package referenz;


import java.util.*;

public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        if (grid == null || grid.length < 3 || grid[0].length < 3) {
            return 0;
        }
        int rows = grid.length;
        int cols = grid[0].length;
        int count = 0;
        for (int i = 0; i <= rows - 3; i++) {
            for (int j = 0; j <= cols - 3; j++) {
                if (isMagic(grid, i, j)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isMagic(int[][] g, int r, int c) {
        // Center of a 3x3 magic square with numbers 1..9 must be 5
        if (g[r + 1][c + 1] != 5) {
            return false;
        }

        boolean[] seen = new boolean[10]; // indices 1..9
        int sum = 0;

        // Check rows and collect numbers
        for (int i = 0; i < 3; i++) {
            int rowSum = 0;
            for (int j = 0; j < 3; j++) {
                int val = g[r + i][c + j];
                if (val < 1 || val > 9) {
                    return false;
                }
                if (seen[val]) {
                    return false;
                }
                seen[val] = true;
                rowSum += val;
            }
            if (i == 0) {
                sum = rowSum; // target sum
            } else if (rowSum != sum) {
                return false;
            }
        }

        // Check columns
        for (int j = 0; j < 3; j++) {
            int colSum = 0;
            for (int i = 0; i < 3; i++) {
                colSum += g[r + i][c + j];
            }
            if (colSum != sum) {
                return false;
            }
        }

        // Check diagonals
        int diag1 = g[r][c] + g[r + 1][c + 1] + g[r + 2][c + 2];
        int diag2 = g[r][c + 2] + g[r + 1][c + 1] + g[r + 2][c];
        return diag1 == sum && diag2 == sum;
    }
}

