public class Solution {
    public int[][] flipAndInvertImage(int[][] image) {
        if (image == null) {
            return null;
        }
        int rows = image.length;
        for (int i = 0; i < rows; i++) {
            int left = 0;
            int right = image[i].length - 1;
            while (left <= right) {
                // Invert values using XOR with 1
                int leftVal = image[i][left] ^ 1;
                int rightVal = image[i][right] ^ 1;
                // Swap the inverted values
                image[i][left] = rightVal;
                image[i][right] = leftVal;
                left++;
                right--;
            }
        }
        return image;
    }
}

