import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    /**
     * Returns the number of car fleets that will arrive at the destination.
     *
     * @param target   the distance to the destination (in miles)
     * @param position array where position[i] is the starting position of the i‑th car
     * @param speed    array where speed[i] is the speed of the i‑th car (in miles per hour)
     * @return the number of distinct car fleets that reach the destination
     */
    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        if (n == 0) {
            return 0;
        }

        // Pair each car's position with its time to reach the target.
        Car[] cars = new Car[n];
        for (int i = 0; i < n; i++) {
            double time = (double) (target - position[i]) / speed[i];
            cars[i] = new Car(position[i], time);
        }

        // Sort cars by starting position in descending order (furthest from target first).
        Arrays.sort(cars, Comparator.comparingInt((Car c) -> c.pos).reversed());

        int fleets = 0;
        double lastFleetTime = -1.0; // time of the fleet that is currently ahead

        for (Car car : cars) {
            // If this car's arrival time is greater than the time of the fleet ahead,
            // it cannot catch up and thus forms a new fleet.
            if (car.time > lastFleetTime) {
                fleets++;
                lastFleetTime = car.time;
            }
            // else: car joins the fleet ahead (no action needed)
        }

        return fleets;
    }

    /** Simple container for a car's position and its time to reach the target. */
    private static class Car {
        int pos;
        double time;

        Car(int pos, double time) {
            this.pos = pos;
            this.time = time;
        }
    }
}

