import java.util.*;

public class Solution {
    // Union-Find data structure
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return;
            // union by size
            if (size[rootA] < size[rootB]) {
                parent[rootA] = rootB;
                size[rootB] += size[rootA];
            } else {
                parent[rootB] = rootA;
                size[rootA] += size[rootB];
            }
        }

        int getSize(int x) {
            return size[find(x)];
        }
    }

    /**
     * Returns the size of the largest island after flipping at most one 0 to 1.
     *
     * @param grid n x n binary matrix
     * @return maximum possible island size
     */
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;

        UnionFind uf = new UnionFind(n * n);
        // Directions: up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // First pass: union all existing 1-cells
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    int id = r * n + c;
                    for (int k = 0; k < 4; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            int nid = nr * n + nc;
                            uf.union(id, nid);
                        }
                    }
                }
            }
        }

        // Map each root to its island size (already stored in uf.size, but we need quick lookup)
        Map<Integer, Integer> islandSize = new HashMap<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    int id = r * n + c;
                    int root = uf.find(id);
                    islandSize.put(root, uf.getSize(root));
                }
            }
        }

        int max = 0;
        // If there is at least one island, initialize max with the largest existing island
        for (int sz : islandSize.values()) {
            max = Math.max(max, sz);
        }

        // Second pass: try flipping each 0
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) {
                    Set<Integer> seen = new HashSet<>();
                    int potential = 1; // the flipped cell itself
                    for (int k = 0; k < 4; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];
                        if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                            int nid = nr * n + nc;
                            int root = uf.find(nid);
                            if (seen.add(root)) {
                                potential += islandSize.get(root);
                            }
                        }
                    }
                    max = Math.max(max, potential);
                }
            }
        }

        // Edge case: all cells are 1
        if (max == 0) {
            return n * n;
        }
        return max;
    }
}

