import java.util.*;

public class Solution {
    public int[] shortestToChar(String s, char c) {
        int n = s.length();
        int[] answer = new int[n];
        int prev = Integer.MIN_VALUE / 2; // a very small number

        // First pass: left to right
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == c) {
                prev = i;
            }
            answer[i] = i - prev;
        }

        // Second pass: right to left
        int next = Integer.MAX_VALUE / 2; // a very large number
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == c) {
                next = i;
            }
            answer[i] = Math.min(answer[i], next - i);
        }

        return answer;
    }
}

