import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        int m = group.length;
        // dp[people][profit] = number of ways
        int[][] dp = new int[n + 1][minProfit + 1];
        dp[0][0] = 1; // no members, zero profit

        for (int idx = 0; idx < m; idx++) {
            int need = group[idx];
            int earn = profit[idx];
            // iterate backwards to avoid reuse within same crime
            for (int people = n; people >= need; people--) {
                for (int p = minProfit; p >= 0; p--) {
                    int newProfit = Math.min(minProfit, p + earn);
                    dp[people][newProfit] = (dp[people][newProfit] + dp[people - need][p]) % MOD;
                }
            }
        }

        int result = 0;
        for (int people = 0; people <= n; people++) {
            result = (result + dp[people][minProfit]) % MOD;
        }
        return result;
    }
}

