public class Solution {
    public int maxDistToClosest(int[] seats) {
        int maxDist = 0;
        int lastOccupied = -1; // index of the last seen occupied seat

        for (int i = 0; i < seats.length; i++) {
            if (seats[i] == 1) {
                if (lastOccupied == -1) {
                    // All seats before i are empty
                    maxDist = i; // distance from start to first occupied seat
                } else {
                    // Seats between lastOccupied and i are empty
                    int dist = (i - lastOccupied) / 2;
                    if (dist > maxDist) {
                        maxDist = dist;
                    }
                }
                lastOccupied = i;
            }
        }

        // Handle trailing empty seats after the last occupied seat
        if (lastOccupied != -1 && lastOccupied < seats.length - 1) {
            int trailingDist = seats.length - 1 - lastOccupied;
            if (trailingDist > maxDist) {
                maxDist = trailingDist;
            }
        }

        return maxDist;
    }
}

