public class Solution {
    public String maskPII(String s) {
        if (s == null) {
            return "";
        }
        if (s.indexOf('@') != -1) {
            // Email masking
            String[] parts = s.split("@");
            String name = parts[0].toLowerCase();
            String domain = parts[1].toLowerCase();
            StringBuilder sb = new StringBuilder();
            sb.append(name.charAt(0))
              .append("*****")
              .append(name.charAt(name.length() - 1))
              .append("@")
              .append(domain);
            return sb.toString();
        } else {
            // Phone number masking
            StringBuilder digits = new StringBuilder();
            for (char c : s.toCharArray()) {
                if (Character.isDigit(c)) {
                    digits.append(c);
                }
            }
            int total = digits.length();
            String lastFour = digits.substring(total - 4);
            int countryLen = total - 10; // number of digits in country code (0-3)

            StringBuilder sb = new StringBuilder();
            if (countryLen == 0) {
                sb.append("***-***-").append(lastFour);
            } else {
                sb.append('+');
                for (int i = 0; i < countryLen; i++) {
                    sb.append('*');
                }
                sb.append("-***-***-").append(lastFour);
            }
            return sb.toString();
        }
    }
}

