import java.util.HashSet;

public class Solution {
    public int[] fairCandySwap(int[] aliceSizes, int[] bobSizes) {
        int sumAlice = 0;
        for (int v : aliceSizes) sumAlice += v;
        int sumBob = 0;
        for (int v : bobSizes) sumBob += v;

        // The difference that needs to be compensated by the swap
        int diff = (sumAlice - sumBob) / 2; // x - y = diff

        HashSet<Integer> bobSet = new HashSet<>();
        for (int v : bobSizes) {
            bobSet.add(v);
        }

        for (int x : aliceSizes) {
            int y = x - diff;
            if (bobSet.contains(y)) {
                return new int[]{x, y};
            }
        }

        // According to the problem statement, a solution always exists.
        // This return will never be reached, but the compiler requires it.
        return new int[0];
    }
}

