public class Solution {
    private static final int[] A = {4, 3, 2, 1}; // amounts of A in 25‑ml units
    private static final int[] B = {0, 1, 2, 3}; // amounts of B in 25‑ml units

    public double soupServings(int n) {
        // For large n the probability is effectively 1.
        if (n > 4800) {
            return 1.0;
        }
        // Convert milliliters to 25‑ml units, rounding up.
        int m = (n + 24) / 25;
        double[][] memo = new double[m + 1][m + 1];
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= m; j++) {
                memo[i][j] = -1.0;
            }
        }
        return dfs(m, m, memo);
    }

    private double dfs(int a, int b, double[][] memo) {
        if (a <= 0 && b <= 0) {
            // both soups empty at the same time
            return 0.5;
        }
        if (a <= 0) {
            // soup A empty first
            return 1.0;
        }
        if (b <= 0) {
            // soup B empty first
            return 0.0;
        }
        if (memo[a][b] >= 0) {
            return memo[a][b];
        }
        double prob = 0.0;
        for (int k = 0; k < 4; k++) {
            prob += dfs(a - A[k], b - B[k], memo);
        }
        prob *= 0.25; // each operation is chosen with equal probability
        memo[a][b] = prob;
        return prob;
    }
}

