import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    public List<String> findAndReplacePattern(String[] words, String pattern) {
        List<String> result = new ArrayList<>();
        for (String word : words) {
            if (matches(word, pattern)) {
                result.add(word);
            }
        }
        return result;
    }

    private boolean matches(String word, String pattern) {
        if (word.length() != pattern.length()) {
            return false;
        }
        int[] mapPatternToWord = new int[26];
        int[] mapWordToPattern = new int[26];
        Arrays.fill(mapPatternToWord, -1);
        Arrays.fill(mapWordToPattern, -1);

        for (int i = 0; i < word.length(); i++) {
            int pIdx = pattern.charAt(i) - 'a';
            int wIdx = word.charAt(i) - 'a';

            if (mapPatternToWord[pIdx] == -1 && mapWordToPattern[wIdx] == -1) {
                mapPatternToWord[pIdx] = wIdx;
                mapWordToPattern[wIdx] = pIdx;
            } else if (mapPatternToWord[pIdx] != wIdx || mapWordToPattern[wIdx] != pIdx) {
                return false;
            }
        }
        return true;
    }
}

package referenz;


public class Solution {
    public double new21Game(int n, int k, int w) {
        // If Alice never draws any card, she always has 0 points.
        if (k == 0) {
            return 1.0;
        }
        // dp[i] – probability of having exactly i points at some moment.
        double[] dp = new double[n + 1];
        dp[0] = 1.0;
        double windowSum = 1.0; // sum of the last w dp values that can reach the next state
        for (int i = 1; i <= n; i++) {
            dp[i] = windowSum / w;
            // Only states with points < k can continue drawing.
            if (i < k) {
                windowSum += dp[i];
            }
            // Remove the value that slides out of the window.
            if (i - w >= 0) {
                windowSum -= dp[i - w];
            }
        }
        double ans = 0.0;
        for (int i = k; i <= n; i++) {
            ans += dp[i];
        }
        return ans;
    }
}

