import java.util.Map;
import java.util.TreeMap;

public class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (groupSize <= 0) {
            return false;
        }
        if (hand.length % groupSize != 0) {
            return false;
        }

        // Count occurrences using a TreeMap to keep keys sorted
        TreeMap<Integer, Integer> countMap = new TreeMap<>();
        for (int card : hand) {
            countMap.put(card, countMap.getOrDefault(card, 0) + 1);
        }

        while (!countMap.isEmpty()) {
            // smallest available card
            int start = countMap.firstKey();
            // try to build a consecutive group starting from 'start'
            for (int i = 0; i < groupSize; i++) {
                int cur = start + i;
                Integer curCount = countMap.get(cur);
                if (curCount == null) {
                    // missing required card
                    return false;
                }
                if (curCount == 1) {
                    countMap.remove(cur);
                } else {
                    countMap.put(cur, curCount - 1);
                }
            }
        }

        return true;
    }
}

package referenz;


public class Solution {
    public int longestMountain(int[] arr) {
        int n = arr.length;
        if (n < 3) {
            return 0;
        }

        int[] up = new int[n];
        int[] down = new int[n];

        // up[i] = length of strictly increasing sequence ending at i (excluding i)
        for (int i = 1; i < n; i++) {
            if (arr[i] > arr[i - 1]) {
                up[i] = up[i - 1] + 1;
            } else {
                up[i] = 0;
            }
        }

        // down[i] = length of strictly decreasing sequence starting at i (excluding i)
        for (int i = n - 2; i >= 0; i--) {
            if (arr[i] > arr[i + 1]) {
                down[i] = down[i + 1] + 1;
            } else {
                down[i] = 0;
            }
        }

        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            if (up[i] > 0 && down[i] > 0) { // i can be a peak
                int len = up[i] + down[i] + 1;
                if (len > maxLen) {
                    maxLen = len;
                }
            }
        }

        return maxLen;
    }
}

