import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Solution {
    private static class TrieNode {
        TrieNode[] child = new TrieNode[26];
    }

    public int minimumLengthEncoding(String[] words) {
        // Remove duplicates to avoid redundant work
        Set<String> uniqueWords = new HashSet<>();
        for (String w : words) {
            uniqueWords.add(w);
        }

        TrieNode root = new TrieNode();
        // Map each word's terminal node to its length
        Map<TrieNode, Integer> nodeLengthMap = new HashMap<>();

        for (String word : uniqueWords) {
            TrieNode node = root;
            // Insert characters in reverse order
            for (int i = word.length() - 1; i >= 0; i--) {
                int idx = word.charAt(i) - 'a';
                if (node.child[idx] == null) {
                    node.child[idx] = new TrieNode();
                }
                node = node.child[idx];
            }
            // Store the length for this terminal node
            nodeLengthMap.put(node, word.length());
        }

        int totalLength = 0;
        // Only words whose terminal node has no children contribute to the encoding
        for (Map.Entry<TrieNode, Integer> entry : nodeLengthMap.entrySet()) {
            TrieNode node = entry.getKey();
            boolean isLeaf = true;
            for (TrieNode child : node.child) {
                if (child != null) {
                    isLeaf = false;
                    break;
                }
            }
            if (isLeaf) {
                totalLength += entry.getValue() + 1; // plus one for the '#'
            }
        }

        return totalLength;
    }
}

