import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        // Remove the outer parentheses
        String inner = s.substring(1, s.length() - 1);
        List<String> result = new ArrayList<>();

        // Split the string into two non‑empty parts
        for (int i = 1; i < inner.length(); i++) {
            String leftPart = inner.substring(0, i);
            String rightPart = inner.substring(i);

            List<String> leftCandidates = generateNumbers(leftPart);
            List<String> rightCandidates = generateNumbers(rightPart);

            for (String left : leftCandidates) {
                for (String right : rightCandidates) {
                    result.add("(" + left + ", " + right + ")");
                }
            }
        }

        return result;
    }

    /**
     * Generates all valid representations of a numeric string according to the
     * problem constraints (no extraneous leading/trailing zeros, at least one digit
     * before a decimal point, etc.).
     */
    private List<String> generateNumbers(String num) {
        List<String> candidates = new ArrayList<>();
        int n = num.length();

        // Single digit numbers are always valid as they are.
        if (n == 1) {
            candidates.add(num);
            return candidates;
        }

        boolean leadingZero = num.charAt(0) == '0';
        boolean trailingZero = num.charAt(n - 1) == '0';

        // If both leading and trailing zeros exist, no valid representation.
        if (leadingZero && trailingZero) {
            return candidates; // empty
        }

        // Case: leading zero but not trailing zero -> only one decimal form "0.xxx"
        if (leadingZero) {
            // Must place decimal after the first digit.
            candidates.add("0." + num.substring(1));
            return candidates;
        }

        // Case: trailing zero but not leading zero -> only integer form allowed
        if (trailingZero) {
            candidates.add(num); // integer only
            return candidates;
        }

        // No leading or trailing zeros: integer itself and all possible decimal insertions
        candidates.add(num); // integer form
        for (int i = 1; i < n; i++) {
            String left = num.substring(0, i);
            String right = num.substring(i);
            candidates.add(left + "." + right);
        }

        return candidates;
    }
}

