        int currentWidth = 0;   // width used in the current line

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            int w = widths[ch - 'a']; // width of the current character

            if (currentWidth + w > 100) {
                // start a new line
                lines++;
                currentWidth = w;
            } else {
                currentWidth += w;
            }
        }

        return new int[]{lines, currentWidth};
