import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        if (indices == null || indices.length == 0) {
            return s;
        }

        // Map each index to its position in the original arrays
        Map<Integer, Integer> indexToPos = new HashMap<>();
        for (int i = 0; i < indices.length; i++) {
            indexToPos.put(indices[i], i);
        }

        // Sort a copy of indices to process replacements from left to right
        int[] sortedIdx = Arrays.copyOf(indices, indices.length);
        Arrays.sort(sortedIdx);

        StringBuilder result = new StringBuilder();
        int cur = 0; // current position in the original string

        for (int idx : sortedIdx) {
            int pos = indexToPos.get(idx);
            String src = sources[pos];
            String tgt = targets[pos];

            // If the source matches the substring starting at idx, perform replacement
            if (s.startsWith(src, idx)) {
                // Append unchanged part before this replacement
                result.append(s, cur, idx);
                // Append the target string
                result.append(tgt);
                // Move current pointer past the replaced source substring
                cur = idx + src.length();
            }
            // If it doesn't match, we simply continue; the current pointer stays unchanged
        }

        // Append any remaining part of the original string
        result.append(s.substring(cur));

        return result.toString();
    }
}

