import java.util.*;

public class Solution {
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return;
            // union by size
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        int getSize(int x) {
            int root = find(x);
            return size[root];
        }
    }

    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        int top = total; // virtual top node index

        // copy grid and apply hits (mark bricks to be removed)
        int[][] copy = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, copy[i], 0, n);
        }

        // record which hits actually hit a brick
        boolean[] hitHasBrick = new boolean[hits.length];
        for (int i = 0; i < hits.length; i++) {
            int r = hits[i][0];
            int c = hits[i][1];
            if (copy[r][c] == 1) {
                copy[r][c] = 0;
                hitHasBrick[i] = true;
            }
        }

        UnionFind uf = new UnionFind(total + 1);

        // initial union of remaining bricks
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (copy[r][c] == 1) {
                    int idx = r * n + c;
                    // if on top row, connect to virtual top
                    if (r == 0) {
                        uf.union(idx, top);
                    }
                    // union with up neighbor
                    if (r > 0 && copy[r - 1][c] == 1) {
                        uf.union(idx, (r - 1) * n + c);
                    }
                    // union with left neighbor
                    if (c > 0 && copy[r][c - 1] == 1) {
                        uf.union(idx, r * n + (c - 1));
                    }
                }
            }
        }

        int[] result = new int[hits.length];
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        // process hits in reverse
        for (int i = hits.length - 1; i >= 0; i--) {
            int r = hits[i][0];
            int c = hits[i][1];
            if (!hitHasBrick[i]) {
                result[i] = 0;
                continue;
            }

            int preTopSize = uf.getSize(top);

            // restore the brick
            copy[r][c] = 1;
            int idx = r * n + c;

            // if on top row, connect to virtual top
            if (r == 0) {
                uf.union(idx, top);
            }

            // union with all 4 neighbors if they are bricks
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && copy[nr][nc] == 1) {
                    uf.union(idx, nr * n + nc);
                }
            }

            int postTopSize = uf.getSize(top);
            int fallen = postTopSize - preTopSize - 1; // exclude the brick just added
            result[i] = Math.max(0, fallen);
        }

        return result;
    }
}

