public class Solution {
    public int surfaceArea(int[][] grid) {
        int n = grid.length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int v = grid[i][j];
                if (v == 0) continue;
                // top and bottom
                total += 2;
                // north
                int north = (i == 0) ? 0 : grid[i - 1][j];
                total += Math.max(v - north, 0);
                // south
                int south = (i == n - 1) ? 0 : grid[i + 1][j];
                total += Math.max(v - south, 0);
                // west
                int west = (j == 0) ? 0 : grid[i][j - 1];
                total += Math.max(v - west, 0);
                // east
                int east = (j == n - 1) ? 0 : grid[i][j + 1];
                total += Math.max(v - east, 0);
            }
        }
        return total;
    }
}

