public class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int y, int x) {
        int total = rows * cols;
        int[][] result = new int[total][2];
        int index = 0;

        // Starting position
        int r = y;
        int c = x;
        if (r >= 0 && r < rows && c >= 0 && c < cols) {
            result[index][0] = r;
            result[index][1] = c;
            index++;
        }

        // Directions: east, south, west, north
        int[] dr = {0, 1, 0, -1};
        int[] dc = {1, 0, -1, 0};

        int steps = 1;      // number of steps in current direction
        int dir = 0;        // current direction index

        while (index < total) {
            // Move 'steps' cells in the current direction
            for (int i = 0; i < steps; i++) {
                r += dr[dir];
                c += dc[dir];
                if (r >= 0 && r < rows && c >= 0 && c < cols) {
                    result[index][0] = r;
                    result[index][1] = c;
                    index++;
                    if (index == total) {
                        break;
                    }
                }
            }
            // Turn clockwise
            dir = (dir + 1) % 4;

            // After completing two directions, increase the step count
            if (dir == 0 || dir == 2) {
                steps++;
            }
        }

        return result;
    }
}

