public class Solution {
    public String pushDominoes(String dominoes) {
        // Add sentinel forces to simplify edge handling
        String extended = "L" + dominoes + "R";
        char[] arr = extended.toCharArray();
        int n = arr.length;
        StringBuilder result = new StringBuilder();

        int i = 0; // index of the last non‑dot character
        for (int j = 1; j < n; j++) {
            if (arr[j] == '.') {
                continue;
            }
            int dotsBetween = j - i - 1; // number of '.' between i and j

            // Append the force at position i (skip the leading sentinel)
            if (i > 0) {
                result.append(arr[i]);
            }

            if (arr[i] == arr[j]) {
                // Same direction forces: all become that direction
                for (int k = 0; k < dotsBetween; k++) {
                    result.append(arr[i]);
                }
            } else if (arr[i] == 'L' && arr[j] == 'R') {
                // Forces are moving away from each other: remain upright
                for (int k = 0; k < dotsBetween; k++) {
                    result.append('.');
                }
            } else { // arr[i] == 'R' && arr[j] == 'L'
                // Opposite forces: fill half R, half L, middle stays '.' if odd
                for (int k = 0; k < dotsBetween / 2; k++) {
                    result.append('R');
                }
                if (dotsBetween % 2 == 1) {
                    result.append('.');
                }
                for (int k = 0; k < dotsBetween / 2; k++) {
                    result.append('L');
                }
            }
            i = j; // move to the next force
        }
        // The trailing sentinel 'R' is not appended, so result length equals original string length
        return result.toString();
    }
}

