 * where two values are connected if they appear consecutively
 * in the linked list {@code head}.
 *
 * @param head the head of the linked list containing unique values
 * @param nums a subset of the values in the linked list
 * @return the number of connected components
 */
public class Solution {

    public int numComponents(ListNode head, int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
        }

        int components = 0;
        ListNode current = head;
        while (current != null) {
            if (set.contains(current.val) &&
                (current.next == null || !set.contains(current.next.val))) {
                components++;
            }
            current = current.next;
        }
        return components;
    }
}

