import java.util.*;

/**
 * Solution for "Smallest Subtree with all the Deepest Nodes".
 */
public class Solution {

    /**
     * Standard binary‑tree node used by LeetCode problems.
     */
    public static class TreeNode {
        public int val;
        public TreeNode left;
        public TreeNode right;

        public TreeNode() {}

        public TreeNode(int val) {
            this.val = val;
        }

        public TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }

    private static class Result {
        int depth;
        TreeNode node;

        Result(int depth, TreeNode node) {
            this.depth = depth;
            this.node = node;
        }
    }

    /**
     * Returns the smallest subtree containing all deepest nodes.
     */
    public TreeNode subtreeWithAllDeepest(TreeNode root) {
        return dfs(root).node;
    }

    private Result dfs(TreeNode node) {
        if (node == null) {
            return new Result(0, null);
        }
        Result left = dfs(node.left);
        Result right = dfs(node.right);

        if (left.depth == right.depth) {
            // current node is the common ancestor of deepest nodes
            return new Result(left.depth + 1, node);
        } else if (left.depth > right.depth) {
            // deepest nodes are in left subtree
            return new Result(left.depth + 1, left.node);
        } else {
            // deepest nodes are in right subtree
            return new Result(right.depth + 1, right.node);
        }
    }
}

