import referenz.Solution.TreeNode;

/**
 * Minimal utility class used by the unit tests.
 * Provides methods to build a binary tree from an array representation
 * and to compare two trees for structural equality.
 */
public class Solution {

    /**
     * Builds a binary tree from a level‑order array representation.
     * {@code null} values denote absent children.
     *
     * @param values level‑order array of node values
     * @return the root of the constructed binary tree
     */
    public static TreeNode fromArray(Integer[] values) {
        if (values == null || values.length == 0) {
            return null;
        }
        TreeNode[] nodes = new TreeNode[values.length];
        for (int i = 0; i < values.length; i++) {
            if (values[i] != null) {
                nodes[i] = new TreeNode(values[i]);
            }
        }
        for (int i = 0; i < values.length; i++) {
            TreeNode current = nodes[i];
            if (current == null) {
                continue;
            }
            int leftIdx = 2 * i + 1;
            int rightIdx = 2 * i + 2;
            if (leftIdx < values.length) {
                current.left = nodes[leftIdx];
            }
            if (rightIdx < values.length) {
                current.right = nodes[rightIdx];
            }
        }
        return nodes[0];
    }

    /**
     * Asserts that two binary trees are structurally identical and contain
     * the same values. Throws {@link AssertionError} if they differ.
     *
     * @param expected the expected tree
     * @param actual   the actual tree produced by the algorithm
     */
    public static void assertTreeEquals(TreeNode expected, TreeNode actual) {
        if (!equals(expected, actual)) {
            throw new AssertionError("Trees are not equal");
        }
    }

    private static boolean equals(TreeNode a, TreeNode b) {
        if (a == null && b == null) {
            return true;
        }
        if (a == null || b == null) {
            return false;
        }
        if (a.val != b.val) {
            return false;
        }
        return equals(a.left, b.left) && equals(a.right, b.right);
    }
}

