import com.github.leetcode.TreeNode;

/**
 * Determines whether two binary trees are leaf‑similar.
 *
 * Two binary trees are considered leaf‑similar if their leaf value sequences
 * (the values of the leaves from left to right) are identical.
 */
public class Solution {

    /**
     * Returns {@code true} if the leaf value sequences of {@code root1} and
     * {@code root2} are exactly the same.
     *
     * @param root1 the root of the first binary tree
     * @param root2 the root of the second binary tree
     * @return {@code true} if both trees have identical leaf sequences,
     *         {@code false} otherwise
     */
    public boolean leafSimilar(TreeNode root1, TreeNode root2) {
        List<Integer> leaves1 = new ArrayList<>();
        List<Integer> leaves2 = new ArrayList<>();
        collectLeaves(root1, leaves1);
        collectLeaves(root2, leaves2);
        return leaves1.equals(leaves2);
    }

    /**
     * Traverses the given tree in a depth‑first left‑to‑right order and records
     * the values of leaf nodes.
     *
     * @param node   the current node (may be {@code null})
     * @param leaves the list that accumulates leaf values
     */
    private void collectLeaves(TreeNode node, List<Integer> leaves) {
        if (node == null) {
            return;
        }
        if (node.left == null && node.right == null) {
            leaves.add(node.val);
        } else {
            collectLeaves(node.left, leaves);
            collectLeaves(node.right, leaves);
        }
    }
}

