public class Solution {
    public int consecutiveNumbersSum(int n) {
        // Remove all factors of 2 because they do not affect the count of odd divisors
        while ((n & 1) == 0) {
            n >>= 1;
        }
        long result = 1;
        int temp = n;
        for (int p = 3; p * p <= temp; p += 2) {
            if (temp % p == 0) {
                int exp = 0;
                while (temp % p == 0) {
                    temp /= p;
                    exp++;
                }
                result *= (exp + 1);
            }
        }
        if (temp > 1) {
            // remaining prime factor
            result *= 2;
        }
        return (int) result;
    }
}

