import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public boolean possibleBipartition(int n, int[][] dislikes) {
        // Build adjacency list for the graph
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] d : dislikes) {
            int a = d[0];
            int b = d[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        // 0 = uncolored, 1 = color A, -1 = color B
        int[] color = new int[n + 1];

        // Process each connected component
        for (int i = 1; i <= n; i++) {
            if (color[i] != 0) {
                continue; // already colored
            }
            // Start BFS from node i
            Queue<Integer> queue = new ArrayDeque<>();
            queue.offer(i);
            color[i] = 1; // assign first color

            while (!queue.isEmpty()) {
                int cur = queue.poll();
                int curColor = color[cur];
                for (int neighbor : graph[cur]) {
                    if (color[neighbor] == 0) {
                        // Assign opposite color to the neighbor
                        color[neighbor] = -curColor;
                        queue.offer(neighbor);
                    } else if (color[neighbor] == curColor) {
                        // Conflict found, not bipartite
                        return false;
                    }
                }
            }
        }

        // All components are bipartite
        return true;
    }
}

