public class Solution {
    public int projectionArea(int[][] grid) {
        int n = grid.length;
        int top = 0;
        int front = 0; // zx plane: max of each row
        int side = 0;  // yz plane: max of each column

        // compute top and front (row max)
        for (int i = 0; i < n; i++) {
            int rowMax = 0;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    top++;
                }
                if (grid[i][j] > rowMax) {
                    rowMax = grid[i][j];
                }
            }
            front += rowMax;
        }

        // compute side (column max)
        for (int j = 0; j < n; j++) {
            int colMax = 0;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] > colMax) {
                    colMax = grid[i][j];
                }
            }
            side += colMax;
        }

        return top + front + side;
    }
}

