        int jobIdx = 0;

        for (int ability : sortedWorkers) {
            // Include all jobs that this worker can do
            while (jobIdx < n && jobs[jobIdx][0] <= ability) {
                maxProfitSoFar = Math.max(maxProfitSoFar, jobs[jobIdx][1]);
                jobIdx++;
            }
            total += maxProfitSoFar;
        }

        return (int) total;
    }
