public class Solution {
    public int maxIncreaseKeepingSkyline(int[][] grid) {
        int n = grid.length;
        if (n == 0) return 0;
        int[] rowMax = new int[n];
        int[] colMax = new int[n];

        // Compute the maximum height for each row and column
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > rowMax[i]) rowMax[i] = grid[i][j];
                if (grid[i][j] > colMax[j]) colMax[j] = grid[i][j];
            }
        }

        int totalIncrease = 0;
        // For each cell, the new height can be at most the minimum of its row and column maxima
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int allowedHeight = Math.min(rowMax[i], colMax[j]);
                totalIncrease += allowedHeight - grid[i][j];
            }
        }

        return totalIncrease;
    }
}

