public class Solution {
    public boolean reorderedPowerOf2(int n) {
        if (n == 0) {
            return false;
        }
        int[] targetCount = digitCount(n);
        // generate powers of two up to 10^10 (covers all possible int digit lengths)
        for (long p = 1; p < 10000000000L; p <<= 1) {
            if (Arrays.equals(targetCount, digitCount((int) p))) {
                return true;
            }
        }
        return false;
    }

    private int[] digitCount(int num) {
        int[] cnt = new int[10];
        while (num > 0) {
            cnt[num % 10]++;
            num /= 10;
        }
        return cnt;
    }
}

