public class Solution {
    public double largestTriangleArea(int[][] points) {
        int n = points.length;
        if (n < 3) {
            return 0.0;
        }
        double maxArea = 0.0;
        for (int i = 0; i < n - 2; i++) {
            int x1 = points[i][0];
            int y1 = points[i][1];
            for (int j = i + 1; j < n - 1; j++) {
