public class Solution {
    public int expressiveWords(String s, String[] words) {
        int count = 0;
        for (String w : words) {
            if (isStretchy(s, w)) {
                count++;
            }
        }
        return count;
    }

    private boolean isStretchy(String s, String w) {
        int i = 0, j = 0;
        int n = s.length(), m = w.length();

        while (i < n && j < m) {
            char cs = s.charAt(i);
            char cw = w.charAt(j);
            if (cs != cw) {
                return false;
            }

            int cntS = 0;
            while (i < n && s.charAt(i) == cs) {
                cntS++;
                i++;
            }

            int cntW = 0;
            while (j < m && w.charAt(j) == cw) {
                cntW++;
                j++;
            }

            if (cntS < 3) {
                if (cntS != cntW) {
                    return false;
                }
            } else {
                if (cntW > cntS) {
                    return false;
                }
                // cntW can be any positive number <= cntS
            }
        }

        return i == n && j == m;
    }
}

