public class Solution {
    public int primePalindrome(int n) {
        if (n <= 2) return 2;
        if (n <= 3) return 3;
        if (n <= 5) return 5;
        if (n <= 7) return 7;
        if (n <= 11) return 11;

        // generate palindromes of length 1..9 (since answer ≤ 2*10^8)
        for (int len = 1; len <= 9; len++) {
            // skip even lengths except 2 (the palindrome 11) which is already handled
            if (len % 2 == 0 && len != 2) continue;

            int halfLen = (len + 1) / 2;               // number of digits we need to generate
            int start = (int) Math.pow(10, halfLen - 1);
            int end = (int) Math.pow(10, halfLen);

            for (int i = start; i < end; i++) {
                int pal = createPalindrome(i, len % 2 == 1);
                if (pal >= n && isPrime(pal)) {
                    return pal;
                }
            }
        }
        // According to problem constraints this line is never reached.
        return -1;
    }

    // Build palindrome from the left half.
    private int createPalindrome(int left, boolean oddLength) {
        int result = left;
        if (oddLength) {
            left /= 10; // skip the middle digit
        }
        while (left > 0) {
            result = result * 10 + (left % 10);
            left /= 10;
        }
        return result;
    }

    // Simple deterministic primality test for numbers up to 2*10^8.
    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num % 2 == 0) return num == 2;
        int sqrt = (int) Math.sqrt(num);
        for (int i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

