import java.util.HashSet;
import java.util.PriorityQueue;
import java.util.Set;

public class Solution {

    private static class Node {
        final String str;
        final int steps;
        final int f; // steps + heuristic

        Node(String str, int steps, int f) {
            this.str = str;
            this.steps = steps;
            this.f = f;
        }
    }

    public int kSimilarity(String a, String b) {
        if (a.equals(b)) {
            return 0;
        }
        int n = a.length();
        PriorityQueue<Node> pq = new PriorityQueue<>((n1, n2) -> Integer.compare(n1.f, n2.f));
        Set<String> visited = new HashSet<>();

        int initHeuristic = heuristic(a, b);
        pq.offer(new Node(a, 0, initHeuristic));
        visited.add(a);

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.str.equals(b)) {
                return cur.steps;
            }

            // find first mismatched position
            int i = 0;
            while (i < n && cur.str.charAt(i) == b.charAt(i)) {
                i++;
            }
            if (i == n) {
                continue; // should not happen because we already checked equality
            }

            char[] arr = cur.str.toCharArray();

            // try to swap position i with a later position j that can fix the mismatch
            for (int j = i + 1; j < n; j++) {
                if (arr[j] == b.charAt(i) && arr[j] != b.charAt(j)) {
                    swap(arr, i, j);
                    String next = new String(arr);
                    if (!visited.contains(next)) {
                        visited.add(next);
                        int h = heuristic(next, b);
                        pq.offer(new Node(next, cur.steps + 1, cur.steps + 1 + h));
                    }
                    swap(arr, i, j); // revert
                }
            }
        }
        return -1; // should never reach here for valid input
    }

    // Heuristic: number of mismatched characters divided by 2 (ceil)
    private int heuristic(String s, String target) {
        int mismatches = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != target.charAt(i)) {
                mismatches++;
            }
        }
        // each swap can fix at most two mismatches
        return (mismatches + 1) / 2;
    }

    private void swap(char[] arr, int i, int j) {
        char tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}

