public class Solution {
    public int minSwap(int[] listA, int[] listB) {
        int n = listA.length;
        // keepPrev: min swaps till i-1 with no swap at i-1
        // swapPrev: min swaps till i-1 with a swap at i-1
        int keepPrev = 0;
        int swapPrev = 1; // we swap the first pair

        for (int i = 1; i < n; i++) {
            int keepCurr = Integer.MAX_VALUE;
            int swapCurr = Integer.MAX_VALUE;

            // Case 1: both sequences are already increasing without swapping at i
            if (listA[i] > listA[i - 1] && listB[i] > listB[i - 1]) {
                keepCurr = Math.min(keepCurr, keepPrev);
                swapCurr = Math.min(swapCurr, swapPrev + 1);
            }

            // Case 2: swapping at i makes the sequences increasing
            if (listA[i] > listB[i - 1] && listB[i] > listA[i - 1]) {
                keepCurr = Math.min(keepCurr, swapPrev);
                swapCurr = Math.min(swapCurr, keepPrev + 1);
            }

            keepPrev = keepCurr;
            swapPrev = swapCurr;
        }

        return Math.min(keepPrev, swapPrev);
    }
}

