import java.util.*;

public class Solution {
    // Union-Find (Disjoint Set Union) structure
    private static class DSU {
        private final int[] parent;
        private final int[] rank;
        private int count; // number of distinct sets

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            count = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) return;

            // union by rank
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
            count--;
        }

        int getCount() {
            return count;
        }
    }

    // Check if two strings are similar according to the problem definition
    private boolean areSimilar(String a, String b) {
        int diff = 0;
        int first = -1, second = -1;
        int len = a.length();

        for (int i = 0; i < len; i++) {
            if (a.charAt(i) != b.charAt(i)) {
                diff++;
                if (diff > 2) {
                    return false;
                }
                if (first == -1) {
                    first = i;
                } else {
                    second = i;
                }
            }
        }

        if (diff == 0) {
            return true; // strings are identical
        }
        // exactly two mismatched positions must be swappable
        return diff == 2 &&
               a.charAt(first) == b.charAt(second) &&
               a.charAt(second) == b.charAt(first);
    }

    public int numSimilarGroups(String[] strs) {
        if (strs == null || strs.length == 0) {
            return 0;
        }

        int n = strs.length;
        DSU dsu = new DSU(n);

        // Compare each pair only once
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (dsu.find(i) != dsu.find(j) && areSimilar(strs[i], strs[j])) {
                    dsu.union(i, j);
                }
            }
        }

        return dsu.getCount();
    }
}

