public class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        // Find the maximum pile size to set the upper bound of binary search
        int maxPile = 0;
        for (int pile : piles) {
            if (pile > maxPile) {
                maxPile = pile;
            }
        }

        int left = 1;          // minimum possible speed
        int right = maxPile;   // maximum possible speed

        while (left < right) {
            int mid = left + (right - left) / 2;
            long hoursNeeded = 0;
            for (int pile : piles) {
                // ceil(pile / mid) without using floating point
                hoursNeeded += (pile + mid - 1) / mid;
                // Early exit if already exceeds h to avoid unnecessary work
                if (hoursNeeded > h) {
                    break;
                }
            }

            if (hoursNeeded <= h) {
                // mid is sufficient, try to find a smaller speed
                right = mid;
            } else {
                // mid is too slow
                left = mid + 1;
            }
        }

        return left;
    }
}

