public class Solution {
    public int uniqueLetterString(String s) {
        int n = s.length();
        int[] prev = new int[n];
        int[] next = new int[n];
        int[] last = new int[256];
        Arrays.fill(last, -1);
        // previous occurrence
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            prev[i] = last[c];
            last[c] = i;
        }
        // next occurrence
        Arrays.fill(last, n);
        for (int i = n - 1; i >= 0; i--) {
            char c = s.charAt(i);
            next[i] = last[c];
            last[c] = i;
        }
        long result = 0L;
        for (int i = 0; i < n; i++) {
            long left = i - prev[i];
            long right = next[i] - i;
            result += left * right;
        }
        return (int) result;
    }
}

