/**
 * Rearranges a binary search tree into an increasing order search tree
 * where each node has only a right child.
 */
public class Solution {
    /**
     * Returns the new root of the rearranged tree.
     *
     * @param root the root of the original BST
     * @return the leftmost node of the original tree, now the root of the
     *         increasing order tree
     */
    public TreeNode increasingBST(TreeNode root) {
        // Dummy node simplifies linking during in‑order traversal
        TreeNode dummy = new TreeNode(0);
        // Use a single‑element array to hold the previous node reference
        TreeNode[] prev = new TreeNode[]{dummy};

        inorder(root, prev);

        // The right child of dummy is the new root
        return dummy.right;
    }

    /**
     * In‑order traversal that rewires nodes to form a right‑skewed tree.
     *
     * @param node current node being visited
     * @param prev array holding the last node added to the new tree
     */
    private void inorder(TreeNode node, TreeNode[] prev) {
        if (node == null) {
            return;
        }
        // Traverse left subtree
        inorder(node.left, prev);

        // Process current node: detach left child and attach to the right of prev
        node.left = null;
        prev[0].right = node;
        prev[0] = node; // move prev forward

        // Traverse right subtree
        inorder(node.right, prev);
    }
}

