public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long totalScore = 0L;

        // Ensure the first column is all 1s by conceptually flipping rows where grid[i][0] == 0
        for (int col = 0; col < n; col++) {
            int onesCount = 0;
            for (int row = 0; row < m; row++) {
                // If the first element of the row was 0, the whole row is considered flipped
                int val = grid[row][col];
                if (grid[row][0] == 0) {
                    val ^= 1; // flip the current cell
                }
                if (val == 1) {
                    onesCount++;
                }
            }
            // For columns other than the first, we may flip the column to maximize 1s
            int maxOnes = Math.max(onesCount, m - onesCount);
            totalScore += (long) maxOnes << (n - 1 - col);
        }

        return (int) totalScore;
    }
}

