public class Solution {
    /**
     * Returns an array where answer[i] is the sum of distances from node i to all other nodes.
     *
     * @param n     number of nodes in the tree (0 .. n-1)
     * @param edges edges of the tree, each edge is a two‑element int array [u, v]
     * @return array of length n with the required sums
     */
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        // Build adjacency list
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }

        int[] subtreeSize = new int[n];   // number of nodes in the subtree rooted at i (including i)
        int[] dp = new int[n];            // sum of distances from i to all nodes in its subtree
        int[] answer = new int[n];        // final result

        // First DFS (post‑order) to compute subtreeSize and dp for root = 0
        dfsPost(0, -1, graph, subtreeSize, dp);

        // Second DFS (pre‑order) to compute answer for every node using re‑rooting technique
        dfsPre(0, -1, graph, subtreeSize, dp, answer, n);

        return answer;
    }

    // Post‑order traversal: fills subtreeSize and dp for each node
    private void dfsPost(int node, int parent,
                         List<Integer>[] graph,
                         int[] subtreeSize,
                         int[] dp) {
        subtreeSize[node] = 1; // count itself
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            dfsPost(nei, node, graph, subtreeSize, dp);
            subtreeSize[node] += subtreeSize[nei];
            dp[node] += dp[nei] + subtreeSize[nei]; // distance to each node in child's subtree increases by 1
        }
    }

    // Pre‑order traversal: computes answer for each node using parent's answer
    private void dfsPre(int node, int parent,
                        List<Integer>[] graph,
                        int[] subtreeSize,
                        int[] dp,
                        int[] answer,
                        int n) {
        // For the root (node == 0) answer is dp[0] (sum of distances to all nodes)
        if (parent == -1) {
            answer[node] = dp[node];
        } else {
            // Re‑rooting formula:
            // answer[node] = answer[parent] - subtreeSize[node] + (n - subtreeSize[node])
            answer[node] = answer[parent] - subtreeSize[node] + (n - subtreeSize[node]);
        }

        for (int nei : graph[node]) {
            if (nei == parent) continue;
            dfsPre(nei, node, graph, subtreeSize, dp, answer, n);
        }
    }
}

