import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    private static final int MOD = 1_000_000_007;
    private long[] xs;          // compressed x coordinates
    private int[] count;        // cover count for each segment tree node
    private long[] coverLen;    // total covered length for each node

    public int rectangleArea(int[][] rectangles) {
        if (rectangles == null || rectangles.length == 0) return 0;

        // 1. collect all unique x coordinates
        List<Integer> xList = new ArrayList<>();
        for (int[] r : rectangles) {
            xList.add(r[0]);
            xList.add(r[2]);
        }
        xs = xList.stream().distinct().sorted().mapToLong(Integer::longValue).toArray();

        // 2. build events
        class Event {
            int y;
            int x1Idx;
            int x2Idx;
            int type; // +1 entering, -1 leaving
            Event(int y, int x1Idx, int x2Idx, int type) {
                this.y = y;
                this.x1Idx = x1Idx;
                this.x2Idx = x2Idx;
                this.type = type;
            }
        }
        List<Event> events = new ArrayList<>();
        for (int[] r : rectangles) {
            int x1Idx = Arrays.binarySearch(xs, r[0]);
            int x2Idx = Arrays.binarySearch(xs, r[2]);
            events.add(new Event(r[1], x1Idx, x2Idx - 1, 1));   // entering at y1
            events.add(new Event(r[3], x1Idx, x2Idx - 1, -1));  // leaving at y2
        }
        events.sort((a, b) -> Integer.compare(a.y, b.y));

        // 3. segment tree initialization
        int segCount = xs.length - 1; // number of elementary x-intervals
        count = new int[segCount * 4];
        coverLen = new long[segCount * 4];

        long area = 0;
        int prevY = events.get(0).y;
        for (Event e : events) {
            int curY = e.y;
            long deltaY = curY - prevY;
            long coveredX = coverLen[1]; // total covered length at current sweep line
            area = (area + (coveredX % MOD) * (deltaY % MOD)) % MOD;

            // update segment tree with current event
            update(1, 0, segCount - 1, e.x1Idx, e.x2Idx, e.type);
            prevY = curY;
        }
        return (int) (area % MOD);
    }

    // update segment tree on interval [l, r] (indices of xs segments)
    private void update(int node, int l, int r, int ql, int qr, int val) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            count[node] += val;
        } else {
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ql, qr, val);
            update(node << 1 | 1, mid + 1, r, ql, qr, val);
        }

        if (count[node] > 0) {
            // fully covered
            coverLen[node] = xs[r + 1] - xs[l];
        } else {
            if (l == r) {
                coverLen[node] = 0;
            } else {
                coverLen[node] = coverLen[node << 1] + coverLen[node << 1 | 1];
            }
        }
    }
}

