import java.util.HashSet;
import java.util.Set;

public class Solution {
    public boolean buddyStrings(String s, String goal) {
        // If lengths differ, impossible
        if (s == null || goal == null || s.length() != goal.length()) {
            return false;
        }

        // If strings are identical, we need at least one duplicate character
        if (s.equals(goal)) {
            Set<Character> seen = new HashSet<>();
            for (char c : s.toCharArray()) {
                if (!seen.add(c)) {
                    // Found a duplicate character, swapping the two identical chars works
                    return true;
                }
            }
            // No duplicate characters, any swap would change the string
            return false;
        }

        // Find the positions where the characters differ
        int first = -1, second = -1;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != goal.charAt(i)) {
                if (first == -1) {
                    first = i;
                } else if (second == -1) {
                    second = i;
                } else {
                    // More than two mismatches
                    return false;
                }
            }
        }

        // Exactly two mismatched positions must exist and cross‑match after swap
        return second != -1
                && s.charAt(first) == goal.charAt(second)
                && s.charAt(second) == goal.charAt(first);
    }
}

