import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int largestOverlap(int[][] img1, int[][] img2) {
        int n = img1.length;
        // Collect coordinates of 1s in both images
        int[][] ones1 = new int[n * n][2];
        int[][] ones2 = new int[n * n][2];
        int cnt1 = 0, cnt2 = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (img1[i][j] == 1) {
                    ones1[cnt1][0] = i;
                    ones1[cnt1][1] = j;
                    cnt1++;
                }
                if (img2[i][j] == 1) {
                    ones2[cnt2][0] = i;
                    ones2[cnt2][1] = j;
                    cnt2++;
                }
            }
        }

        if (cnt1 == 0 || cnt2 == 0) {
            return 0;
        }

        Map<Long, Integer> shiftCount = new HashMap<>();
        int maxOverlap = 0;

        for (int i = 0; i < cnt1; i++) {
            int x1 = ones1[i][0];
            int y1 = ones1[i][1];
            for (int j = 0; j < cnt2; j++) {
                int x2 = ones2[j][0];
                int y2 = ones2[j][1];
                int dx = x1 - x2;
                int dy = y1 - y2;
                // Encode pair (dx, dy) into a single long key
                long key = ((long) dx << 32) ^ (dy & 0xffffffffL);
                int newCount = shiftCount.getOrDefault(key, 0) + 1;
                shiftCount.put(key, newCount);
                if (newCount > maxOverlap) {
                    maxOverlap = newCount;
                }
            }
        }

        return maxOverlap;
    }
}

