public class Solution {
    public int[] advantageCount(int[] nums1, int[] nums2) {
        int n = nums1.length;
        // Count occurrences of each number in nums1
        TreeMap<Integer, Integer> map = new TreeMap<>();
        for (int num : nums1) {
            map.merge(num, 1, Integer::sum);
        }

        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            // Find the smallest number in nums1 that is greater than nums2[i]
            Integer key = map.higherKey(nums2[i]);
            if (key == null) {
                // No such number, use the smallest available
                key = map.firstKey();
            }
            result[i] = key;
            // Decrease count or remove the key
            int cnt = map.get(key);
            if (cnt == 1) {
                map.remove(key);
            } else {
                map.put(key, cnt - 1);
            }
        }
        return result;
    }
}

