public class Solution {
    public String shiftingLetters(String s, int[][] shifts) {
        if (s == null || s.isEmpty()) {
            return s;
        }
        int n = s.length();
        int[] diff = new int[n + 1]; // difference array for range updates

        for (int[] shiftInfo : shifts) {
            int start = shiftInfo[0];
            int end = shiftInfo[1];
            int direction = shiftInfo[2];
            int delta = direction == 1 ? 1 : -1; // forward = +1, backward = -1

            diff[start] += delta;
            if (end + 1 < n) {
                diff[end + 1] -= delta;
            }
        }

        char[] result = s.toCharArray();
        int cumulative = 0;
        for (int i = 0; i < n; i++) {
            cumulative += diff[i];
            int shift = ((cumulative % 26) + 26) % 26; // normalize to [0,25]
            int originalPos = result[i] - 'a';
            int newPos = (originalPos + shift) % 26;
            result[i] = (char) ('a' + newPos);
        }

        return new String(result);
    }
}

