import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int distinctSequences(int n) {
        // dp[prev1][prev2] = number of ways ending with prev1 (last roll) and prev2 (second last roll)
        long[][] dp = new long[7][7];
        dp[0][0] = 1; // before any roll, both previous values are "empty" (0)

        for (int pos = 1; pos <= n; pos++) {
            long[][] next = new long[7][7];
            for (int prev1 = 0; prev1 <= 6; prev1++) {
                for (int prev2 = 0; prev2 <= 6; prev2++) {
                    long curWays = dp[prev1][prev2];
                    if (curWays == 0) continue;
                    for (int cur = 1; cur <= 6; cur++) {
                        // distance constraint: cannot repeat within distance 1 or 2
                        if (cur == prev1 || cur == prev2) continue;
                        // adjacency GCD constraint (only if there is a previous roll)
                        if (prev1 != 0 && gcd(cur, prev1) != 1) continue;
                        // transition to new state: last becomes cur, second last becomes prev1
                        next[cur][prev1] = (next[cur][prev1] + curWays) % MOD;
                    }
                }
            }
            dp = next;
        }

        long ans = 0;
        for (int prev1 = 0; prev1 <= 6; prev1++) {
            for (int prev2 = 0; prev2 <= 6; prev2++) {
                ans = (ans + dp[prev1][prev2]) % MOD;
            }
        }
        return (int) ans;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

