public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int numberOfWays(int startPos, int endPos, int k) {
        long d = (long) endPos - (long) startPos;          // required net displacement
        // r = (k + d) / 2 must be integer and 0 <= r <= k
        long sum = k + d;
        if ((sum & 1L) != 0L) {                            // not divisible by 2
            return 0;
        }
        long r = sum / 2;
        long l = k - r;
        if (r < 0 || l < 0) {
            return 0;
        }

        // compute C(k, r) modulo MOD
        int n = k;
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1L;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        long result = fact[n];
        result = result * invFact[(int) r] % MOD;
        result = result * invFact[(int) l] % MOD;

        return (int) result;
    }

    private long modPow(long base, long exp) {
        long res = 1L;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1L) == 1L) {
                res = (res * b) % MOD;
            }
            b = (b * b) % MOD;
            e >>= 1;
        }
        return res;
    }
}

