/**
 * Solution for the "All Nodes Distance K in Binary Tree" problem.
 */
public class Solution {

    /**
     * Returns the values of all nodes that are exactly k edges away from the target node.
     *
     * @param root   the root of the binary tree
     * @param target the target node
     * @param k      the required distance
     * @return a list containing the values of all nodes at distance k from target
     */
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        if (root == null) {
            return new ArrayList<>();
        }

        // Build a map from each node to its parent
        Map<TreeNode, TreeNode> parentMap = new HashMap<>();
        buildParentMap(root, null, parentMap);

        // BFS starting from the target node
        Deque<TreeNode> queue = new ArrayDeque<>();
        Set<TreeNode> visited = new HashSet<>();

        queue.offer(target);
        visited.add(target);
        int currentDist = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            if (currentDist == k) {
                List<Integer> result = new ArrayList<>(size);
                for (TreeNode node : queue) {
                    result.add(node.val);
                }
                return result;
            }

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.left != null && visited.add(node.left)) {
                    queue.offer(node.left);
                }
                if (node.right != null && visited.add(node.right)) {
                    queue.offer(node.right);
                }
                TreeNode parent = parentMap.get(node);
                if (parent != null && visited.add(parent)) {
                    queue.offer(parent);
                }
            }
            currentDist++;
        }

        // If k is larger than the height of the tree, return empty list
        return new ArrayList<>();
    }

    /**
     * Helper method to fill the parent map using DFS.
     *
     * @param node      current node
     * @param parent    parent of the current node
     * @param parentMap map to store child → parent relationships
     */
    private void buildParentMap(TreeNode node, TreeNode parent, Map<TreeNode, TreeNode> parentMap) {
        if (node == null) {
            return;
        }
        parentMap.put(node, parent);
        buildParentMap(node.left, node, parentMap);
        buildParentMap(node.right, node, parentMap);
    }
}

