import java.util.HashSet;
import java.util.Set;

public class Solution {
    public long countExcellentPairs(int[] nums, int k) {
        // Keep only distinct numbers
        Set<Integer> unique = new HashSet<>();
        for (int num : nums) {
            unique.add(num);
        }

        // Maximum possible popcount for an int (32 bits) – using a safe upper bound
        final int MAX_BITS = 64;
        long[] countByPop = new long[MAX_BITS + 1];

        // Count how many unique numbers have each popcount
        for (int val : unique) {
            int pop = Integer.bitCount(val);
            countByPop[pop]++;
        }

        // Build suffix sums: suffix[i] = total numbers with popcount >= i
        long[] suffix = new long[MAX_BITS + 2];
        for (int i = MAX_BITS; i >= 0; i--) {
            suffix[i] = suffix[i + 1] + countByPop[i];
        }

        long answer = 0L;
        for (int p = 0; p <= MAX_BITS; p++) {
            long cntP = countByPop[p];
            if (cntP == 0) continue;

            int need = k - p;
            if (need < 0) need = 0;
            if (need > MAX_BITS) continue; // no partner can satisfy the condition

            answer += cntP * suffix[need];
        }

        return answer;
    }
}

