public class Solution {
    public long taskSchedulerII(int[] tasks, int space) {
        // Map to store the last day a particular task type was performed
        Map<Integer, Long> lastDay = new HashMap<>();
        long currentDay = 0L; // days are counted starting from 1

        for (int task : tasks) {
            long earliestPossible = currentDay + 1; // we can always move to the next day
            if (lastDay.containsKey(task)) {
                // Need to wait 'space' days after the previous occurrence
                long nextAllowed = lastDay.get(task) + (long) space + 1;
                if (nextAllowed > earliestPossible) {
                    earliestPossible = nextAllowed;
                }
            }
            // Perform the task on 'earliestPossible' day
            currentDay = earliestPossible;
            lastDay.put(task, currentDay);
        }

        return currentDay;
    }
}

