import java.util.*;

public class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;
        // dp[j] = minimum cost to reach column j of the current row
        int[] dp = new int[n];
        // Initialize with the first row values
        for (int j = 0; j < n; j++) {
            dp[j] = grid[0][j];
        }

        // Process each subsequent row
        for (int i = 1; i < m; i++) {
            int[] newDp = new int[n];
            Arrays.fill(newDp, Integer.MAX_VALUE);
            for (int curCol = 0; curCol < n; curCol++) {
                int cellValue = grid[i][curCol];
                int bestPrev = Integer.MAX_VALUE;
                for (int prevCol = 0; prevCol < n; prevCol++) {
                    int prevCost = dp[prevCol];
                    int move = moveCost[grid[i - 1][prevCol]][curCol];
                    int total = prevCost + move;
                    if (total < bestPrev) {
                        bestPrev = total;
                    }
                }
                newDp[curCol] = cellValue + bestPrev;
            }
            dp = newDp;
        }

        // Find the minimum cost in the last row
        int answer = Integer.MAX_VALUE;
        for (int cost : dp) {
            if (cost < answer) {
                answer = cost;
            }
        }
        return answer;
    }
}

