import java.util.HashMap;
import java.util.Map;

public class Solution {
    public long countBadPairs(int[] nums) {
        int n = nums.length;
        // total number of pairs (i, j) with i < j
        long totalPairs = (long) n * (n - 1) / 2;

        // count good pairs where (j - i) == (nums[j] - nums[i])
        // This is equivalent to (i - nums[i]) == (j - nums[j])
        Map<Long, Long> freq = new HashMap<>();
        for (int i = 0; i < n; i++) {
            long key = (long) i - (long) nums[i];
            freq.put(key, freq.getOrDefault(key, 0L) + 1);
        }

        long goodPairs = 0L;
        for (long cnt : freq.values()) {
            // number of ways to choose 2 indices with the same key
            goodPairs += cnt * (cnt - 1) / 2;
        }

        // bad pairs = total pairs - good pairs
        return totalPairs - goodPairs;
    }
}

