import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maximumSum(int[] nums) {
        // Map from digit sum to an array of two largest numbers with that digit sum.
        // index 0 -> largest, index 1 -> second largest
        Map<Integer, int[]> best = new HashMap<>();

        for (int num : nums) {
            int dSum = digitSum(num);
            int[] pair = best.getOrDefault(dSum, new int[]{-1, -1});

            if (num > pair[0]) {
                // shift current largest to second place
                pair[1] = pair[0];
                pair[0] = num;
            } else if (num > pair[1]) {
                pair[1] = num;
            }
            best.put(dSum, pair);
        }

        int max = -1;
        for (int[] pair : best.values()) {
            if (pair[1] != -1) { // we have at least two numbers with this digit sum
                int sum = pair[0] + pair[1];
                if (sum > max) {
                    max = sum;
                }
            }
        }
        return max;
    }

    // Helper method to compute sum of digits of a positive integer
    private int digitSum(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
}

