    /**
     * Builds a binary tree from a level‑order representation.
     * {@code data} may contain {@code null} entries to denote missing children.
     *
     * Example:
     *   List.of(1, 0, 1, null, 0, 0, 1)
     *   creates the tree used in LeetCode problem 814.
     *
     * @param data level‑order list of node values (may contain nulls)
     * @return the root of the constructed binary tree, or {@code null} if the list is empty
     */
    public static TreeNode create(List<Integer> data) {
        if (data == null || data.isEmpty()) {
            return null;
        }

        Iterator<Integer> it = data.iterator();
        TreeNode root = new TreeNode(it.next());
        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);

        while (it.hasNext()) {
            TreeNode parent = queue.poll();

            // left child
            Integer leftVal = it.next();
            if (leftVal != null) {
                parent.left = new TreeNode(leftVal);
                queue.add(parent.left);
            }

            // right child (if present)
            if (it.hasNext()) {
                Integer rightVal = it.next();
                if (rightVal != null) {
                    parent.right = new TreeNode(rightVal);
                    queue.add(parent.right);
                }
            }
        }

        return root;
    }
}

