import java.util.HashMap;
import java.util.Map;

public class Solution {
    private static class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            // union by size
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        int componentSize(int x) {
            return size[find(x)];
        }
    }

    public long countPairs(int n, int[][] edges) {
        UnionFind uf = new UnionFind(n);
        for (int[] edge : edges) {
            uf.union(edge[0], edge[1]);
        }

        // Gather sizes of each distinct component
        Map<Integer, Integer> compSizeMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = uf.find(i);
            compSizeMap.put(root, uf.size[root]); // size array already holds component size for root
        }

        long totalPairs = (long) n * (n - 1) / 2;
        long intraPairs = 0L;
        for (int sz : compSizeMap.values()) {
            intraPairs += (long) sz * (sz - 1) / 2;
        }

        return totalPairs - intraPairs;
    }
}

