import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    /**
     * Returns the maximum length of a consecutive subarray of robots whose total cost does not exceed
     * the given budget. The total cost of a window [l, r] is:
     *   max(chargeTimes[l..r]) + (r - l + 1) * sum(runningCosts[l..r])
     *
     * @param chargeTimes  array of charge costs
     * @param runningCosts array of running costs
     * @param budget       maximum allowed total cost
     * @return maximum number of consecutive robots that can be run within the budget
     */
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        Deque<Integer> maxDeque = new ArrayDeque<>(); // stores indices, decreasing chargeTimes
        long sumRunning = 0L;
        int left = 0;
        int best = 0;

        for (int right = 0; right < n; right++) {
            // add new robot to the window
            sumRunning += runningCosts[right];

            // maintain decreasing deque for max charge time
            while (!maxDeque.isEmpty() && chargeTimes[maxDeque.peekLast()] <= chargeTimes[right]) {
                maxDeque.pollLast();
            }
            maxDeque.offerLast(right);

            // shrink window while it violates the budget
            while (left <= right) {
                long maxCharge = chargeTimes[maxDeque.peekFirst()];
                long totalCost = maxCharge + (long) (right - left + 1) * sumRunning;
                if (totalCost <= budget) {
                    break;
                }
                // remove leftmost element
                if (maxDeque.peekFirst() == left) {
                    maxDeque.pollFirst();
                }
                sumRunning -= runningCosts[left];
                left++;
            }

            // update answer
            best = Math.max(best, right - left + 1);
        }

        return best;
    }
}

