public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        int n = edges.length;
        int[] dist1 = new int[n];
        int[] dist2 = new int[n];
        final int INF = Integer.MAX_VALUE;

        // initialize distances with INF
        for (int i = 0; i < n; i++) {
            dist1[i] = INF;
            dist2[i] = INF;
        }

        // compute distances from node1
        computeDistances(edges, node1, dist1, INF);
        // compute distances from node2
        computeDistances(edges, node2, dist2, INF);

        int bestNode = -1;
        int bestDist = INF;

        for (int i = 0; i < n; i++) {
            if (dist1[i] == INF || dist2[i] == INF) {
                continue; // unreachable from at least one start node
            }
            int curMax = Math.max(dist1[i], dist2[i]);
            if (curMax < bestDist) {
                bestDist = curMax;
                bestNode = i;
            }
        }

        return bestNode;
    }

    private void computeDistances(int[] edges, int start, int[] dist, int INF) {
        int steps = 0;
        int node = start;
        while (node != -1 && dist[node] == INF) {
            dist[node] = steps;
            steps++;
            node = edges[node];
        }
        // If we encounter a node already visited (dist[node] != INF), we stop to avoid cycles.
    }
}

