import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Solution {
    public boolean matchReplacement(String s, String sub, char[][] mappings) {
        if (sub.length() > s.length()) {
            return false;
        }

        // Build replacement map: old -> set of possible new characters
        Map<Character, Set<Character>> replaceMap = new HashMap<>();
        for (char[] pair : mappings) {
            if (pair == null || pair.length < 2) continue;
            char oldChar = pair[0];
            char newChar = pair[1];
            replaceMap.computeIfAbsent(oldChar, k -> new HashSet<>()).add(newChar);
        }

        int n = s.length();
        int m = sub.length();

        // Try every possible starting position in s
        for (int i = 0; i <= n - m; i++) {
            boolean ok = true;
            for (int j = 0; j < m; j++) {
                char cSub = sub.charAt(j);
                char cS = s.charAt(i + j);
                if (cSub == cS) {
                    continue; // direct match
                }
                Set<Character> possible = replaceMap.get(cSub);
                if (possible == null || !possible.contains(cS)) {
                    ok = false;
                    break; // this window cannot work
                }
            }
            if (ok) {
                return true; // found a valid window
            }
        }
        return false; // no window satisfied the condition
    }
}

