public class Solution {
    public boolean canChange(String start, String target) {
        if (start.length() != target.length()) {
            return false;
        }

        int n = start.length();
        // Remove '_' and compare the order of L and R
        StringBuilder sBuilder = new StringBuilder();
        StringBuilder tBuilder = new StringBuilder();

        for (int i = 0; i < n; i++) {
            char c = start.charAt(i);
            if (c != '_') {
                sBuilder.append(c);
            }
        }
        for (int i = 0; i < n; i++) {
            char c = target.charAt(i);
            if (c != '_') {
                tBuilder.append(c);
            }
        }

        if (!sBuilder.toString().equals(tBuilder.toString())) {
            return false;
        }

        // Check positional constraints using two pointers
        int i = 0, j = 0;
        while (i < n && j < n) {
            // skip blanks in start
            while (i < n && start.charAt(i) == '_') {
                i++;
            }
            // skip blanks in target
            while (j < n && target.charAt(j) == '_') {
                j++;
            }
            if (i == n || j == n) {
                break;
            }

            char cs = start.charAt(i);
            char ct = target.charAt(j);

            // characters are the same because we already checked the order
            if (cs == 'L' && i < j) {
                // L can only move left, so its index in start must be >= index in target
                return false;
            }
            if (cs == 'R' && i > j) {
                // R can only move right, so its index in start must be <= index in target
                return false;
            }

            i++;
            j++;
        }

        // After processing, any remaining non-blank characters would have been caught earlier
        return true;
    }
}

