public class Solution {
    public long minimumReplacement(int[] nums) {
        int n = nums.length;
        long operations = 0L;
        // target is the maximum allowed value for the current element to keep array non‑decreasing
        long target = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            long cur = nums[i];
            if (cur <= target) {
                // no split needed, just update target to current value
                target = cur;
                continue;
            }
            // need to split cur into parts so that each part <= target
            long parts = (cur + target - 1) / target; // ceil(cur / target)
            operations += parts - 1; // each split adds one operation
            // after splitting, the largest piece is ceil(cur / parts) <= target
            // the smallest (leftmost) piece is floor(cur / parts)
            target = cur / parts; // floor division
        }
        return operations;
    }
}

