public class Solution {
    public int minNumberOfHours(int initialEnergy, int initialExperience, int[] energy, int[] experience) {
        int trainingHours = 0;
        int curEnergy = initialEnergy;
        int curExp = initialExperience;
        int n = energy.length;
        for (int i = 0; i < n; i++) {
            // Ensure enough energy
            if (curEnergy <= energy[i]) {
                int need = energy[i] - curEnergy + 1;
                trainingHours += need;
                curEnergy += need;
            }
            // Ensure enough experience
            if (curExp <= experience[i]) {
                int need = experience[i] - curExp + 1;
                trainingHours += need;
                curExp += need;
            }
            // Fight the opponent
            curEnergy -= energy[i];
            curExp += experience[i];
        }
        return trainingHours;
    }
}

