public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0;
        long sum2 = 0;
        int[] diff = new int[n]; // nums2[i] - nums1[i]
        for (int i = 0; i < n; i++) {
            sum1 += nums1[i];
            sum2 += nums2[i];
            diff[i] = nums2[i] - nums1[i];
        }

        int maxGainForSum1 = maxSubarraySum(diff);               // improve sum1
        int maxGainForSum2 = maxSubarraySumNeg(diff);            // improve sum2 (swap roles)

        long candidate1 = sum1 + maxGainForSum1;
        long candidate2 = sum2 + maxGainForSum2;

        return (int) Math.max(candidate1, candidate2);
    }

    // Kadane's algorithm for maximum subarray sum (non‑negative result)
    private int maxSubarraySum(int[] arr) {
        int maxEndingHere = 0;
        int maxSoFar = 0;
        for (int x : arr) {
            maxEndingHere = Math.max(0, maxEndingHere + x);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }
        return maxSoFar;
    }

    // Maximum subarray sum of the negated array, i.e., max subarray sum of -arr
    private int maxSubarraySumNeg(int[] arr) {
        int maxEndingHere = 0;
        int maxSoFar = 0;
        for (int x : arr) {
            int neg = -x;
            maxEndingHere = Math.max(0, maxEndingHere + neg);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }
        return maxSoFar;
    }
}

