import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int peopleAwareOfSecret(int n, int delay, int forget) {
        int size = n + Math.max(delay, forget) + 2;
        int[] startSharing = new int[size];
        int[] forgetOnDay = new int[size];

        // day 1 initial person
        if (1 + delay < size) {
            startSharing[1 + delay] = 1;
        }
        if (1 + forget < size) {
            forgetOnDay[1 + forget] = 1;
        }

        long active = 1;          // people who currently know the secret
        long shareable = 0;       // people that can share today

        for (int day = 2; day <= n; day++) {
            // people become sharers today
            shareable = (shareable + startSharing[day]) % MOD;
            // people stop sharing because they forget today
            shareable = (shareable - forgetOnDay[day] + MOD) % MOD;

            // all current sharers teach a new person today
            long newPeople = shareable;

            // update the number of people that still know the secret
            active = (active + newPeople - forgetOnDay[day] + MOD) % MOD;

            // schedule future sharing / forgetting for the newly taught people
            int shareDay = day + delay;
            int forgetDay = day + forget;
            if (shareDay < size) {
                startSharing[shareDay] = (int) ((startSharing[shareDay] + newPeople) % MOD);
            }
            if (forgetDay < size) {
                forgetOnDay[forgetDay] = (int) ((forgetOnDay[forgetDay] + newPeople) % MOD);
            }
        }

        return (int) active;
    }
}

