import java.util.*;

public class Solution {
    public int distributeCookies(int[] c, int k) {
        int n = c.length;
        if (k >= n) {
            int max = 0;
            for (int v : c) max = Math.max(max, v);
            return max;
        }

        int totalMask = 1 << n;
        int[] sum = new int[totalMask];
        for (int mask = 1; mask < totalMask; mask++) {
            int lsb = mask & -mask;                     // lowest set bit
            int idx = Integer.numberOfTrailingZeros(lsb);
            sum[mask] = sum[mask ^ lsb] + c[idx];
        }

        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[totalMask][k + 1];
        for (int[] row : dp) Arrays.fill(row, INF);
        dp[0][0] = 0;

        for (int mask = 1; mask < totalMask; mask++) {
            for (int child = 1; child <= k; child++) {
                // iterate over submasks of mask
                // submask will be the set of bags given to the current child
                for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                    int prev = dp[mask ^ sub][child - 1];
                    if (prev == INF) continue;
                    int curUnfair = Math.max(prev, sum[sub]);
                    if (curUnfair < dp[mask][child]) {
                        dp[mask][child] = curUnfair;
                    }
                }
            }
        }

        return dp[totalMask - 1][k];
    }
}

