public class Solution {
    public int garbageCollection(String[] garbage, int[] travel) {
        int n = garbage.length;
        // Prefix sum of travel distances: distance from house 0 to house i
        int[] prefix = new int[n];
        prefix[0] = 0;
        for (int i = 1; i < n; i++) {
            prefix[i] = prefix[i - 1] + travel[i - 1];
        }

        // Last occurrence index for each garbage type
        int lastM = -1, lastP = -1, lastG = -1;
        long totalGarbage = 0;

        for (int i = 0; i < n; i++) {
            String s = garbage[i];
            totalGarbage += s.length(); // each character is one unit of time
            for (int j = 0; j < s.length(); j++) {
                char c = s.charAt(j);
                if (c == 'M') lastM = i;
                else if (c == 'P') lastP = i;
                else if (c == 'G') lastG = i;
            }
        }

        long totalTime = totalGarbage;
        if (lastM != -1) totalTime += prefix[lastM];
        if (lastP != -1) totalTime += prefix[lastP];
        if (lastG != -1) totalTime += prefix[lastG];

        return (int) totalTime;
    }
}

