import java.util.*;

public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();

        // Find previous smaller element for each index
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            left[i] = stack.isEmpty() ? -1 : stack.peek();
            stack.push(i);
        }

        stack.clear();

        // Find next smaller element for each index
        for (int i = n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) {
                stack.pop();
            }
            right[i] = stack.isEmpty() ? n : stack.peek();
            stack.push(i);
        }

        // Check each position for a feasible subarray length
        for (int i = 0; i < n; i++) {
            int maxLen = right[i] - left[i] - 1; // longest subarray where nums[i] is the minimum
            if (nums[i] <= 0) {
                continue; // avoid division by zero or non‑positive minima
            }
            int minK = threshold / nums[i] + 1; // smallest k such that nums[i] > threshold / k
            if (minK <= maxLen) {
                return minK; // any valid size is acceptable
            }
        }

        return -1; // no valid subarray found
    }
}

