public class Solution {
    public int shortestSequence(int[] rolls, int k) {
        int completedRounds = 0;
        int distinctSeen = 0;
        int currentMark = 1;
        int[] mark = new int[k + 1]; // default 0

        for (int roll : rolls) {
            if (roll < 1 || roll > k) {
                continue; // safety, though problem guarantees valid values
            }
            if (mark[roll] != currentMark) {
                mark[roll] = currentMark;
                distinctSeen++;
                if (distinctSeen == k) {
                    completedRounds++;
                    distinctSeen = 0;
                    currentMark++; // start tracking a new round
                }
            }
        }
        return completedRounds + 1;
    }
}

