/**
 * Generates an m x n matrix filled with the values from the linked list
 * in clockwise spiral order starting from the top‑left corner.
 * Remaining cells are filled with -1.
 */
public class Solution {

    /**
     * Generates an m x n matrix filled with the values from the linked list
     * in clockwise spiral order starting from the top‑left corner.
     * Remaining cells are filled with -1.
     *
     * @param m    number of rows
     * @param n    number of columns
     * @param head head of the singly linked list
     * @return the generated matrix
     */
    public int[][] spiralMatrix(int m, int n, ListNode head) {
        int[][] matrix = new int[m][n];
        int top = 0, bottom = m - 1;
        int left = 0, right = n - 1;
        ListNode cur = head;

        while (top <= bottom && left <= right) {
            // left → right
            for (int col = left; col <= right; col++) {
                if (cur != null) {
                    matrix[top][col] = cur.val;
                    cur = cur.next;
                } else {
                    matrix[top][col] = -1;
                }
            }
            top++;
            if (top > bottom) break;

            // top → bottom
            for (int row = top; row <= bottom; row++) {
                if (cur != null) {
                    matrix[row][right] = cur.val;
                    cur = cur.next;
                } else {
                    matrix[row][right] = -1;
                }
            }
            right--;
            if (left > right) break;

            // right → left
            for (int col = right; col >= left; col--) {
                if (cur != null) {
                    matrix[bottom][col] = cur.val;
                    cur = cur.next;
                } else {
                    matrix[bottom][col] = -1;
                }
            }
            bottom--;
            if (top > bottom) break;

            // bottom → top
            for (int row = bottom; row >= top; row--) {
                if (cur != null) {
                    matrix[row][left] = cur.val;
                    cur = cur.next;
                } else {
                    matrix[row][left] = -1;
                }
            }
            left++;
        }

        return matrix;
    }
}

