import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countPaths(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dp = new int[m][n];

        List<int[]> cells = new ArrayList<>(m * n);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells.add(new int[]{grid[i][j], i, j});
            }
        }

        Collections.sort(cells, Comparator.comparingInt(a -> a[0]));

        long answer = 0;
        int[] dirX = {-1, 0, 1, 0};
        int[] dirY = {0, 1, 0, -1};

        for (int[] cell : cells) {
            int value = cell[0];
            int x = cell[1];
            int y = cell[2];

            long ways = 1; // path consisting only of this cell
            for (int d = 0; d < 4; d++) {
                int nx = x + dirX[d];
                int ny = y + dirY[d];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] < value) {
                    ways += dp[nx][ny];
                }
            }
            ways %= MOD;
            dp[x][y] = (int) ways;
            answer += ways;
            if (answer >= MOD) {
                answer -= MOD;
            }
        }

        return (int) answer;
    }
}

