import java.util.*;

public class Solution {
    // number n as an array, splitted by each digit
    public int countSpecialNumbers(int n) {
        // Convert n to digit array
        String s = Integer.toString(n);
        int len = s.length();
        int[] digits = new int[len];
        for (int i = 0; i < len; i++) {
            digits[i] = s.charAt(i) - '0';
        }

        // memo[pos][mask][started] for states where tight == false
        long[][][] memo = new long[len + 1][1 << 10][2];
        for (int i = 0; i <= len; i++) {
            for (int m = 0; m < (1 << 10); m++) {
                Arrays.fill(memo[i][m], -1L);
            }
        }

        // depth‑first search with memoization
        long dfs = dfs(0, 0, true, false, digits, memo);
        // result fits into int according to problem constraints
        return (int) dfs;
    }

    private long dfs(int pos, int mask, boolean tight, boolean started,
                     int[] digits, long[][][] memo) {
        if (pos == digits.length) {
            // count only numbers that have at least one non‑leading digit
            return started ? 1L : 0L;
        }

        if (!tight && memo[pos][mask][started ? 1 : 0] != -1L) {
            return memo[pos][mask][started ? 1 : 0];
        }

        int limit = tight ? digits[pos] : 9;
        long res = 0L;

        for (int d = 0; d <= limit; d++) {
            boolean nextStarted = started || d != 0;
            boolean nextTight = tight && d == limit;

            if (!nextStarted) {
                // still leading zeros, mask unchanged
                res += dfs(pos + 1, mask, nextTight, false, digits, memo);
            } else {
                // if digit already used, skip
                if ((mask & (1 << d)) != 0) {
                    continue;
                }
                res += dfs(pos + 1, mask | (1 << d), nextTight, true, digits, memo);
            }
        }

        if (!tight) {
            memo[pos][mask][started ? 1 : 0] = res;
        }
        return res;
    }
}

