import java.util.HashSet;
import java.util.Set;

public class Solution {
    /**
     * Returns the number of distinct valid company names that can be formed.
     *
     * @param ideas an array of distinct strings representing possible names
     * @return the count of valid company name combinations
     */
    public long distinctNames(String[] ideas) {
        // Store suffixes (the part after the first character) for each starting letter
        @SuppressWarnings("unchecked")
        Set<String>[] groups = new Set[26];
        for (int i = 0; i < 26; i++) {
            groups[i] = new HashSet<>();
        }

        for (String idea : ideas) {
            char first = idea.charAt(0);
            String suffix = idea.substring(1);
            groups[first - 'a'].add(suffix);
        }

        long result = 0L;

        // Compare each pair of different starting letters
        for (int i = 0; i < 26; i++) {
            for (int j = i + 1; j < 26; j++) {
                Set<String> setI = groups[i];
                Set<String> setJ = groups[j];

                if (setI.isEmpty() || setJ.isEmpty()) {
                    continue;
                }

                // Count suffixes that are unique to each set
                int uniqueInI = 0;
                for (String s : setI) {
                    if (!setJ.contains(s)) {
                        uniqueInI++;
                    }
                }

                int uniqueInJ = 0;
                for (String s : setJ) {
                    if (!setI.contains(s)) {
                        uniqueInJ++;
                    }
                }

                // Each ordered pair (i, j) and (j, i) yields a valid name
                result += 2L * uniqueInI * uniqueInJ;
            }
        }

        return result;
    }
}

