public class Solution {
    public long countSubarrays(int[] nums, long k) {
        if (k <= 0) {
            return 0L;
        }
        long answer = 0L;
        long sum = 0L;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            while (left <= right) {
                long len = right - left + 1L;
                // ceil(k / len) without overflow
                long ceil = k / len;
                if (k % len != 0) {
                    ceil++;
                }
                if (sum < ceil) {
                    break;
                }
                sum -= nums[left];
                left++;
            }
            answer += (right - left + 1L);
        }
        return answer;
    }
}

