import java.util.Arrays;

public class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        // Compute the greatest common divisor (GCD) of all elements in numsDivide
        int g = 0;
        for (int val : numsDivide) {
            g = gcd(g, val);
        }

        // Sort nums to consider the smallest possible candidates first
        Arrays.sort(nums);

        // Find the first element that divides the GCD
        for (int i = 0; i < nums.length; i++) {
            if (g % nums[i] == 0) {
                // All elements before index i need to be deleted
                return i;
            }
        }

        // No element in nums can divide all elements of numsDivide
        return -1;
    }

    // Helper method to compute GCD using Euclidean algorithm
    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return Math.abs(a);
    }
}

