import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

public class Solution {
    public long kSum(int[] nums, int k) {
        long base = 0L;                     // sum of all non‑negative numbers
        List<Long> penalties = new ArrayList<>(); // absolute values that reduce the sum when taken

        for (int v : nums) {
            if (v >= 0) {
                base += v;
                if (v != 0) {
                    penalties.add((long) v); // excluding a positive number reduces the sum by v
                }
            } else {
                penalties.add((long) (-v)); // including a negative number reduces the sum by -v
            }
        }

        Collections.sort(penalties);       // smallest penalties first
        int n = penalties.size();

        // Min‑heap storing pairs {currentPenaltySum, indexInPenalties}
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));

        // The empty subset gives penalty sum 0 (the largest possible original sum)
        if (n > 0) {
            pq.offer(new long[]{penalties.get(0), 0});
        }

        // We already have the smallest penalty sum (0)
        if (k == 1) {
            return base;                    // the largest subsequence sum
        }

        long curPenalty = 0L;
        int count = 1;                      // number of penalty sums we have taken (including 0)

        while (count < k) {
            long[] top = pq.poll();
            curPenalty = top[0];
            int idx = (int) top[1];
            count++;

            if (idx + 1 < n) {
                // Replace the penalty at position idx with the next one
                long newSumReplace = curPenalty - penalties.get(idx) + penalties.get(idx + 1);
                pq.offer(new long[]{newSumReplace, idx + 1});

                // Keep the current penalties and also add the next one
                long newSumAdd = curPenalty + penalties.get(idx + 1);
                pq.offer(new long[]{newSumAdd, idx + 1});
            }
        }

        // The k‑th largest original sum equals base minus the (k‑1)‑th smallest penalty sum
        return base - curPenalty;
    }
}

