import java.util.*;

public class Solution {
    // Union-Find structure to manage active segments
    private class UF {
        private final int[] parent;
        private final long[] sum;
        private final boolean[] active;
        private final int n;

        public UF(int n) {
            this.n = n;
            this.parent = new int[n];
            this.sum = new long[n];
            this.active = new boolean[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        private int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        private void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) {
                return;
            }
            // merge rb into ra
            parent[rb] = ra;
            sum[ra] += sum[rb];
        }

        public void insert(int x, int value) {
            active[x] = true;
            parent[x] = x;
            sum[x] = value;

            if (x - 1 >= 0 && active[x - 1]) {
                union(x, x - 1);
            }
            if (x + 1 < n && active[x + 1]) {
                union(x, x + 1);
            }
        }

        public long getSegmentSum(int x) {
            return sum[find(x)];
        }
    }

    /**
     * Returns the maximum segment sum after each removal.
     *
     * @param nums          the original array of positive integers
     * @param removeQueries indices to be removed in order
     * @return an array where answer[i] is the maximum segment sum after the i‑th removal
     */
    public long[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        UF uf = new UF(n);
        long[] answer = new long[n];
        long currentMax = 0L;

        // Process removals in reverse: add elements back
        for (int i = n - 1; i >= 0; i--) {
            answer[i] = currentMax;
            int idx = removeQueries[i];
            uf.insert(idx, nums[idx]);
            currentMax = Math.max(currentMax, uf.getSegmentSum(idx));
        }
        return answer;
    }
}

