public class Solution {
    public int longestIdealString(String s, int k) {
        // dp for each character a..z storing the longest ideal subsequence ending with that character
        int[] best = new int[26];
        int result = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            int cur = s.charAt(i) - 'a';
            int left = Math.max(0, cur - k);
            int right = Math.min(25, cur + k);
            int maxPrev = 0;
            for (int ch = left; ch <= right; ch++) {
                if (best[ch] > maxPrev) {
                    maxPrev = best[ch];
                }
            }
            int curLen = maxPrev + 1;
            if (curLen > best[cur]) {
                best[cur] = curLen;
            }
            if (curLen > result) {
                result = curLen;
            }
        }
        return result;
    }
}

