public class Solution {
    public int fillCups(int[] amount) {
        // Calculate total number of cups needed
        int total = amount[0] + amount[1] + amount[2];
        // Find the maximum cups of a single type
        int max = Math.max(amount[0], Math.max(amount[1], amount[2]));
        // The minimum seconds is the larger of:
        // 1) the max single type (since we can fill at most one cup of that type per second)
