import java.util.*;

public class Solution {
    private List<Integer>[] graph;
    private int[] parent;
    private int[] tin;
    private int[] tout;
    private int[] subXor;
    private int timer;
    private int totalXor;

    public int minimumScore(int[] nums, int[][] edges) {
        int n = nums.length;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        parent = new int[n];
        tin = new int[n];
        tout = new int[n];
        subXor = new int[n];
        timer = 0;

        dfs(0, -1, nums);

        totalXor = subXor[0];
        int answer = Integer.MAX_VALUE;

        // Pre‑process edges to know child direction according to the rooted tree
        int m = edges.length;
        int[] edgeChild = new int[m]; // child node of each edge
        for (int i = 0; i < m; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            if (parent[u] == v) {
                edgeChild[i] = u;
            } else {
                edgeChild[i] = v; // parent[v] == u
            }
        }

        // Try every edge as the first removed edge
        for (int i = 0; i < m; i++) {
            int childA = edgeChild[i];
            int xorA = subXor[childA];          // component A (subtree of childA)
            int xorB = totalXor ^ xorA;         // component B (the rest)

            // Try every other edge as the second removed edge
            for (int j = 0; j < m; j++) {
                if (i == j) continue; // cannot remove the same edge twice
                int child = edgeChild[j];

                // Determine which component the second edge belongs to
                if (isInSubtree(child, childA)) {
                    // Edge inside component A
                    int xorC1 = subXor[child];
                    int xorC2 = xorA ^ subXor[child];
                    int xorC3 = xorB;
                    int cur = score(xorC1, xorC2, xorC3);
                    if (cur < answer) answer = cur;
                } else if (!isInSubtree(childA, child)) {
                    // Edge inside component B (neither endpoint is inside A)
                    int xorC1 = subXor[child];
                    int xorC2 = xorB ^ subXor[child];
                    int xorC3 = xorA;
                    int cur = score(xorC1, xorC2, xorC3);
                    if (cur < answer) answer = cur;
                }
                // Edges that would cross the two components cannot exist
                // because the tree is already split by the first removed edge.
            }
        }

        return answer;
    }

    private void dfs(int node, int par, int[] nums) {
        parent[node] = par;
        tin[node] = timer++;
        int curXor = nums[node];
        for (int nb : graph[node]) {
            if (nb == par) continue;
            dfs(nb, node, nums);
            curXor ^= subXor[nb];
        }
        subXor[node] = curXor;
        tout[node] = timer++;
    }

    private boolean isInSubtree(int v, int u) {
        // returns true if v is inside the subtree rooted at u
        return tin[u] <= tin[v] && tout[v] <= tout[u];
    }

    private int score(int a, int b, int c) {
        int max = Math.max(a, Math.max(b, c));
        int min = Math.min(a, Math.min(b, c));
        return max - min;
    }
}

