public class Solution {
    public String largestPalindromic(String num) {
        int[] cnt = new int[10];
        for (int i = 0; i < num.length(); i++) {
            cnt[num.charAt(i) - '0']++;
        }

        StringBuilder left = new StringBuilder();

        // Build the left half using pairs of digits from 9 to 1 first
        for (int d = 9; d >= 1; d--) {
            int pairs = cnt[d] / 2;
            if (pairs > 0) {
                left.append(String.valueOf(d).repeat(pairs));
                cnt[d] -= pairs * 2;
            }
        }

        // Add zero pairs only if we already have a non‑zero digit in the left half
        if (left.length() > 0) {
            int zeroPairs = cnt[0] / 2;
            if (zeroPairs > 0) {
                left.append("0".repeat(zeroPairs));
                cnt[0] -= zeroPairs * 2;
            }
        }

        // Choose the middle digit (the largest remaining digit, if any)
        char middle = 0;
        boolean hasMiddle = false;
        for (int d = 9; d >= 0; d--) {
            if (cnt[d] > 0) {
                middle = (char) ('0' + d);
                hasMiddle = true;
                break;
            }
        }

        // Assemble the palindrome
        StringBuilder result = new StringBuilder();
        result.append(left);
        if (hasMiddle) {
            result.append(middle);
        }
        result.append(left.reverse());

        // If nothing was added (possible when num consists only of zeros), return "0"
        if (result.length() == 0) {
            return "0";
        }
        return result.toString();
    }
}

