public class Solution {
    public boolean validPartition(int[] nums) {
        int n = nums.length;
        // dp[i] indicates whether the prefix of length i can be partitioned validly
        boolean[] dp = new boolean[n + 1];
        dp[0] = true; // empty prefix is valid

        for (int i = 2; i <= n; i++) {
            // Check a subarray of length 2 with equal elements
            if (dp[i - 2] && nums[i - 2] == nums[i - 1]) {
                dp[i] = true;
            }

            if (i >= 3) {
                // Check a subarray of length 3 with all equal elements
                if (dp[i - 3] && nums[i - 3] == nums[i - 2] && nums[i - 2] == nums[i - 1]) {
                    dp[i] = true;
                }
                // Check a subarray of length 3 with consecutive increasing elements
                if (dp[i - 3] && nums[i - 3] + 1 == nums[i - 2] && nums[i - 2] + 1 == nums[i - 1]) {
                    dp[i] = true;
                }
            }
        }

        return dp[n];
    }
}

