import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int idealArrays(int n, int maxValue) {
        // pre‑compute smallest prime factor for every number up to maxValue
        int[] spf = new int[maxValue + 1];
        for (int i = 2; i <= maxValue; i++) {
            if (spf[i] == 0) {
                for (int j = i; j <= maxValue; j += i) {
                    if (spf[j] == 0) spf[j] = i;
                }
            }
        }

        // factorials up to n + max exponent (worst case n + log2(maxValue))
        int limit = n + maxValue; // safe upper bound, still small (≤ 2·10⁴ for given constraints)
        long[] fact = new long[limit + 1];
        long[] invFact = new long[limit + 1];
        fact[0] = 1;
        for (int i = 1; i <= limit; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[limit] = modPow(fact[limit], MOD - 2);
        for (int i = limit; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        long answer = 0;
        // iterate over every possible final value
        for (int v = 1; v <= maxValue; v++) {
            long ways = 1;
            int x = v;
            while (x > 1) {
                int p = spf[x];
                int cnt = 0;
                while (x % p == 0) {
                    x /= p;
                    cnt++;
                }
                // multiply by C(cnt + n - 1, n - 1)
                ways = ways * nCr(cnt + n - 1, n - 1, fact, invFact) % MOD;
            }
            answer += ways;
            if (answer >= MOD) answer -= MOD;
        }
        return (int) answer;
    }

    private static long nCr(int N, int K, long[] fact, long[] invFact) {
        if (K < 0 || K > N) return 0;
        return fact[N] * invFact[K] % MOD * invFact[N - K] % MOD;
    }

    private static long modPow(long base, long exp) {
        long res = 1;
        long b = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = res * b % MOD;
            }
            b = b * b % MOD;
            exp >>= 1;
        }
        return res;
    }
}

