import java.util.Arrays;

public class Solution {
    public int maximumGroups(int[] grades) {
        // Sort grades to use smallest values first
        Arrays.sort(grades);
        long prevSum = 0;
        int prevSize = 0;
        long curSum = 0;
        int curSize = 0;
        int groups = 0;

        for (int grade : grades) {
            curSum += grade;
            curSize++;

            // Check if we can close the current group
            if (curSize > prevSize && curSum > prevSum) {
                groups++;
                prevSize = curSize;
                prevSum = curSum;
                // reset for next group
                curSize = 0;
                curSum = 0;
            }
        }
        return groups;
    }
}

