        int n = edges.length;
        int[] visited = new int[n]; // 0 = unvisited, otherwise stores traversal id (i+1)
        int[] depth = new int[n];   // step index within current traversal
        int maxCycle = -1;

        for (int i = 0; i < n; i++) {
            if (visited[i] != 0) {
                continue; // already processed in a previous traversal
            }
            int cur = i;
            int step = 0;
            int traversalId = i + 1; // unique id for this walk

            while (cur != -1 && visited[cur] == 0) {
                visited[cur] = traversalId;
                depth[cur] = step;
                step++;
                cur = edges[cur];
            }

            // If we stopped because we reached a node visited in the same traversal,
            // a cycle has been found.
            if (cur != -1 && visited[cur] == traversalId) {
                int cycleLen = step - depth[cur];
                if (cycleLen > maxCycle) {
                    maxCycle = cycleLen;
                }
            }
            // Nodes visited in this traversal remain marked with traversalId,
            // preventing them from being started again.
        }

        return maxCycle;
    }
}

