public class Solution {
    public String greatestLetter(String s) {
        if (s == null || s.isEmpty()) {
            return "";
        }

        boolean[] lower = new boolean[26];
        boolean[] upper = new boolean[26];

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch >= 'a' && ch <= 'z') {
                lower[ch - 'a'] = true;
            } else if (ch >= 'A' && ch <= 'Z') {
                upper[ch - 'A'] = true;
            } else {
                // Invalid character – required by the test contract
                throw new ArrayIndexOutOfBoundsException(
                    "Input contains non-letter character: '" + ch + "'"
                );
            }
        }

        for (int i = 25; i >= 0; i--) {
            if (lower[i] && upper[i]) {
                char result = (char) ('A' + i);
                return String.valueOf(result);
            }
        }

        return "";
    }
}

