public class Solution {
    public String removeStars(String s) {
        // Use a StringBuilder as a stack for efficiency
        StringBuilder stack = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '*') {
                // Remove the closest non‑star character to the left
                // (the last character in the stack) and discard the star.
                if (stack.length() > 0) {
                    stack.deleteCharAt(stack.length() - 1);
                }
                // The star itself is not added to the stack, effectively removed.
            } else {
                // Regular character, push onto the stack
                stack.append(ch);
            }
        }
        return stack.toString();
    }
}

