import java.util.NavigableMap;
import java.util.TreeMap;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        long k = (long) k1 + k2;
        NavigableMap<Integer, Long> freq = new TreeMap<>();
        long totalDiff = 0L;

        for (int i = 0; i < nums1.length; i++) {
            long diff = Math.abs((long) nums1[i] - (long) nums2[i]);
            if (diff > 0) {
                int d = (int) diff; // diff fits in int range of problem constraints
                freq.merge(d, 1L, Long::sum);
                totalDiff += diff;
            }
        }

        // If we have enough operations to reduce all differences to zero
        if (k >= totalDiff) {
            return 0L;
        }

        while (k > 0 && !freq.isEmpty()) {
            int maxDiff = freq.lastKey();
            long count = freq.remove(maxDiff);

            Integer lowerKeyObj = freq.lowerKey(maxDiff);
            int lowerDiff = (lowerKeyObj == null) ? 0 : lowerKeyObj;

            long diffStep = maxDiff - lowerDiff;
            long opsNeeded = diffStep * count;

            if (k >= opsNeeded) {
                // Reduce all 'count' elements down to 'lowerDiff'
                freq.merge(lowerDiff, count, Long::sum);
                k -= opsNeeded;
            } else {
                long fullSteps = k / count;          // how many whole levels we can drop
                long remainder = k % count;          // remaining single reductions
                int newVal = (int) (maxDiff - fullSteps);

                // Elements that receive only the fullSteps reductions
                freq.merge(newVal, count - remainder, Long::sum);
                // Elements that receive one extra reduction
                if (remainder > 0) {
                    freq.merge(newVal - 1, remainder, Long::sum);
                }
                k = 0; // all operations used
            }
        }

        long result = 0L;
        for (var entry : freq.entrySet()) {
            int d = entry.getKey();
            long cnt = entry.getValue();
            result += cnt * (long) d * d;
        }
        return result;
    }
}

