public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        if (m == 0) {
            return 0;
        }
        int n = matrix[0].length;
        if (numSelect >= n) {
            // selecting all columns (or more) covers every row
            return m;
        }

        int totalMasks = 1 << n;
        int[] freq = new int[totalMasks];

        // Build frequency of each row mask
        for (int[] row : matrix) {
            int mask = 0;
            for (int col = 0; col < n; col++) {
                if (row[col] == 1) {
                    mask |= (1 << col);
                }
            }
            freq[mask]++;
        }

        // SOS DP: dp[mask] = sum of freq[submask] for all submask ⊆ mask
        int[] dp = freq.clone();
        for (int i = 0; i < n; i++) {
            for (int mask = 0; mask < totalMasks; mask++) {
                if ((mask & (1 << i)) != 0) {
                    dp[mask] += dp[mask ^ (1 << i)];
                }
            }
        }

        int best = 0;
        for (int mask = 0; mask < totalMasks; mask++) {
            if (Integer.bitCount(mask) == numSelect) {
                best = Math.max(best, dp[mask]);
            }
        }
        return best;
    }
}

