import java.util.*;

public class Solution {

    /**
     * Evaluates the boolean value of a full binary tree where leaf nodes are 0 (false) or 1 (true)
     * and internal nodes are 2 (OR) or 3 (AND).
     *
     * @param root the root of the binary tree
     * @return the boolean result of evaluating the tree
     */
    public boolean evaluateTree(TreeNode root) {
        if (root == null) {
            // The problem guarantees a non‑null root, but returning false is a safe default.
            return false;
        }

        // Leaf node: its value directly represents the boolean result.
        if (root.left == null && root.right == null) {
            return root.val == 1;
        }

        // Recursively evaluate left and right sub‑trees.
        boolean leftResult = evaluateTree(root.left);
        boolean rightResult = evaluateTree(root.right);

        // Internal node: apply the operation encoded in the node's value.
        // 2 → OR, 3 → AND.
        if (root.val == 2) { // OR operation
            return leftResult || rightResult;
        } else { // AND operation (value 3)
            return leftResult && rightResult;
        }
    }

    /**
     * Minimal definition of a binary tree node compatible with the problem statement.
     */
    public static class TreeNode {
        public int val;
        public TreeNode left;
        public TreeNode right;

        public TreeNode() {}

        public TreeNode(int val) {
            this.val = val;
        }

        public TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }
}

