public class Solution {
    public int minimumRecolors(String blocks, int k) {
        int n = blocks.length();
        if (k == 0 || n == 0) {
            return 0;
        }
        int whiteCount = 0;
        // Count whites in the first window of size k
        for (int i = 0; i < k; i++) {
            if (blocks.charAt(i) == 'W') {
                whiteCount++;
            }
        }
        int minRecolors = whiteCount;
        // Slide the window across the string
        for (int i = k; i < n; i++) {
            // Add the new character entering the window
            if (blocks.charAt(i) == 'W') {
                whiteCount++;
            }
            // Remove the character exiting the window
            if (blocks.charAt(i - k) == 'W') {
                whiteCount--;
            }
            // Update the minimum number of whites seen in any window
            if (whiteCount < minRecolors) {
                minRecolors = whiteCount;
            }
        }
        return minRecolors;
    }
}

