import java.util.*;

public class Solution {
    // Using topological sort to solve this problem
    public int[][] buildMatrix(int k, int[][] rowC, int[][] colC) {
        List<Integer> rowOrder = topologicalSort(k, rowC);
        List<Integer> colOrder = topologicalSort(k, colC);
        if (rowOrder == null || colOrder == null) {
            return new int[0][0];
        }

        // map number -> row index and column index
        int[] rowPos = new int[k + 1];
        int[] colPos = new int[k + 1];
        for (int i = 0; i < k; i++) {
            rowPos[rowOrder.get(i)] = i;
            colPos[colOrder.get(i)] = i;
        }

        int[][] matrix = new int[k][k];
        for (int num = 1; num <= k; num++) {
            int r = rowPos[num];
            int c = colPos[num];
            matrix[r][c] = num;
        }
        return matrix;
    }

    // Returns a topological ordering of numbers 1..k according to conditions.
    // If a cycle exists, returns null.
    private List<Integer> topologicalSort(int k, int[][] conditions) {
        List<List<Integer>> graph = new ArrayList<>(k + 1);
        for (int i = 0; i <= k; i++) {
            graph.add(new ArrayList<>());
        }
        int[] indegree = new int[k + 1];

        for (int[] cond : conditions) {
            int from = cond[0];
            int to = cond[1];
            graph.get(from).add(to);
            indegree[to]++;
        }

        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 1; i <= k; i++) {
            if (indegree[i] == 0) {
                queue.offer(i);
            }
        }

        List<Integer> order = new ArrayList<>(k);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            order.add(cur);
            for (int nxt : graph.get(cur)) {
                indegree[nxt]--;
                if (indegree[nxt] == 0) {
                    queue.offer(nxt);
                }
            }
        }

        return order.size() == k ? order : null;
    }
}

