public class Solution {
    public int minimumNumbers(int nums, int k) {
        // If the target sum is zero, the empty set (size 0) satisfies the condition.
        if (nums == 0) {
            return 0;
        }

        // Try all possible set sizes from 1 up to 10.
        // More than 10 is unnecessary because the condition depends only on the remainder modulo 10.
        for (int size = 1; size <= 10; size++) {
            int remaining = nums - size * k;
            if (remaining < 0) {
                continue; // sum would be negative, not possible
            }
            // After fixing the unit digits (size * k), the rest of the sum must be a multiple of 10.
            if (remaining % 10 == 0) {
                return size;
            }
        }

        // No feasible size found.
        return -1;
    }
}

