public class Solution {
    /**
     * Returns the first character that appears twice in the given string.
     * The second occurrence of the returned character is the earliest among all characters.
     *
     * @param s the input string; must contain at least one character that appears twice
     * @return the first repeated character
     * @throws IllegalArgumentException if the input is null, empty, or contains no repeated character
     */
    public char repeatedCharacter(String s) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("Input string must contain at least one character");
        }

        Set<Integer> seen = new HashSet<>();

        int index = 0;
        while (index < s.length()) {
            int codePoint = s.codePointAt(index);
            if (seen.contains(codePoint)) {
                // The problem guarantees lowercase English letters (BMP), so casting is safe.
                return (char) codePoint;
            }
            seen.add(codePoint);
            index += Character.charCount(codePoint);
        }

        // No duplicate found – this violates the problem constraints.
        throw new IllegalArgumentException("No repeated character found in the input string");
    }
}

