import java.util.*;

public class Solution {
    public int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        int n = nums.length;
        int q = queries.length;
        int[] answer = new int[q];
        int len = nums[0].length();

        // Pre‑compute all possible trimmed versions to avoid repeated substring operations
        // trimmed[i][t] = trimmed string of nums[i] keeping last (t+1) characters (t from 0)
        String[][] trimmed = new String[n][len];
        for (int i = 0; i < n; i++) {
            String s = nums[i];
            for (int t = 1; t <= len; t++) {
                trimmed[i][t - 1] = s.substring(len - t);
            }
        }

        for (int idx = 0; idx < q; idx++) {
            int k = queries[idx][0];
            int trim = queries[idx][1];

            // Build list of indices
            Integer[] order = new Integer[n];
            for (int i = 0; i < n; i++) order[i] = i;

            // Sort according to trimmed value then original index
            final int t = trim - 1; // zero‑based position in trimmed array
            Arrays.sort(order, (a, b) -> {
                int cmp = trimmed[a][t].compareTo(trimmed[b][t]);
                if (cmp != 0) return cmp;
                return Integer.compare(a, b);
            });

            // k is 1‑based
            answer[idx] = order[k - 1];
        }

        return answer;
    }
}

