public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int countHousePlacements(int n) {
        // Number of valid configurations on one side = f[n]
        // where f[0] = 1 (empty), f[1] = 2 (0 or 1), and f[i] = f[i-1] + f[i-2]
        if (n == 0) {
            return 1; // only the empty configuration on both sides
        }
        long prevPrev = 1; // f[0]
        long prev = 2;     // f[1]

        if (n == 1) {
            long ways = prev;
            return (int) ((ways * ways) % MOD);
        }

        long cur = 0;
        for (int i = 2; i <= n; i++) {
            cur = (prevPrev + prev) % MOD; // f[i] = f[i-1] + f[i-2]
            prevPrev = prev;
            prev = cur;
        }

        long waysOneSide = prev; // f[n]
        long result = (waysOneSide * waysOneSide) % MOD;
        return (int) result;
    }
}

