import java.util.Arrays;

public class Solution {
    public int[] answerQueries(int[] nums, int[] queries) {
        // Sort nums because the order of the subsequence does not matter
        Arrays.sort(nums);
        int n = nums.length;
        long[] prefix = new long[n];
        if (n > 0) {
            prefix[0] = nums[0];
            for (int i = 1; i < n; i++) {
                prefix[i] = prefix[i - 1] + nums[i];
            }
        }

        int m = queries.length;
        int[] answer = new int[m];
        for (int i = 0; i < m; i++) {
            long target = queries[i];
            int idx = Arrays.binarySearch(prefix, target);
            if (idx >= 0) {
                // Exact match found; we can take idx+1 elements
                answer[i] = idx + 1;
            } else {
                // Insertion point gives the count of elements with sum <= target
                int insertionPoint = -idx - 1;
                answer[i] = insertionPoint;
            }
        }
        return answer;
    }
}

