import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);
        Set<Integer> passengerSet = new HashSet<>();
        for (int p : passengers) {
            passengerSet.add(p);
        }

        int pIdx = 0;               // index in passengers array
        int lastBoarded = -1;        // time of the last passenger who boarded the current bus
        int candidate = -1;          // answer to be determined

        for (int i = 0; i < buses.length; i++) {
            int busTime = buses[i];
            int boarded = 0;

            while (boarded < capacity && pIdx < passengers.length && passengers[pIdx] <= busTime) {
                lastBoarded = passengers[pIdx];
                pIdx++;
                boarded++;
            }

            // If this is the last bus, decide the candidate time
            if (i == buses.length - 1) {
                if (boarded < capacity) {
                    // there is still room on the last bus
                    candidate = busTime;
                } else {
                    // bus is full, we must arrive before the last boarded passenger
                    candidate = lastBoarded - 1;
                }
            }
        }

        // Ensure the candidate time does not clash with any existing passenger arrival time
        while (candidate >= 0 && passengerSet.contains(candidate)) {
            candidate--;
        }

        return candidate;
    }
}

