public class Solution {
    public int longestSubsequence(String s, int k) {
        long sum = 0L;          // current value of selected ones
        long power = 1L;        // value of the current bit (least‑significant first)
        int length = 0;         // length of the subsequence we build

        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c == '0') {
                // zeros never increase the value
                length++;
            } else { // c == '1'
                if (sum + power <= k) {
                    sum += power;
                    length++;
                }
            }

            // prepare power for the next (more significant) position
            // once power exceeds k it will never be useful for a '1',
            // but we keep increasing it (capped) to avoid overflow.
            if (power <= (long) k) {
                power <<= 1;
                // guard against overflow beyond long range
                if (power < 0) {
                    power = (long) k + 1;
                }
            } else {
                // keep it larger than k so that further '1's are never taken
                power = (long) k + 1;
            }
        }

        return length;
    }
}

