import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int pos = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == k) {
                pos = i;
                break;
            }
        }
        // map stores frequency of prefix balances to the left of k (including empty prefix)
        Map<Integer, Integer> leftCount = new HashMap<>();
        leftCount.put(0, 1); // empty prefix
        int balance = 0;
        // process elements left of k
        for (int i = pos - 1; i >= 0; i--) {
            balance += (nums[i] > k) ? 1 : -1;
            leftCount.put(balance, leftCount.getOrDefault(balance, 0) + 1);
        }

        long answer = 0;
        balance = 0;
        // process elements from k to the right, including k itself
        for (int i = pos; i < n; i++) {
            if (i != pos) {
                balance += (nums[i] > k) ? 1 : -1;
            }
            // we need total balance = 0 or 1
            answer += leftCount.getOrDefault(-balance, 0);
            answer += leftCount.getOrDefault(1 - balance, 0);
        }

        return (int) answer;
    }
}

