public class Solution {
    public int deleteGreatestValue(int[][] grid) {
        int m = grid.length;
        if (m == 0) {
            return 0;
        }
        int n = grid[0].length;
        // Sort each row in non‑decreasing order
        for (int i = 0; i < m; i++) {
            Arrays.sort(grid[i]);
        }
        int answer = 0;
        // For each operation (column), take the maximum among the current greatest elements
        for (int col = 0; col < n; col++) {
            int curMax = 0;
            for (int row = 0; row < m; row++) {
                // The greatest remaining element in this row is at index n‑1‑col after sorting
                curMax = Math.max(curMax, grid[row][n - 1 - col]);
            }
            answer += curMax;
        }
        return answer;
    }
}

