import java.util.*;

public class Solution {
    /**
     * Returns the number of pairs (i, j) with i < j such that
     * nums1[i] - nums1[j] <= nums2[i] - nums2[j] + diff.
     *
     * @param nums1 first integer array
     * @param nums2 second integer array
     * @param diff  the allowed difference
     * @return the count of valid pairs
     */
    public long numberOfPairs(int[] nums1, int[] nums2, int diff) {
        return countPairs(nums1, nums2, diff);
    }

    // Core implementation (kept private to avoid exposing two public APIs)
    private long countPairs(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        long[] transformed = new long[n];
        for (int i = 0; i < n; i++) {
            // a[i] = nums1[i] - nums2[i]
            transformed[i] = (long) nums1[i] - (long) nums2[i];
        }
        return sortAndCount(transformed, 0, n - 1, (long) diff);
    }

    // Helper method that sorts the subarray [l, r] and returns the number of valid pairs
    private long sortAndCount(long[] arr, int l, int r, long diff) {
        if (l >= r) {
            return 0L;
        }
        int mid = l + (r - l) / 2;
        long count = 0;
        count += sortAndCount(arr, l, mid, diff);
        count += sortAndCount(arr, mid + 1, r, diff);
        count += countCrossPairs(arr, l, mid, r, diff);
        merge(arr, l, mid, r);
        return count;
    }

    // Count pairs where left index is in [l, mid] and right index in [mid+1, r]
    private long countCrossPairs(long[] arr, int l, int mid, int r, long diff) {
        long cnt = 0;
        int j = mid + 1;
        for (int i = l; i <= mid; i++) {
            while (j <= r && arr[i] > arr[j] + diff) {
                j++;
            }
            // All elements from j to r satisfy arr[i] <= arr[k] + diff
            cnt += (r - j + 1);
        }
        return cnt;
    }

    // Standard merge of two sorted halves [l, mid] and [mid+1, r]
    private void merge(long[] arr, int l, int mid, int r) {
        int n1 = mid - l + 1;
        int n2 = r - mid;
        long[] left = new long[n1];
        long[] right = new long[n2];
        System.arraycopy(arr, l, left, 0, n1);
        System.arraycopy(arr, mid + 1, right, 0, n2);
        int i = 0, j = 0, k = l;
        while (i < n1 && j < n2) {
            if (left[i] <= right[j]) {
                arr[k++] = left[i++];
            } else {
                arr[k++] = right[j++];
            }
        }
        while (i < n1) {
            arr[k++] = left[i++];
        }
        while (j < n2) {
            arr[k++] = right[j++];
        }
    }
}

