import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int unequalTriplets(int[] nums) {
        // Count frequency of each distinct number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.merge(num, 1, Integer::sum);
        }

        long sum = 0;        // sum of frequencies processed so far
        long sumPairs = 0;   // sum of products of frequencies of any two processed distinct values
        long result = 0;     // final answer

        for (int f : freqMap.values()) {
            // For each new distinct value, all previously seen pairs can form a triplet with it
            result += f * sumPairs;

            // Update pairwise sum with the new value combined with each previous single frequency
            sumPairs += f * sum;

            // Update the simple sum of frequencies
            sum += f;
        }

        return (int) result;
    }
}

