import java.util.*;

public class Solution {
    /**
     * Returns the number of subarrays whose greatest common divisor equals k.
     *
     * @param nums the input array
     * @param k    the target GCD
     * @return the count of subarrays with GCD equal to k
     */
    public int subarrayGCD(int[] nums, int k) {
        long count = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int currentGcd = 0;
            for (int j = i; j < n; j++) {
                currentGcd = gcd(currentGcd, nums[j]);
                if (currentGcd == k) {
                    count++;
                }
                // If the current GCD is already smaller than k, it can never become k again.
                if (currentGcd < k) {
                    break;
                }
                // If k does not divide the current GCD, future GCDs (which are divisors of currentGcd)
                // will also not be divisible by k, thus can never become exactly k.
                if (currentGcd % k != 0) {
                    break;
                }
            }
        }
        return (int) count;
    }

    // Euclidean algorithm for GCD
    private int gcd(int a, int b) {
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return Math.abs(a);
    }
}

