import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import com_github_leetcode.TreeNode;

/**
 * Solution for reversing node values at each odd level of a perfect binary tree.
 */
public class Solution {

    /**
     * Reverses the values of nodes at every odd level (1‑based) of the given perfect binary tree.
     *
     * @param root the root of the perfect binary tree
     * @return the root of the tree after the values on odd levels have been reversed
     */
    public TreeNode reverseOddLevels(TreeNode root) {
        if (root == null) {
            return null;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int level = 0; // root is level 0 (even)

        while (!queue.isEmpty()) {
            int size = queue.size();
            List<TreeNode> currentLevelNodes = new ArrayList<>(size);

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                // Collect nodes of the current level
                currentLevelNodes.add(node);

                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }

            // If this is an odd level, reverse the values in place
            if (level % 2 == 1) {
                int left = 0;
                int right = currentLevelNodes.size() - 1;
                while (left < right) {
                    int tmp = currentLevelNodes.get(left).val;
                    currentLevelNodes.get(left).val = currentLevelNodes.get(right).val;
                    currentLevelNodes.get(right).val = tmp;
                    left++;
                    right--;
                }
            }

            level++;
        }

        return root;
    }
}

