public class Solution {
    /**
     * Returns the maximum hourglass sum in the given matrix.
     * An hourglass is defined as:
     * a b c
     *   d
     * e f g
     *
     * @param grid the input matrix
     * @return the maximum hourglass sum
     */
    public int maxSum(int[][] grid) {
        int rows = grid.length;
        if (rows < 3) {
            // Not enough rows to form an hourglass
            return 0;
        }
        int cols = grid[0].length;
        if (cols < 3) {
            // Not enough columns to form an hourglass
            return 0;
        }

        int max = Integer.MIN_VALUE;

        // Iterate over every possible top‑left corner of an hourglass
        for (int i = 0; i <= rows - 3; i++) {
            for (int j = 0; j <= cols - 3; j++) {
                // Compute the sum of the current hourglass
                int sum = 0;
                // top row
                sum += grid[i][j] + grid[i][j + 1] + grid[i][j + 2];
                // middle
                sum += grid[i + 1][j + 1];
                // bottom row
                sum += grid[i + 2][j] + grid[i + 2][j + 1] + grid[i + 2][j + 2];

                if (sum > max) {
                    max = sum;
                }
            }
        }

        return max;
    }
}

