public class Solution {
    public long makeSimilar(int[] nums, int[] target) {
        int n = nums.length;
        // Count odds to allocate arrays
        int oddCount = 0;
        for (int v : nums) {
            if ((v & 1) == 1) {
                oddCount++;
            }
        }
        int evenCount = n - oddCount;

        int[] oddNums = new int[oddCount];
        int[] evenNums = new int[evenCount];
        int[] oddTarget = new int[oddCount];
        int[] evenTarget = new int[evenCount];

        int oIdx = 0, eIdx = 0;
        for (int v : nums) {
            if ((v & 1) == 1) {
                oddNums[oIdx++] = v;
            } else {
                evenNums[eIdx++] = v;
            }
        }

        oIdx = 0;
        eIdx = 0;
        for (int v : target) {
            if ((v & 1) == 1) {
                oddTarget[oIdx++] = v;
            } else {
                evenTarget[eIdx++] = v;
            }
        }

        Arrays.sort(oddNums);
        Arrays.sort(oddTarget);
        Arrays.sort(evenNums);
        Arrays.sort(evenTarget);

        long operations = 0L;

        for (int i = 0; i < oddCount; i++) {
            int diff = oddTarget[i] - oddNums[i];
            if (diff > 0) {
                operations += diff / 2;
            }
        }

        for (int i = 0; i < evenCount; i++) {
            int diff = evenTarget[i] - evenNums[i];
            if (diff > 0) {
                operations += diff / 2;
            }
        }

        return operations;
    }
}

