import java.util.List;
import java.util.Objects;

/**
 * Utility public class Solution the solution for the difference matrix problem
 * and helper methods used by the test suite.
 */
public final class Solution {

    /** Prevent instantiation. */
    private Solution() {
        // utility class – prevent instantiation
    }

    /**
     * Computes the difference matrix {@code diff} for a given binary matrix {@code grid}.
     * <p>
     * For each cell {@code (i, j)}:
     * <pre>
     * diff[i][j] = onesRow_i + onesCol_j - zerosRow_i - zerosCol_j
     * </pre>
     * where {@code onesRow_i} is the number of {@code 1}s in row {@code i},
     * {@code onesCol_j} is the number of {@code 1}s in column {@code j},
     * {@code zerosRow_i} = n - onesRow_i, and {@code zerosCol_j} = m - onesCol_j.
     *
     * @param grid a binary matrix (containing only 0 and 1)
     * @return the computed difference matrix
     */
    public static int[][] differenceMatrix(int[][] grid) {
        if (grid == null || grid.length == 0) {
            return new int[0][0];
        }
        int m = grid.length;
        int n = grid[0].length;

        int[] onesRow = new int[m];
        int[] onesCol = new int[n];

        // Count ones per row and per column
        for (int i = 0; i < m; i++) {
            int rowOnes = 0;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    rowOnes++;
                    onesCol[j]++;
                }
            }
            onesRow[i] = rowOnes;
        }

        int[][] diff = new int[m][n];
        // Compute diff using the formula
        for (int i = 0; i < m; i++) {
            int zerosRow = n - onesRow[i];
            for (int j = 0; j < n; j++) {
                int zerosCol = m - onesCol[j];
                diff[i][j] = onesRow[i] + onesCol[j] - zerosRow - zerosCol;
            }
        }
        return diff;
    }

    /**
     * Convert a {@code List<List<Integer>>} to a primitive {@code int[][]}.
     *
     * @param list the list of rows
     * @return a 2‑D int array with the same contents
     */
    public static int[][] to2DIntArray(List<List<Integer>> list) {
        if (list == null) {
            return new int[0][];
        }
        int rows = list.size();
        int[][] result = new int[rows][];
        for (int i = 0; i < rows; i++) {
            List<Integer> row = list.get(i);
            if (row == null) {
                result[i] = new int[0];
                continue;
            }
            int cols = row.size();
            int[] arr = new int[cols];
            for (int j = 0; j < cols; j++) {
                arr[j] = Objects.requireNonNull(row.get(j));
            }
            result[i] = arr;
        }
        return result;
    }

    /**
     * Optional helper to pretty‑print a matrix (useful while debugging).
     *
     * @param matrix matrix to print
     */
    public static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            System.out.println(java.util.Arrays.toString(row));
        }
    }
}

