import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    private static class Factory {
        long pos;
        int limit;
        Factory(long p, int l) {
            this.pos = p;
            this.limit = l;
        }
    }

    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        // convert robots to array and sort
        int n = robot.size();
        long[] robots = new long[n];
        for (int i = 0; i < n; i++) {
            robots[i] = robot.get(i);
        }
        java.util.Arrays.sort(robots);

        // convert factories to list of objects and sort by position
        List<Factory> factories = new ArrayList<>();
        for (int[] arr : f) {
            factories.add(new Factory(arr[0], arr[1]));
        }
        factories.sort((a, b) -> Long.compare(a.pos, b.pos));

        final long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1];
        for (int i = 1; i <= n; i++) dp[i] = INF;
        dp[0] = 0;

        for (Factory factory : factories) {
            long[] ndp = new long[n + 1];
            // start with the case of assigning 0 robots to this factory
            System.arraycopy(dp, 0, ndp, 0, n + 1);

            // try to assign k (1..limit) robots ending at position i to this factory
            for (int i = 1; i <= n; i++) {
                long cum = 0;
                // assign up to factory.limit robots ending at i
                for (int k = 1; k <= factory.limit && k <= i; k++) {
                    cum += Math.abs(robots[i - k] - factory.pos);
                    long candidate = dp[i - k] + cum;
                    if (candidate < ndp[i]) {
                        ndp[i] = candidate;
                    }
                }
            }
            dp = ndp;
        }

        return dp[n];
    }
}

