import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int minGroups(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return 0;
        }

        // Sort intervals by their start time
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        // Min‑heap to keep the earliest ending interval of each current group
        PriorityQueue<Integer> heap = new PriorityQueue<>();

        int maxGroups = 0;
        for (int[] interval : intervals) {
            int start = interval[0];
            int end = interval[1];

            // If the current interval starts after the earliest ending interval,
            // they do not intersect (strictly greater, because sharing an endpoint counts as intersecting)
            if (!heap.isEmpty() && start > heap.peek()) {
                heap.poll(); // reuse that group
            }

            heap.offer(end); // assign current interval to a group (new or reused)
            maxGroups = Math.max(maxGroups, heap.size());
        }

        return maxGroups;
    }
}

