public class Solution {
    public int[] applyOperations(int[] nums) {
        int n = nums.length;
        // Apply the operations sequentially
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] == nums[i + 1]) {
                nums[i] <<= 1;          // multiply by 2
                nums[i + 1] = 0;
            }
        }
        // Shift all zeros to the end while preserving order of non‑zero elements
        int idx = 0;
        for (int value : nums) {
            if (value != 0) {
                nums[idx++] = value;
            }
        }
        while (idx < n) {
            nums[idx++] = 0;
        }
        return nums;
    }
}

