        int startA = toDayOfYear(arriveAlice);
        int endA   = toDayOfYear(leaveAlice);
        int startB = toDayOfYear(arriveBob);
        int endB   = toDayOfYear(leaveBob);

        int start = Math.max(startA, startB);
        int end   = Math.min(endA, endB);

        if (start > end) {
            return 0;
        }
        return end - start + 1;
    }
}

