public class Solution {
    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;
        int[] suffixOr = new int[n];
        // compute suffix ORs
        suffixOr[n - 1] = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            suffixOr[i] = nums[i] | suffixOr[i + 1];
        }

        int[] answer = new int[n];
        int[] bitCount = new int[31]; // counts of each bit in the current window
        int currentOr = 0;
        int r = 0; // exclusive right bound of the window

        for (int i = 0; i < n; i++) {
            // expand the window until its OR equals the maximal suffix OR for position i
            while (r < n && currentOr != suffixOr[i]) {
                int val = nums[r];
                for (int b = 0; b < 31; b++) {
                    if (((val >> b) & 1) == 1) {
                        if (bitCount[b] == 0) {
                            currentOr |= (1 << b);
                        }
                        bitCount[b]++;
                    }
                }
                r++;
            }
            // now currentOr == suffixOr[i]; the window [i, r) is the minimal one
            answer[i] = r - i;

            // remove nums[i] before moving to the next start index
            int val = nums[i];
            for (int b = 0; b < 31; b++) {
                if (((val >> b) & 1) == 1) {
                    bitCount[b]--;
                    if (bitCount[b] == 0) {
                        currentOr &= ~(1 << b);
                    }
                }
            }
        }

        return answer;
    }
}

