import java.util.PriorityQueue;

public class Solution {
    private static class Worker {
        int cost;
        int index;

        Worker(int cost, int index) {
            this.cost = cost;
            this.index = index;
        }
    }

    public long totalCost(int[] costs, int k, int candidates) {
        int n = costs.length;
        int leftPtr = 0;
        int rightPtr = n - 1;

        PriorityQueue<Worker> leftHeap = new PriorityQueue<>(
                (a, b) -> a.cost != b.cost ? Integer.compare(a.cost, b.cost)
                                            : Integer.compare(a.index, b.index));
        PriorityQueue<Worker> rightHeap = new PriorityQueue<>(
                (a, b) -> a.cost != b.cost ? Integer.compare(a.cost, b.cost)
                                            : Integer.compare(a.index, b.index));

        // Fill initial candidates from the left side
        for (int i = 0; i < candidates && leftPtr <= rightPtr; i++) {
            leftHeap.offer(new Worker(costs[leftPtr], leftPtr));
            leftPtr++;
        }

        // Fill initial candidates from the right side
        for (int i = 0; i < candidates && leftPtr <= rightPtr; i++) {
            rightHeap.offer(new Worker(costs[rightPtr], rightPtr));
            rightPtr--;
        }

        long total = 0L;

        for (int hired = 0; hired < k; hired++) {
            // Decide from which heap to take the next worker
            if (rightHeap.isEmpty() ||
                (!leftHeap.isEmpty() && compareWorkers(leftHeap.peek(), rightHeap.peek()) <= 0)) {
                // Take from left heap
                Worker w = leftHeap.poll();
                total += w.cost;

                // Replenish left heap if possible
                if (leftPtr <= rightPtr) {
                    leftHeap.offer(new Worker(costs[leftPtr], leftPtr));
                    leftPtr++;
                }
            } else {
                // Take from right heap
                Worker w = rightHeap.poll();
                total += w.cost;

                // Replenish right heap if possible
                if (leftPtr <= rightPtr) {
                    rightHeap.offer(new Worker(costs[rightPtr], rightPtr));
                    rightPtr--;
                }
            }
        }

        return total;
    }

    // Helper to compare two workers according to the problem's tie‑breaking rules
    private int compareWorkers(Worker a, Worker b) {
        if (a.cost != b.cost) {
            return Integer.compare(a.cost, b.cost);
        }
        return Integer.compare(a.index, b.index);
    }
}

