public class Solution {
    public int[][] closestNodes(TreeNode root, int[] queries) {
        TreeSet<Integer> values = new TreeSet<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode cur = root;
        while (cur != null || !stack.isEmpty()) {
            while (cur != null) {
                stack.push(cur);
                cur = cur.left;
            }
            cur = stack.pop();
            values.add(cur.val);
            cur = cur.right;
        }

        int n = queries.length;
        int[][] answer = new int[n][2];
        for (int i = 0; i < n; i++) {
            int q = queries[i];
            Integer floor = values.floor(q);
            Integer ceil = values.ceiling(q);
            answer[i][0] = (floor != null) ? floor : -1;
            answer[i][1] = (ceil != null) ? ceil : -1;
        }
        return answer;
    }
}

