public class Solution {
    // Trie node definition
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        int count; // number of words that have this prefix
    }

    private final TrieNode root = new TrieNode();

    public Solution() {
        // constructor can stay empty
    }

    // Insert a word into the trie, updating prefix counts
    private void insert(String word) {
        TrieNode node = root;
        for (int i = 0; i < word.length(); i++) {
            int idx = word.charAt(i) - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
            node.count++; // this prefix appears in one more word
        }
    }

    // Compute the sum of prefix scores for a single word
    private int query(String word) {
        TrieNode node = root;
        int sum = 0;
        for (int i = 0; i < word.length(); i++) {
            int idx = word.charAt(i) - 'a';
            node = node.children[idx];
            sum += node.count;
        }
        return sum;
    }

    public int[] sumPrefixScores(String[] words) {
        // Build the trie with all words
        for (String w : words) {
            insert(w);
        }

        int n = words.length;
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            answer[i] = query(words[i]);
        }
        return answer;
    }
}

