public class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        int n = creators.length;
        // total views per creator
        Map<String, Long> totalViews = new HashMap<>();
        // best video id per creator (most views, tie -> lexicographically smallest id)
        Map<String, String> bestId = new HashMap<>();
        // views of the best video per creator
        Map<String, Integer> bestViews = new HashMap<>();

        for (int i = 0; i < n; i++) {
            String creator = creators[i];
            String videoId = ids[i];
            int view = views[i];

            // update total views
            totalViews.put(creator, totalViews.getOrDefault(creator, 0L) + view);

            // update best video for this creator
            if (!bestViews.containsKey(creator) ||
                view > bestViews.get(creator) ||
                (view == bestViews.get(creator) && videoId.compareTo(bestId.get(creator)) < 0)) {
                bestViews.put(creator, view);
                bestId.put(creator, videoId);
            }
        }

        // find maximum total popularity
        long maxPopularity = 0;
        for (long v : totalViews.values()) {
            if (v > maxPopularity) {
                maxPopularity = v;
            }
        }

        // collect answer
        List<List<String>> answer = new ArrayList<>();
        for (Map.Entry<String, Long> entry : totalViews.entrySet()) {
            if (entry.getValue() == maxPopularity) {
                List<String> pair = new ArrayList<>(2);
                pair.add(entry.getKey());
                pair.add(bestId.get(entry.getKey()));
                answer.add(pair);
            }
        }

        return answer;
    }
}

