import java.util.*;

/* ---------- TreeNode definition (package‑private) ---------- */
public class Solution {
    int val;
    TreeNode left;
    TreeNode right;

    TreeNode() {}

    TreeNode(int val) {
        this.val = val;
    }

    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }

    /**
     * Builds a binary tree from a level‑order list.
     * {@code null} values denote absent children.
     */
    static TreeNode create(List<Integer> values) {
        if (values == null || values.isEmpty()) {
            return null;
        }
        Iterator<Integer> it = values.iterator();
        Integer rootVal = it.next();
        if (rootVal == null) {
            return null;
        }
        TreeNode root = new TreeNode(rootVal);
        Queue<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        while (it.hasNext()) {
            TreeNode parent = q.poll();

            // left child
            Integer leftVal = it.next();
            if (leftVal != null) {
                TreeNode left = new TreeNode(leftVal);
                parent.left = left;
                q.add(left);
            }

            // right child (may be absent if list length is odd)
            if (it.hasNext()) {
                Integer rightVal = it.next();
                if (rightVal != null) {
                    TreeNode right = new TreeNode(rightVal);
                    parent.right = right;
                    q.add(right);
                }
            }
        }
        return root;
    }
}

/* ---------- Solution ---------- */
public class Solution {

    /* ---------- Fields for preprocessing ---------- */
    private final Map<Integer, Integer> depth = new HashMap<>();        // depth from root (edges)
    private final Map<Integer, Integer> subMaxDepth = new HashMap<>(); // max depth inside subtree
    private final Map<Integer, Integer> outsideDepth = new HashMap<>(); // answer for each node

    /** First DFS: compute depth of each node and the maximum depth inside each subtree. */
    private void dfsDepth(TreeNode node, int d) {
        if (node == null) {
            return;
        }
        depth.put(node.val, d);
        int max = d; // at least the node itself
        if (node.left != null) {
            dfsDepth(node.left, d + 1);
            max = Math.max(max, subMaxDepth.get(node.left.val));
        }
        if (node.right != null) {
            dfsDepth(node.right, d + 1);
            max = Math.max(max, subMaxDepth.get(node.right.val));
        }
        subMaxDepth.put(node.val, max);
    }

    /**
     * Second DFS: for each node compute the greatest depth reachable without using its own subtree.
     * {@code bestFromAbove} is the maximum depth among all nodes that are not in the current node's subtree
     * and are located above (i.e., ancestors or sibling subtrees of ancestors).
     */
    private void dfsOutside(TreeNode node, int bestFromAbove) {
        if (node == null) {
            return;
        }
        outsideDepth.put(node.val, bestFromAbove);

        // Collect children for easier handling
        List<TreeNode> children = new ArrayList<>(2);
        if (node.left != null) children.add(node.left);
        if (node.right != null) children.add(node.right);
        int sz = children.size();

        // Prefix and suffix maximums of children's subtree max depths
        int[] pref = new int[sz];
        int[] suff = new int[sz];
        for (int i = 0; i < sz; i++) {
            int val = subMaxDepth.get(children.get(i).val);
            pref[i] = (i == 0) ? val : Math.max(pref[i - 1], val);
        }
        for (int i = sz - 1; i >= 0; i--) {
            int val = subMaxDepth.get(children.get(i).val);
            suff[i] = (i == sz - 1) ? val : Math.max(suff[i + 1], val);
        }

        // Propagate to each child
        for (int i = 0; i < sz; i++) {
            TreeNode child = children.get(i);

            // Best depth among sibling subtrees (excluding this child)
            int bestSibling = Integer.MIN_VALUE;
            if (i > 0) bestSibling = Math.max(bestSibling, pref[i - 1]);
            if (i < sz - 1) bestSibling = Math.max(bestSibling, suff[i + 1]);

            // Depth of the current node itself is also reachable from the child after removal
            int candidate = Math.max(bestFromAbove, depth.get(node.val));
            if (bestSibling != Integer.MIN_VALUE) {
                candidate = Math.max(candidate, bestSibling);
            }

            dfsOutside(child, candidate);
        }
    }

    /**
     * Returns the height of the tree after removing the subtree rooted at each query node.
     *
     * @param root    the root of the original binary tree
     * @param queries array of node values whose subtrees are to be removed (independently)
     * @return array of heights after each removal
     */
    public int[] treeQueries(TreeNode root, int[] queries) {
        if (root == null) {
            return new int[0];
        }
        // Clear previous state (in case the same Solution instance is reused)
        depth.clear();
        subMaxDepth.clear();
        outsideDepth.clear();

        dfsDepth(root, 0);
        dfsOutside(root, Integer.MIN_VALUE); // root has no outside nodes; queries never ask for root

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            ans[i] = outsideDepth.getOrDefault(queries[i], 0);
        }
        return ans;
    }
}

