import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int destroyTargets(int[] nums, int space) {
        // Map from remainder to an array where:
        // index 0 -> count of numbers with this remainder
        // index 1 -> minimal number with this remainder
        Map<Integer, int[]> map = new HashMap<>();

        for (int num : nums) {
            int rem = num % space;
            int[] info = map.get(rem);
            if (info == null) {
                // first occurrence of this remainder
                map.put(rem, new int[]{1, num});
            } else {
                info[0]++;                     // increase count
                if (num < info[1]) {
                    info[1] = num;            // keep minimal seed value
                }
            }
        }

        int bestCount = -1;
        int answer = Integer.MAX_VALUE;

        for (int[] info : map.values()) {
            int cnt = info[0];
            int minVal = info[1];
            if (cnt > bestCount) {
                bestCount = cnt;
                answer = minVal;
            } else if (cnt == bestCount && minVal < answer) {
                answer = minVal;
            }
        }

        return answer;
    }
}

