        for (int v : nums1) {
            xorA ^= v;
        }
        int xorB = 0;
        for (int v : nums2) {
            xorB ^= v;
        }
        int n = nums1.length;
        int m = nums2.length;

        if (m % 2 == 0) {
            // each element of nums1 contributes xorB
            return (n % 2 == 0) ? 0 : xorB;
