import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;

public class Solution {
    public int maxStarSum(int[] nodeValues, int[][] edges, int maxNumberOfEdges) {
        int n = nodeValues.length;
        @SuppressWarnings("unchecked")
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        long answer = Long.MIN_VALUE;

        for (int center = 0; center < n; center++) {
            long sum = nodeValues[center];

            if (maxNumberOfEdges > 0) {
                PriorityQueue<Integer> heap = new PriorityQueue<>(maxNumberOfEdges);
                for (int neighbor : adj[center]) {
                    int val = nodeValues[neighbor];
                    if (val <= 0) {
                        continue; // non‑positive values do not improve the sum
                    }
                    if (heap.size() < maxNumberOfEdges) {
                        heap.offer(val);
                    } else if (val > heap.peek()) {
                        heap.poll();
                        heap.offer(val);
                    }
                }
                for (int v : heap) {
                    sum += v;
                }
            }

            answer = Math.max(answer, sum);
        }

        return (int) answer;
    }
}

