import java.util.ArrayList;
import java.util.List;
import java.util.Stack;

/**
 * Solution for the minimum fuel cost problem.
 *
 * The idea is to treat the road network as a tree rooted at the capital (city 0).
 * For each edge we need to transport all representatives from the child subtree
 * to the parent. If a subtree contains {@code k} representatives and each car
 * can carry {@code seats} people, the number of cars that must cross the edge
 * is {@code ceil(k / seats)}. Since each car traverses the edge exactly once,
 * the total fuel consumption contributed by that edge equals that number.
 *
 * By performing a post‑order traversal we can compute the size of every
 * subtree and accumulate the required fuel for each edge.
 */
public class Solution {

    /**
     * Returns the minimum total liters of fuel required for all representatives
     * to reach the capital city (city 0).
     *
     * @param roads an array where each element {@code [a, b]} represents a bidirectional road
     * @param seats the number of seats in each car (capacity)
     * @return the minimum total fuel consumption
     */
    public long minimumFuelCost(int[][] roads, int seats) {
        int n = roads.length + 1; // number of cities (nodes)

        // Build adjacency list
        @SuppressWarnings("unchecked")
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        // parent[i] = parent of node i in the tree rooted at 0
        int[] parent = new int[n];
        parent[0] = -1;

        // Order of traversal (pre‑order); we will later process it in reverse
        List<Integer> order = new ArrayList<>(n);
        Stack<Integer> stack = new Stack<>();
        stack.push(0);
        while (!stack.isEmpty()) {
            int node = stack.pop();
            order.add(node);
            for (int nb : graph[node]) {
                if (nb == parent[node]) {
                    continue;
                }
                parent[nb] = node;
                stack.push(nb);
            }
        }

        // subtreeSize[i] = number of representatives in the subtree rooted at i
        int[] subtreeSize = new int[n];
        long totalFuel = 0L;

        // Process nodes from leaves up to the root
        for (int i = order.size() - 1; i >= 0; i--) {
            int node = order.get(i);
            subtreeSize[node] = 1; // count the representative of the node itself
            for (int nb : graph[node]) {
                if (nb == parent[node]) {
                    continue;
                }
                subtreeSize[node] += subtreeSize[nb];
                long carsNeeded = (subtreeSize[nb] + (long) seats - 1) / seats;
                totalFuel += carsNeeded; // each car traverses the edge once
            }
        }

        return totalFuel;
    }
}

