public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        // dpPrev[j][r] – number of ways to reach cell (i‑1, j) with sum % k == r
        long[][] dpPrev = new long[n][k];
        // dpCurr[j][r] – number of ways to reach cell (i, j) with sum % k == r
        long[][] dpCurr = new long[n][k];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                long[] ways = new long[k];
                int cellVal = ((grid[i][j] % k) + k) % k; // ensure non‑negative

                if (i == 0 && j == 0) {
                    // start cell
                    ways[cellVal] = 1;
                } else {
                    // from top (i‑1, j)
                    if (i > 0) {
                        long[] fromTop = dpPrev[j];
                        for (int r = 0; r < k; r++) {
                            long cnt = fromTop[r];
                            if (cnt != 0) {
                                int newR = (r + cellVal) % k;
                                ways[newR] = (ways[newR] + cnt) % MOD;
                            }
                        }
                    }
                    // from left (i, j‑1)
                    if (j > 0) {
                        long[] fromLeft = dpCurr[j - 1];
                        for (int r = 0; r < k; r++) {
                            long cnt = fromLeft[r];
                            if (cnt != 0) {
                                int newR = (r + cellVal) % k;
                                ways[newR] = (ways[newR] + cnt) % MOD;
                            }
                        }
                    }
                }
                dpCurr[j] = ways;
            }
            // prepare for next row
            dpPrev = dpCurr;
            dpCurr = new long[n][k];
        }

        return (int) (dpPrev[n - 1][0] % MOD);
    }
}

