import java.util.*;

public class Solution {
    public int longestNiceSubarray(int[] nums) {
        int n = nums.length;
        if (n == 0) {
            return 0;
        }

        // bit counts for bits 0..30 (since nums are positive ints, up to 2^31-1)
        int[] bitCount = new int[31];
        int left = 0;
        int best = 1; // subarrays of length 1 are always nice

        for (int right = 0; right < n; right++) {
            int val = nums[right];
            for (int b = 0; b < 31; b++) {
                if (((val >> b) & 1) == 1) {
                    bitCount[b]++;
                }
            }

            // shrink window until it becomes nice
            while (!isNice(bitCount, right - left + 1)) {
                int removeVal = nums[left];
                for (int b = 0; b < 31; b++) {
                    if (((removeVal >> b) & 1) == 1) {
                        bitCount[b]--;
                    }
                }
                left++;
            }

            best = Math.max(best, right - left + 1);
        }

        return best;
    }

    // Helper to check the "nice" condition for the current window size
    private boolean isNice(int[] bitCount, int windowSize) {
        // Sub‑arrays of length 1 are always nice
        if (windowSize <= 1) {
            return true;
        }

        // If any bit appears in two or more numbers, the pairwise AND is non‑zero → not nice
        for (int b = 0; b < 31; b++) {
            if (bitCount[b] >= 2) {
                return false;
            }
        }
        return true;
    }
}

