import java.util.*;

public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        // parent and depth from root (0)
        int[] parent = new int[n];
        int[] depth = new int[n];
        Arrays.fill(parent, -1);
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(0);
        depth[0] = 0;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int nxt : graph[cur]) {
                if (nxt == parent[cur]) continue;
                parent[nxt] = cur;
                depth[nxt] = depth[cur] + 1;
                queue.add(nxt);
            }
        }

        // distance from bob to each node on bob's path to root
        final int INF = Integer.MAX_VALUE;
        int[] bobDist = new int[n];
        Arrays.fill(bobDist, INF);
        int node = bob;
        int d = 0;
        while (node != -1) {
            bobDist[node] = d;
            node = parent[node];
            d++;
        }

        // contribution of each node for Alice
        long[] contrib = new long[n];
        for (int i = 0; i < n; i++) {
            if (bobDist[i] == INF) {
                contrib[i] = amount[i];
            } else {
                if (depth[i] < bobDist[i]) {
                    contrib[i] = amount[i];
                } else if (depth[i] == bobDist[i]) {
                    contrib[i] = amount[i] / 2; // amounts are even
                } else {
                    contrib[i] = 0;
                }
            }
        }

        // DFS from root to all leaves, tracking max sum
        long maxProfit = Long.MIN_VALUE;
        Deque<long[]> stack = new ArrayDeque<>();
        stack.push(new long[]{0, -1, contrib[0]}); // node, parent, current sum

        while (!stack.isEmpty()) {
            long[] cur = stack.pop();
            int curNode = (int) cur[0];
            int curParent = (int) cur[1];
            long curSum = cur[2];

            boolean isLeaf = (curNode != 0 && graph[curNode].size() == 1);
            if (isLeaf) {
                if (curSum > maxProfit) maxProfit = curSum;
            }

            for (int nxt : graph[curNode]) {
                if (nxt == curParent) continue;
                stack.push(new long[]{nxt, curNode, curSum + contrib[nxt]});
            }
        }

        // Edge case: single node tree
        if (n == 1) {
            maxProfit = contrib[0];
        }

        return (int) maxProfit;
    }
}

