import java.util.*;

public class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();
        char[] ch = s.toCharArray();
        int[] dp = new int[n + 1];
        Arrays.fill(dp, -1_000_000);
        dp[0] = 0;

        for (int i = 0; i < n; i++) {
            // propagate the best value without taking a new substring
            dp[i + 1] = Math.max(dp[i + 1], dp[i]);

            // find the shortest palindrome starting at i with length >= k
            int bestEnd = Integer.MAX_VALUE;

            // odd length palindromes
            int left = i, right = i;
            while (left >= 0 && right < n && ch[left] == ch[right]) {
                int len = right - left + 1;
                if (len >= k) {
                    bestEnd = Math.min(bestEnd, right);
                    break; // first (shortest) odd palindrome meeting the length requirement
                }
                left--;
                right++;
            }

            // even length palindromes
            left = i;
            right = i + 1;
            while (left >= 0 && right < n && ch[left] == ch[right]) {
                int len = right - left + 1;
                if (len >= k) {
                    bestEnd = Math.min(bestEnd, right);
                    break; // first (shortest) even palindrome meeting the length requirement
                }
                left--;
                right++;
            }

            if (bestEnd != Integer.MAX_VALUE) {
                dp[bestEnd + 1] = Math.max(dp[bestEnd + 1], dp[i] + 1);
            }
        }

        return dp[n];
    }
}

