import java.util.Arrays;

public class Solution {
    /**
     * Returns the minimum total cost to make all elements of {@code nums} equal.
     * Changing the value of {@code nums[i]} by 1 costs {@code cost[i]}.
     *
     * @param nums the original values
     * @param cost the cost per unit change for each position
     * @return the minimal total cost
     */
    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        // Pair each number with its corresponding cost
        long[][] pairs = new long[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums[i];
            pairs[i][1] = cost[i];
        }

        // Sort by the number values
        Arrays.sort(pairs, (a, b) -> Long.compare(a[0], b[0]));

        // Compute total weight (sum of costs)
        long totalWeight = 0L;
        for (int i = 0; i < n; i++) {
            totalWeight += pairs[i][1];
        }

        // Find the weighted median
        long median = 0L;
        long prefix = 0L;
        long half = (totalWeight + 1) / 2; // first position where prefix >= half
        for (int i = 0; i < n; i++) {
            prefix += pairs[i][1];
            if (prefix >= half) {
                median = pairs[i][0];
                break;
            }
        }

        // Compute total cost using the median
        long answer = 0L;
        for (int i = 0; i < n; i++) {
            long diff = Math.abs(pairs[i][0] - median);
            answer += diff * pairs[i][1];
        }

        return answer;
    }
}

