import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    private List<Integer>[] graph;
    private int[] values;
    private long targetSum;
    private int componentCount;

    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        this.values = nums;
        // build adjacency list
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int a = e[0];
            int b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        long total = 0;
        for (int v : nums) total += v;

        // special case: total sum is zero -> we can cut all edges
        if (total == 0) {
            return n - 1;
        }

        // collect all divisors of total sum (positive only)
        List<Long> divisors = new ArrayList<>();
        for (long i = 1; i * i <= total; i++) {
            if (total % i == 0) {
                divisors.add(i);
                if (i != total / i) {
                    divisors.add(total / i);
                }
            }
        }
        Collections.sort(divisors); // ascending target component sum

        int maxComponents = 1; // at least the whole tree
        for (long candTarget : divisors) {
            this.targetSum = candTarget;
            this.componentCount = 0;
            long remainder = dfs(0, -1);
            if (remainder == 0) {
                int comps = (int) (total / candTarget);
                if (comps > maxComponents) {
                    maxComponents = comps;
                }
            }
        }
        return maxComponents - 1; // deletions = components - 1
    }

    private long dfs(int node, int parent) {
        long sum = values[node];
        for (int nb : graph[node]) {
            if (nb == parent) continue;
            sum += dfs(nb, node);
        }
        if (sum == targetSum) {
            componentCount++;
            return 0;
        }
        return sum;
    }
}

