public class Solution {
    public int bestClosingTime(String customers) {
        int n = customers.length();
        int totalY = 0;
        for (int i = 0; i < n; i++) {
            if (customers.charAt(i) == 'Y') {
                totalY++;
            }
        }

        int bestHour = 0;
        int minPenalty = Integer.MAX_VALUE;
        int yPrefix = 0; // number of 'Y' in first j characters

        for (int j = 0; j <= n; j++) {
            // penalty = j + totalY - 2 * yPrefix
            int penalty = j + totalY - 2 * yPrefix;
            if (penalty < minPenalty) {
                minPenalty = penalty;
                bestHour = j;
            }
            // update yPrefix for next j (if not at end)
            if (j < n && customers.charAt(j) == 'Y') {
                yPrefix++;
            }
        }

        return bestHour;
    }
}

