public class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        if (digitSum(n) <= target) {
            return 0L;
        }
        long answer = Long.MAX_VALUE;
        long pow = 1L; // 10^i
        // iterate over positions, up to 18 (since 10^18 > Long.MAX_VALUE)
        for (int i = 0; i < 19; i++) {
            // compute candidate by rounding n up to the next multiple of pow
            long candidate = ((n / pow) + 1) * pow;
            if (digitSum(candidate) <= target) {
                answer = candidate - n;
                break; // this is the minimal addition because we increase pow progressively
            }
            // prepare next power of 10, avoid overflow
            if (pow > Long.MAX_VALUE / 10) {
                break;
            }
            pow *= 10L;
        }
        return answer;
    }

    private int digitSum(long x) {
        int sum = 0;
        while (x > 0) {
            sum += (int)(x % 10);
            x /= 10;
        }
        return sum;
    }
}

