import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    private static class UnionFind {
        int[] parent;
        int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    }

    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        // build adjacency list
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        // nodes sorted by value
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (i, j) -> Integer.compare(vals[i], vals[j]));

        UnionFind uf = new UnionFind(n);
        long answer = n; // each single node is a good path

        int idx = 0;
        while (idx < n) {
            int curVal = vals[order[idx]];
            // union all edges where both ends have value <= curVal
            int start = idx;
            while (idx < n && vals[order[idx]] == curVal) {
                int node = order[idx];
                for (int nb : graph[node]) {
                    if (vals[nb] <= curVal) {
                        uf.union(node, nb);
                    }
                }
                idx++;
            }
            // count nodes with current value per component
            Map<Integer, Integer> compCount = new HashMap<>();
            for (int i = start; i < idx; i++) {
                int node = order[i];
                int root = uf.find(node);
                compCount.put(root, compCount.getOrDefault(root, 0) + 1);
            }
            // add pairs inside each component
            for (int cnt : compCount.values()) {
                answer += (long) cnt * (cnt - 1) / 2;
            }
        }

        return (int) answer;
    }
}

