import java.util.Arrays;

/**
 * Solution for:
 *   Given an integer array {@code nums} and an integer {@code k},
 *   find the length of the longest strictly increasing subsequence
 *   where the difference between any two adjacent elements in the
 *   subsequence is at most {@code k}.
 *
 * The implementation uses a segment tree (range maximum query) on
 * the compressed values of {@code nums}. For each element we query
 * the best subsequence length among all previous elements whose
 * values lie in the interval {@code [num - k, num - 1]} and then
 * update the position of {@code num} with the new length.
 *
 * Time   : O(n log n)
 * Memory : O(m) where m = number of distinct values in {@code nums}
 */
public class Solution {

    /** Public API expected by the tests */
    public int lengthOfLIS(int[] nums, int k) {
        return longestSubsequence(nums, k);
    }

    /** Core implementation (kept unchanged) */
    public int longestSubsequence(int[] nums, int k) {
        if (nums == null || nums.length == 0) {
            return 0;
        }

        // ----- coordinate compression -----
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int m = 1;
        for (int i = 1; i < sorted.length; i++) {
            if (sorted[i] != sorted[i - 1]) {
                sorted[m++] = sorted[i];
            }
        }
        sorted = Arrays.copyOf(sorted, m); // unique sorted values

        // ----- segment tree for range maximum -----
        SegTree seg = new SegTree(m);

        int answer = 0;
        for (int num : nums) {
            // find the range of values that are < num and >= num - k
            int left = lowerBound(sorted, num - k);
            int right = lowerBound(sorted, num) - 1; // strictly less than num

            int best = 0;
            if (left <= right) {
                best = seg.query(left, right);
            }

            int curLen = best + 1;
            int idx = lowerBound(sorted, num); // exact position of num
            seg.update(idx, curLen); // keep the maximum length for this value

            if (curLen > answer) {
                answer = curLen;
            }
        }
        return answer;
    }

    /** binary search: first index >= target */
    private int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    /** segment tree supporting point update (max) and range max query */
    private static class SegTree {
        private final int n;          // size of the underlying array
        private final int[] tree;     // 1‑based segment tree

        SegTree(int n) {
            this.n = n;
            this.tree = new int[4 * n];
        }

        /** point update: set position idx to max(old, value) */
        void update(int idx, int value) {
            update(1, 0, n - 1, idx, value);
        }

        private void update(int node, int l, int r, int idx, int value) {
            if (l == r) {
                if (value > tree[node]) {
                    tree[node] = value;
                }
                return;
            }
            int mid = (l + r) >>> 1;
            if (idx <= mid) {
                update(node << 1, l, mid, idx, value);
            } else {
                update(node << 1 | 1, mid + 1, r, idx, value);
            }
            tree[node] = Math.max(tree[node << 1], tree[node << 1 | 1]);
        }

        /** range maximum query on inclusive interval [ql, qr] */
        int query(int ql, int qr) {
            return query(1, 0, n - 1, ql, qr);
        }

        private int query(int node, int l, int r, int ql, int qr) {
            if (qr < l || r < ql) {
                return 0; // neutral element for max
            }
            if (ql <= l && r <= qr) {
                return tree[node];
            }
            int mid = (l + r) >>> 1;
            int left = query(node << 1, l, mid, ql, qr);
            int right = query(node << 1 | 1, mid + 1, r, ql, qr);
            return Math.max(left, right);
        }
    }
}

