public class Solution {
    public int maximumValue(String[] strs) {
        int max = 0;
        if (strs == null) {
            return max;
        }
        for (String s : strs) {
            if (s == null) {
                continue;
            }
            int value;
            if (isAllDigits(s)) {
                try {
                    // Use long to avoid overflow during parsing, then clamp to int range if needed
                    long num = Long.parseLong(s);
                    if (num > Integer.MAX_VALUE) {
                        value = Integer.MAX_VALUE;
                    } else if (num < Integer.MIN_VALUE) {
                        value = Integer.MIN_VALUE;
                    } else {
                        value = (int) num;
                    }
                } catch (NumberFormatException e) {
                    // In case the number is too large for long, treat its value as length
                    value = s.length();
                }
            } else {
                value = s.length();
            }
            if (value > max) {
                max = value;
            }
        }
        return max;
    }

    private boolean isAllDigits(String s) {
        if (s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
