import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int beautifulPartitions(String s, int k, int minLength) {
        int n = s.length();
        if (k * minLength > n) return 0;

        boolean[] isPrime = new boolean[n];
        boolean[] isNonPrime = new boolean[n];
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '2' || c == '3' || c == '5' || c == '7') {
                isPrime[i] = true;
            } else {
                isNonPrime[i] = true; // digits are only '1'..'9', others are non‑prime
            }
        }

        // The whole string must start with a prime and end with a non‑prime
        if (!isPrime[0] || !isNonPrime[n - 1]) return 0;

        long[] dpPrev = new long[n];

        // Base case: first substring must start at index 0
        for (int i = 0; i < n; i++) {
            if (isNonPrime[i]) {
                int length = i - 0 + 1;
                if (length >= minLength) {
                    dpPrev[i] = 1; // exactly one way to end the first part at i
                }
            }
        }

        // Build DP for parts 2 .. k
        for (int part = 2; part <= k; part++) {
            long[] prefix = new long[n];
            long running = 0;
            for (int prev = 0; prev < n; prev++) {
                // If the next character can be the start of a new substring,
                // it must be a prime digit.
                if (prev + 1 < n && isPrime[prev + 1]) {
                    running = (running + dpPrev[prev]) % MOD;
                }
                prefix[prev] = running;
            }

            long[] dpCurr = new long[n];
            for (int i = 0; i < n; i++) {
                if (!isNonPrime[i]) continue; // substring must end with non‑prime
                int limit = i - minLength;
                if (limit >= 0) {
                    dpCurr[i] = prefix[limit];
                }
            }
            dpPrev = dpCurr;
        }

        return (int) (dpPrev[n - 1] % MOD);
    }
}

