public class Solution {
    public int minimizeXor(int num1, int num2) {
        int k = Integer.bitCount(num2); // required number of set bits
        int x = 0;

        // First, try to copy set bits from num1 starting from the most significant bit
        for (int i = 31; i >= 0 && k > 0; i--) {
            if (((num1 >> i) & 1) == 1) {
                x |= (1 << i);
                k--;
            }
        }

        // If we still need more set bits, set bits where num1 has 0,
        // starting from the least significant bit to keep xor minimal
        for (int i = 0; i <= 31 && k > 0; i++) {
            if (((num1 >> i) & 1) == 0) {
                x |= (1 << i);
                k--;
            }
        }

        return x;
    }
}

