import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            answer[i] = -1;
        }

        Deque<Integer> firstGreaterStack = new ArrayDeque<>();
        Deque<Integer> secondGreaterStack = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            int cur = nums[i];

            // Resolve pending second greater elements
            while (!secondGreaterStack.isEmpty() && nums[secondGreaterStack.peek()] < cur) {
                int idx = secondGreaterStack.pop();
                answer[idx] = cur;
            }

            // Move indices whose first greater is found to second stack
            while (!firstGreaterStack.isEmpty() && nums[firstGreaterStack.peek()] < cur) {
                int idx = firstGreaterStack.pop();
                secondGreaterStack.push(idx);
            }

            // Current index waits for its first greater
            firstGreaterStack.push(i);
        }

        return answer;
    }
}

