import java.util.Arrays;
import java.util.Comparator;
import java.util.PriorityQueue;

public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        // sort meetings by original start time
        Arrays.sort(meetings, Comparator.comparingInt(a -> a[0]));

        // priority queue of free rooms (by smallest index)
        PriorityQueue<Integer> freeRooms = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            freeRooms.offer(i);
        }

        // priority queue of occupied rooms (by earliest end time)
        // each element: [endTime, roomIndex]
        PriorityQueue<long[]> occupied = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));

        int[] count = new int[n];

        for (int[] meeting : meetings) {
            int start = meeting[0];
            int end = meeting[1];
            long duration = (long) end - start;

            // release rooms that have become free by current start time
            while (!occupied.isEmpty() && occupied.peek()[0] <= start) {
                long[] freed = occupied.poll();
                freeRooms.offer((int) freed[1]);
            }

            if (!freeRooms.isEmpty()) {
                // assign the smallest numbered free room
                int room = freeRooms.poll();
                count[room]++;
                occupied.offer(new long[]{end, room});
            } else {
                // all rooms are busy, delay the meeting
                long[] earliest = occupied.poll();
                long newStart = earliest[0];
                long newEnd = newStart + duration;
                int room = (int) earliest[1];
                count[room]++;
                occupied.offer(new long[]{newEnd, room});
            }
        }

        // find the room with the maximum meetings (lowest index on tie)
        int bestRoom = 0;
        int maxMeetings = count[0];
        for (int i = 1; i < n; i++) {
            if (count[i] > maxMeetings) {
                maxMeetings = count[i];
                bestRoom = i;
            }
        }
        return bestRoom;
    }
}

