public class Solution {
    public long countSubarrays(int[] nums, int minK, int maxK) {
        long result = 0L;
        int lastInvalid = -1;   // last index where element is out of [minK, maxK]
        int lastMin = -1;       // last index where element == minK
        int lastMax = -1;       // last index where element == maxK

        for (int i = 0; i < nums.length; i++) {
            int val = nums[i];

            // If current value breaks the allowed range, reset the window
            if (val < minK || val > maxK) {
                lastInvalid = i;
                lastMin = -1;
                lastMax = -1;
                continue;
            }

            // Update positions of minK and maxK if we see them
            if (val == minK) {
                lastMin = i;
            }
            if (val == maxK) {
                lastMax = i;
            }

            // Number of valid subarrays ending at i is determined by the
            // earliest of the last minK/maxK positions that is still after
            // the last invalid position.
            int earliestValid = Math.min(lastMin, lastMax);
            if (earliestValid > lastInvalid) {
                result += (earliestValid - lastInvalid);
            }
        }

        return result;
    }
}

