import java.util.ArrayList;
import java.util.List;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int[] productQueries(int n, int[][] queries) {
        // Build the list of powers of two that sum to n (sorted increasingly)
        List<Long> powers = new ArrayList<>();
        long value = 1;
        int temp = n;
        int bit = 0;
        while (temp > 0) {
            if ((temp & 1) == 1) {
                powers.add(value);
            }
            temp >>= 1;
            value <<= 1;
            bit++;
        }

        int m = powers.size();
        // Prefix products: pref[i] = product of powers[0..i-1]
        long[] pref = new long[m + 1];
        pref[0] = 1L;
        for (int i = 0; i < m; i++) {
            pref[i + 1] = (pref[i] * powers.get(i)) % MOD;
        }

        int q = queries.length;
        int[] ans = new int[q];
        for (int i = 0; i < q; i++) {
            int left = queries[i][0];
            int right = queries[i][1];
            long prod = pref[right + 1];
            long inv = modPow(pref[left], MOD - 2);
            long res = (prod * inv) % MOD;
            ans[i] = (int) res;
        }
        return ans;
    }

    // Fast exponentiation (base^exp % MOD)
    private long modPow(long base, long exp) {
        long result = 1L;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1L) == 1L) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            e >>= 1;
        }
        return result;
    }
}

