import java.util.ArrayList;
import java.util.List;

public class Solution {

    /**
     * Returns all words from {@code queries} that can be turned into some word in {@code dictionary}
     * with at most two character edits (i.e., Hamming distance ≤ 2).
     *
     * @param queries    array of query words, all of the same length
     * @param dictionary array of dictionary words, all of the same length as queries
     * @return list of matching query words in the original order
     */
    public List<String> twoEditWords(String[] queries, String[] dictionary) {
        List<String> result = new ArrayList<>();
        if (queries == null || dictionary == null || queries.length == 0 || dictionary.length == 0) {
            return result;
        }

        // All words have the same length according to the problem statement
        int wordLength = queries[0].length();

        for (String query : queries) {
            // Defensive check: skip if length differs
            if (query == null || query.length() != wordLength) {
                continue;
            }
            boolean matches = false;
            for (String dictWord : dictionary) {
                if (dictWord == null || dictWord.length() != wordLength) {
                    continue; // defensive, should not happen
                }
                int mismatches = 0;
                for (int i = 0; i < wordLength; i++) {
                    if (query.charAt(i) != dictWord.charAt(i)) {
                        mismatches++;
                        if (mismatches > 2) {
                            break; // more than two edits, stop checking this dictionary word
                        }
                    }
                }
                if (mismatches <= 2) {
                    matches = true;
                    break; // no need to check other dictionary words
                }
            }
            if (matches) {
                result.add(query);
            }
        }
        return result;
    }
}

