import java.util.HashSet;
import java.util.Set;

public class Solution {
    /**
     * Determines whether it is possible to remove exactly one character from the given word
     * so that all remaining letters have the same frequency.
     *
     * @param word a non‑null string consisting of lowercase English letters
     * @return true if such a removal exists, false otherwise
     */
    public boolean equalFrequency(String word) {
        int[] freq = new int[26];
        for (char c : word.toCharArray()) {
            freq[c - 'a']++;
        }

        // Try removing one occurrence of each letter that appears at least once
        for (int i = 0; i < 26; i++) {
            if (freq[i] == 0) {
                continue;
            }

            freq[i]--; // simulate removal

            Set<Integer> set = new HashSet<>();
            for (int f : freq) {
                if (f > 0) {
                    set.add(f);
                }
            }

            // If there are 0 or 1 distinct frequencies, condition is satisfied
            if (set.size() <= 1) {
                return true;
            }

            freq[i]++; // restore for next iteration
        }

        return false;
    }
}

