import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Solution {
    public long minimumMoney(int[][] transactions) {
        List<int[]> profit = new ArrayList<>();
        List<int[]> loss = new ArrayList<>();

        for (int[] t : transactions) {
            if (t[1] >= t[0]) {
                profit.add(t);
            } else {
                loss.add(t);
            }
        }

        // Profit transactions: worst case is encountering the largest cost first.
        profit.sort((a, b) -> Integer.compare(b[0], a[0])); // descending by cost

        // Loss transactions: worst case is encountering the largest net loss first,
        // tie‑breaker: larger cost first.
        loss.sort((a, b) -> {
            int diff = Integer.compare((b[0] - b[1]), (a[0] - a[1])); // larger net loss first
            if (diff != 0) {
                return diff;
            }
            return Integer.compare(b[0], a[0]); // larger cost first
        });

        long extraMoney = 0;
        long balance = 0;

        // Process loss transactions first (worst case)
        for (int[] t : loss) {
            long cost = t[0];
            long cash = t[1];
            if (balance < cost) {
                long deficit = cost - balance;
                extraMoney += deficit;
                balance = cost;
            }
            balance = balance - cost + cash; // net loss (balance may decrease)
        }

        // Then process profit transactions
        for (int[] t : profit) {
            long cost = t[0];
            long cash = t[1];
            if (balance < cost) {
                long deficit = cost - balance;
                extraMoney += deficit;
                balance = cost;
            }
            balance = balance - cost + cash; // net gain (balance will not go down)
        }

        return extraMoney;
    }
}

