import java.util.ArrayList;
import java.util.List;

public class Solution {
    public String[] splitMessage(String message, int limit) {
        if (message == null) {
            return new String[0];
        }
        int n = message.length();

        // Minimal possible suffix length is "<1/1>" which is 5 characters.
        if (limit < 5) {
            return new String[0];
        }

        int low = 1;
        int high = n; // at most n parts (each part must contain at least one character)
        int answer = -1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canSplit(message, limit, mid)) {
                answer = mid;
                high = mid - 1; // try to find a smaller number of parts
            } else {
                low = mid + 1;
            }
        }

        if (answer == -1) {
            return new String[0];
        }

        return buildParts(message, limit, answer);
    }

    private boolean canSplit(String message, int limit, int parts) {
        int total = 0;
        int digitsParts = digits(parts);
        for (int i = 1; i <= parts; i++) {
            int suffixLen = digits(i) + digitsParts + 3; // "<a/b>"
            int contentLen = limit - suffixLen;
            if (contentLen < 0) {
                return false;
            }
            total += contentLen;
            if (total >= message.length()) {
                return true;
            }
        }
        return total >= message.length();
    }

    private String[] buildParts(String message, int limit, int parts) {
        List<String> result = new ArrayList<>(parts);
        int idx = 0;
        for (int i = 1; i <= parts; i++) {
            String suffix = "<" + i + "/" + parts + ">";
            int contentLen = limit - suffix.length();
            int remaining = message.length() - idx;
            int take = Math.min(contentLen, remaining);
            String partContent = message.substring(idx, idx + take);
            idx += take;
            result.add(partContent + suffix);
        }
        return result.toArray(new String[0]);
    }

    private int digits(int x) {
        int cnt = 0;
        while (x > 0) {
            cnt++;
            x /= 10;
        }
        return cnt;
    }
}

