import java.util.*;

public class Solution {
    public int subarrayLCM(int[] nums, int k) {
        int n = nums.length;
        int count = 0;
        for (int i = 0; i < n; i++) {
            long lcm = 1L;
            for (int j = i; j < n; j++) {
                long a = nums[j];
                long g = gcd(lcm, a);
                // compute lcm = lcm / g * a, but stop if it exceeds k
                long tmp = lcm / g;
                // if tmp * a would exceed k, we can set lcm to k+1 to break later
                if (tmp > k / a) {
                    lcm = (long) k + 1;
                } else {
                    lcm = tmp * a;
                }
                if (lcm > k) {
                    break; // further extension cannot reduce LCM
                }
                if (lcm == k) {
                    count++;
                }
            }
        }
        return count;
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

