            int val = nums[right];
            windowSum += val;
            freq.put(val, freq.getOrDefault(val, 0) + 1);
            if (freq.get(val) == 2) {
                duplicateCount++;
            }

            // Shrink the window if it exceeds size k
            if (right - left + 1 > k) {
                int leftVal = nums[left];
                int cnt = freq.get(leftVal);
                if (cnt == 2) {
                    duplicateCount--;
                }
                if (cnt == 1) {
                    freq.remove(leftVal);
                } else {
                    freq.put(leftVal, cnt - 1);
                }
                windowSum -= leftVal;
                left++;
            }

            // When the window size is exactly k and all elements are distinct, evaluate sum
            if (right - left + 1 == k && duplicateCount == 0) {
                if (!found || windowSum > maxSum) {
                    maxSum = windowSum;
                    found = true;
                }
            }
        }

        // If no valid subarray was found, the answer should be 0
        return found ? maxSum : 0L;
    }
}

