public class Solution {
    /**
     * Removes every node that has a node with a strictly greater value anywhere to its right.
     *
     * @param head the head of the singly‑linked list
     * @return the head of the modified list
     */
    public ListNode removeNodes(ListNode head) {
        // Reverse the list to process from right to left
        ListNode reversed = reverse(head);

        // Build a new list keeping only nodes that are >= max seen so far
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        int max = Integer.MIN_VALUE;

        while (reversed != null) {
            if (reversed.val >= max) {
                max = reversed.val;
                tail.next = reversed;
                tail = reversed;
            }
            reversed = reversed.next;
        }

        // Ensure the new list is properly terminated
        tail.next = null;

        // Reverse again to restore original order
        return reverse(dummy.next);
    }

    /** Helper method to reverse a singly‑linked list. */
    private ListNode reverse(ListNode head) {
        ListNode prev = null;
        while (head != null) {
            ListNode next = head.next;
            head.next = prev;
            prev = head;
            head = next;
        }
        return prev;
    }

    /** Definition of singly‑linked list node. */
    public static class ListNode {
        public int val;
        public ListNode next;

        public ListNode() {}

        public ListNode(int val) {
            this.val = val;
        }

        public ListNode(int val, ListNode next) {
            this.val = val;
            this.next = next;
        }
    }
}

