public class Solution {
    /**
     * Finds the largest positive integer k such that both k and -k are present in the array.
     * If no such integer exists, returns -1.
     *
     * @param nums an array of non‑zero integers
     * @return the largest positive integer k with its negative counterpart, or -1 if none exists
     */
    public int findMaxK(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
