import java.util.Collections;
import java.util.PriorityQueue;

public class Solution {
    public int minimumDeviation(int[] nums) {
        // Max‑heap to always have the current largest element
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        int currentMin = Integer.MAX_VALUE;

        // Make every number even (odd numbers are multiplied by 2)
        for (int num : nums) {
            if ((num & 1) == 1) { // odd
                num <<= 1; // multiply by 2
            }
            maxHeap.offer(num);
            currentMin = Math.min(currentMin, num);
        }

        int answer = Integer.MAX_VALUE;

        // Continuously reduce the maximum element while it is even
        while (true) {
            int currentMax = maxHeap.poll();
            answer = Math.min(answer, currentMax - currentMin);

            // If the maximum is odd we cannot make it smaller any more
            if ((currentMax & 1) == 1) {
                break;
            }

            // Reduce the maximum by dividing by 2
            currentMax >>= 1;
            currentMin = Math.min(currentMin, currentMax);
            maxHeap.offer(currentMax);
        }

        return answer;
    }
}

