import java.util.*;

/**
 * Solution for the “Magnificent Sets” problem.
 *
 * The algorithm works as follows:
 * 1. Build the adjacency list of the graph.
 * 2. For each connected component:
 *    a) Verify that the component is bipartite (necessary because the
 *       required condition |group(b) – group(a)| = 1 forces a 2‑coloring).
 *    b) Compute the diameter of the component using two BFS passes.
 *    c) The maximum number of groups contributed by this component is
 *       diameter + 1.
 * 3. Sum the contributions of all components. If any component is not
 *    bipartite, return -1.
 */
public class Solution {

    /**
     * Returns the maximum number of groups that can be formed such that
     * for every edge (a, b) the absolute difference of the group indices of a
     * and b is exactly 1. If it is impossible, returns -1.
     *
     * @param n     number of nodes (1‑indexed)
     * @param edges undirected edges of the graph
     * @return maximum number of groups, or -1 if impossible
     */
    @SuppressWarnings("unchecked")
    public int magnificentSets(int n, int[][] edges) {
        // ---------- build adjacency list ----------
        List<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int a = e[0];
            int b = e[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        int[] color = new int[n + 1];          // 0 = uncolored, 1 / -1 = two colors
        boolean[] visited = new boolean[n + 1];
        int totalGroups = 0;

        // ---------- process each connected component ----------
        for (int start = 1; start <= n; start++) {
            if (visited[start]) {
                continue;
            }

            // ---- 1️⃣  BFS to check bipartiteness and collect component nodes ----
            Queue<Integer> q = new ArrayDeque<>();
            List<Integer> component = new ArrayList<>();

            q.offer(start);
            visited[start] = true;
            color[start] = 1;
            component.add(start);
            boolean isBipartite = true;

            while (!q.isEmpty() && isBipartite) {
                int u = q.poll();
                for (int v : graph[u]) {
                    if (color[v] == 0) {
                        color[v] = -color[u];
                    } else if (color[v] == color[u]) {
                        // odd cycle → not bipartite
                        return -1;
                    }
                    if (!visited[v]) {
                        visited[v] = true;
                        q.offer(v);
                        component.add(v);
                    }
                }
            }

            // ---- 2️⃣  Compute diameter of this component ----
            // First BFS: farthest node from any node in the component
            int farNode = bfsFarthest(start, graph);
            // Second BFS: diameter length from farNode
            int diameter = bfsDistance(farNode, graph);

            // The component can contribute (diameter + 1) groups
            totalGroups += diameter + 1;
        }

        return totalGroups;
    }

    /** BFS that returns the node farthest from src (by edge count). */
    private int bfsFarthest(int src, List<Integer>[] graph) {
        Queue<Integer> q = new ArrayDeque<>();
        int[] dist = new int[graph.length];
        Arrays.fill(dist, -1);
        q.offer(src);
        dist[src] = 0;
        int far = src;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                    if (dist[v] > dist[far]) {
                        far = v;
                    }
                }
            }
        }
        return far;
    }

    /** BFS that returns the maximum distance from src to any reachable node. */
    private int bfsDistance(int src, List<Integer>[] graph) {
        Queue<Integer> q = new ArrayDeque<>();
        int[] dist = new int[graph.length];
        Arrays.fill(dist, -1);
        q.offer(src);
        dist[src] = 0;
        int maxDist = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                    maxDist = Math.max(maxDist, dist[v]);
                }
            }
        }
        return maxDist;
    }
}

