import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        // dp[i]: minimum trips to deliver first i boxes (0 <= i <= n)
        int[] dp = new int[n + 1];
        // prePortChanges[i]: number of port changes among first i boxes (1‑based)
        int[] prePortChanges = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            if (i == 1) {
                prePortChanges[i] = 0;
            } else {
                prePortChanges[i] = prePortChanges[i - 1]
                        + (boxes[i - 1][0] != boxes[i - 2][0] ? 1 : 0);
            }
        }

        Deque<Integer> deque = new ArrayDeque<>();
        int left = 0;          // left index of current window (0‑based)
        int curWeight = 0;     // total weight of boxes in window

        for (int i = 1; i <= n; i++) {
            // extend window to include box i‑1
            curWeight += boxes[i - 1][1];

            // shrink window to satisfy constraints
            while (i - left > maxBoxes || curWeight > maxWeight) {
                curWeight -= boxes[left][1];
                left++;
            }

            // candidate index j = i‑1 (the position just before i)
            int j = i - 1;
            int candidateValue = dp[j] - prePortChanges[j + 1];
            while (!deque.isEmpty()) {
                int last = deque.peekLast();
                int lastValue = dp[last] - prePortChanges[last + 1];
                if (lastValue <= candidateValue) break;
                deque.pollLast();
            }
            deque.offerLast(j);

            // remove indices that are out of the current feasible window
            while (!deque.isEmpty() && deque.peekFirst() < left) {
                deque.pollFirst();
            }

            // best previous index is at the front of the deque
            int bestIdx = deque.peekFirst();
            // corrected recurrence: add +2 to account for the return trip
            dp[i] = (dp[bestIdx] - prePortChanges[bestIdx + 1]) + prePortChanges[i] + 2;
        }

        return dp[n];
    }
}

