public class Solution {
    public String getSmallestString(int n, int k) {
        // Start with all 'a's, each contributes 1 to the sum.
        char[] chars = new char[n];
        for (int i = 0; i < n; i++) {
            chars[i] = 'a';
        }

        // Remaining value to distribute after accounting for the initial 'a's.
        int remaining = k - n; // each position already has value 1

        // Distribute the remaining value from the end to keep the string lexicographically smallest.
        for (int i = n - 1; i >= 0 && remaining > 0; i--) {
            int add = Math.min(25, remaining); // max we can add to a position (a->z)
            chars[i] = (char) ('a' + add);
            remaining -= add;
        }

        return new String(chars);
    }
}

