import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Boolean> checkArithmeticSubarrays(int[] nums, int[] l, int[] r) {
        List<Boolean> answer = new ArrayList<>(l.length);
        for (int i = 0; i < l.length; i++) {
            int left = l[i];
            int right = r[i];
            int len = right - left + 1;

            // Subarrays of length 0 or 1 cannot be arithmetic by definition (need at least 2),
            // but the problem guarantees at least two elements in a valid query.
            // Still, treat them as true for safety.
            if (len <= 2) {
                answer.add(true);
                continue;
            }

            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            for (int j = left; j <= right; j++) {
                int val = nums[j];
                if (val < min) min = val;
                if (val > max) max = val;
            }

            // The common difference must be an integer.
            if ((max - min) % (len - 1) != 0) {
                answer.add(false);
                continue;
            }

            int diff = (max - min) / (len - 1);

            // When diff is zero, all numbers must be identical.
            if (diff == 0) {
                boolean allSame = true;
                for (int j = left; j <= right; j++) {
                    if (nums[j] != min) {
                        allSame = false;
                        break;
                    }
                }
                answer.add(allSame);
                continue;
            }

            boolean[] seen = new boolean[len];
            boolean ok = true;
            for (int j = left; j <= right; j++) {
                int val = nums[j];
                if ((val - min) % diff != 0) {
                    ok = false;
                    break;
                }
                int idx = (val - min) / diff;
                if (idx < 0 || idx >= len || seen[idx]) {
                    ok = false;
                    break;
                }
                seen[idx] = true;
            }
            answer.add(ok);
        }
        return answer;
    }
}

