import java.util.*;

public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        // Count frequencies of each unique number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }
        int[] counts = new int[freqMap.size()];
        int idx = 0;
        for (int v : freqMap.values()) {
            counts[idx++] = v;
        }
        // Sort counts descending to improve pruning
        Arrays.sort(counts);
        for (int i = 0, j = counts.length - 1; i < j; i++, j--) {
            int tmp = counts[i];
            counts[i] = counts[j];
            counts[j] = tmp;
        }

        int m = quantity.length;
        int totalMasks = 1 << m;
        int[] sumMask = new int[totalMasks];
        for (int mask = 1; mask < totalMasks; mask++) {
            int lsb = Integer.numberOfTrailingZeros(mask);
            int prev = mask ^ (1 << lsb);
            sumMask[mask] = sumMask[prev] + quantity[lsb];
        }

        // Memoization: dp[idx][mask] = Boolean (null = unknown)
        Boolean[][] memo = new Boolean[counts.length + 1][totalMasks];

        return dfs(0, (1 << m) - 1, counts, sumMask, memo);
    }

    private boolean dfs(int idx, int mask, int[] counts, int[] sumMask, Boolean[][] memo) {
        if (mask == 0) {
            return true; // all customers satisfied
        }
        if (idx == counts.length) {
            return false; // no more numbers to use
        }
        if (memo[idx][mask] != null) {
            return memo[idx][mask];
        }

        // Option 1: skip current count
        if (dfs(idx + 1, mask, counts, sumMask, memo)) {
            memo[idx][mask] = true;
            return true;
        }

        int curCount = counts[idx];
        // Iterate over all non‑empty submasks of mask
        for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
            if (sumMask[sub] <= curCount) {
                if (dfs(idx + 1, mask ^ sub, counts, sumMask, memo)) {
                    memo[idx][mask] = true;
                    return true;
                }
            }
        }

        memo[idx][mask] = false;
        return false;
    }
}

