import java.util.*;

public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) {
            return -1;
        }
        int groupSize = n / k;

        // If any number appears more than k times, impossible
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
            if (freq.get(num) > k) {
                return -1;
            }
        }

        int fullMask = (1 << n) - 1;
        int[] incompat = new int[1 << n];
        Arrays.fill(incompat, -1);

        // Pre‑compute incompatibility for every subset of size groupSize with distinct elements
        for (int mask = 0; mask <= fullMask; mask++) {
            if (Integer.bitCount(mask) != groupSize) {
                continue;
            }
            Set<Integer> seen = new HashSet<>();
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            boolean ok = true;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    int val = nums[i];
                    if (!seen.add(val)) {
                        ok = false;
                        break;
                    }
                    if (val < min) min = val;
                    if (val > max) max = val;
                }
            }
            if (ok) {
                incompat[mask] = max - min;
            }
        }

        int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[1 << n];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        // For each mask, try to add a valid group from the remaining elements
        for (int mask = 0; mask <= fullMask; mask++) {
            if (dp[mask] == INF) continue;
            int remaining = fullMask ^ mask; // elements not yet used
            // iterate over submasks of remaining that are valid groups
            // enumerate submask = remaining; submask > 0; submask = (submask - 1) & remaining
            for (int sub = remaining; sub > 0; sub = (sub - 1) & remaining) {
                if (incompat[sub] == -1) continue; // not a valid group
                int newMask = mask | sub;
                dp[newMask] = Math.min(dp[newMask], dp[mask] + incompat[sub]);
            }
        }

        return dp[fullMask] == INF ? -1 : dp[fullMask];
    }
}

