import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int createSortedArray(int[] instructions) {
        int n = instructions.length;
        // Coordinate compression
        int[] sorted = instructions.clone();
        Arrays.sort(sorted);
        Map<Integer, Integer> map = new HashMap<>();
        int idx = 1;
        for (int val : sorted) {
            if (!map.containsKey(val)) {
                map.put(val, idx++);
            }
        }

        FenwickTree bit = new FenwickTree(idx);
        long cost = 0L;

        for (int i = 0; i < n; i++) {
            int compressed = map.get(instructions[i]);
            long less = bit.query(compressed - 1);
            long greater = i - bit.query(compressed);
            cost += Math.min(less, greater);
            if (cost >= MOD) cost %= MOD;
            bit.update(compressed, 1);
        }

        return (int) (cost % MOD);
    }

    // Fenwick Tree (Binary Indexed Tree) for prefix sums
    private static class FenwickTree {
        private final long[] tree;
        private final int size;

        FenwickTree(int size) {
            this.size = size;
            this.tree = new long[size + 2];
        }

        // add delta at position index (1‑based)
        void update(int index, long delta) {
            while (index <= size) {
                tree[index] += delta;
                index += index & -index;
            }
        }

        // sum of values in [1, index] (inclusive)
        long query(int index) {
            long sum = 0;
            while (index > 0) {
                sum += tree[index];
                index -= index & -index;
            }
            return sum;
        }
    }
}

