import java.util.HashMap;
import java.util.Map;

public class Solution {
    // Base happiness: 0 = empty, 1 = introvert, 2 = extrovert
    private static final int[] BASE = {0, 120, 40};

    // neighbour effect on the *current* person only.
    // introvert loses 30 per neighbour, extrovert gains 20 per neighbour.
    private static final int[][] PAIR = {
            // neighbour:   0      1      2
            /* self 0 */ { 0,     0,     0 },   // empty cell – never used
            /* self 1 */ { 0,   -30,   -30 },   // introvert
            /* self 2 */ { 0,    20,    20 }    // extrovert
    };

    private int m, n;
    private int[] pow3;
    private Map<Long, Integer> memo;

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        this.m = m;
        this.n = n;
        pow3 = new int[n + 1];
        pow3[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow3[i] = pow3[i - 1] * 3;
        }
        memo = new HashMap<>();
        return dfs(0, introvertsCount, extrovertsCount, 0, 0);
    }

    private int dfs(int pos, int introLeft, int extroLeft, int prevMask, int curMask) {
        if (pos == m * n) {
            return 0;
        }
        long key = pack(pos, introLeft, extroLeft, prevMask, curMask);
        Integer cached = memo.get(key);
        if (cached != null) {
            return cached;
        }

        int row = pos / n;
        int col = pos % n;

        // type of left neighbour (already placed in current row)
        int leftType = (col == 0) ? 0 : (curMask % 3);
        // type of upper neighbour (from previous row)
        int upType = (prevMask / pow3[n - 1 - col]) % 3;

        // Option 1: leave this cell empty
        int newCurMaskEmpty = curMask * 3; // type 0 for empty
        int nextPrevMaskEmpty = (col == n - 1) ? newCurMaskEmpty : prevMask;
        int nextCurMaskEmpty = (col == n - 1) ? 0 : newCurMaskEmpty;
        int best = dfs(pos + 1, introLeft, extroLeft, nextPrevMaskEmpty, nextCurMaskEmpty);

        // Option 2: place an introvert
        if (introLeft > 0) {
            int self = 1;
            int added = BASE[self];
            // effect on the new introvert
            added += PAIR[self][leftType];
            added += PAIR[self][upType];
            // effect on the neighbours caused by this introvert
            added += PAIR[leftType][self];
            added += PAIR[upType][self];

            int newCurMask = curMask * 3 + self;

            int nextPrevMask = (col == n - 1) ? newCurMask : prevMask;
            int nextCurMask = (col == n - 1) ? 0 : newCurMask;

            int candidate = added + dfs(pos + 1, introLeft - 1, extroLeft, nextPrevMask, nextCurMask);
            if (candidate > best) {
                best = candidate;
            }
        }

        // Option 3: place an extrovert
        if (extroLeft > 0) {
            int self = 2;
            int added = BASE[self];
            // effect on the new extrovert
            added += PAIR[self][leftType];
            added += PAIR[self][upType];
            // effect on the neighbours caused by this extrovert
            added += PAIR[leftType][self];
            added += PAIR[upType][self];

            int newCurMask = curMask * 3 + self;

            int nextPrevMask = (col == n - 1) ? newCurMask : prevMask;
            int nextCurMask = (col == n - 1) ? 0 : newCurMask;

            int candidate = added + dfs(pos + 1, introLeft, extroLeft - 1, nextPrevMask, nextCurMask);
            if (candidate > best) {
                best = candidate;
            }
        }

        memo.put(key, best);
        return best;
    }

    private long pack(int pos, int intro, int extro, int prevMask, int curMask) {
        long key = pos;
        key = (key << 5) | intro;      // intro up to 25 -> fits in 5 bits
        key = (key << 5) | extro;      // extro up to 25
        key = (key << 9) | prevMask;   // prevMask up to 3^5 = 243 < 2^9
        key = (key << 9) | curMask;    // curMask same bound
        return key;
    }
}

