public class Solution {
    public int[] mostCompetitive(int[] nums, int k) {
        int n = nums.length;
        int[] stack = new int[k];
        int size = 0;
        for (int i = 0; i < n; i++) {
            // while we can remove the top element to make the sequence smaller
            while (size > 0 && stack[size - 1] > nums[i] && size - 1 + (n - i) >= k) {
                size--;
            }
            // if we still need more elements, push current one
            if (size < k) {
                stack[size++] = nums[i];
            }
        }
        return stack;
    }
}

