public class Solution {
    public double trimMean(int[] arr) {
        // Number of elements to remove from each end (5% of the array)
        int n = arr.length;
        int removeCount = (int) (n * 0.05); // floor of 5%

        // Sort the array to easily discard the smallest and largest elements
        Arrays.sort(arr);

        // Sum the remaining elements
        double sum = 0.0;
        int remaining = n - 2 * removeCount;
        for (int i = removeCount; i < n - removeCount; i++) {
            sum += arr[i];
        }

        // Compute and return the mean
        return sum / remaining;
    }
}

