public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        // dpL[i+1][j+1] = length of longest common suffix ending at s[i] and t[j]
        int[][] dpL = new int[n + 1][m + 1];
        for (int i = 1; i <= n; i++) {
            char cs = s.charAt(i - 1);
            for (int j = 1; j <= m; j++) {
                if (cs == t.charAt(j - 1)) {
                    dpL[i][j] = dpL[i - 1][j - 1] + 1;
                } else {
                    dpL[i][j] = 0;
                }
            }
        }

        // dpR[i][j] = length of longest common prefix starting at s[i] and t[j]
        int[][] dpR = new int[n + 1][m + 1];
        for (int i = n - 1; i >= 0; i--) {
            char cs = s.charAt(i);
            for (int j = m - 1; j >= 0; j--) {
                if (cs == t.charAt(j)) {
                    dpR[i][j] = dpR[i + 1][j + 1] + 1;
                } else {
                    dpR[i][j] = 0;
                }
            }
        }

        long ans = 0L;
        for (int i = 0; i < n; i++) {
            char cs = s.charAt(i);
            for (int j = 0; j < m; j++) {
                if (cs != t.charAt(j)) {
                    int left = dpL[i][j];          // common suffix before (i,j)
                    int right = dpR[i + 1][j + 1]; // common prefix after (i,j)
                    ans += (long) (left + 1) * (right + 1);
                }
            }
        }
        return (int) ans;
    }
}

