import java.util.*;

public class Solution {
    private static final long INF = Long.MAX_VALUE / 2; // prevent overflow

    public String kthSmallestPath(int[] destination, int k) {
        int v = destination[0]; // number of vertical moves 'V'
        int h = destination[1]; // number of horizontal moves 'H'

        // Pre‑compute binomial coefficients up to (v + h)
        long[][] comb = new long[v + h + 1][v + h + 1];
        for (int i = 0; i <= v + h; i++) {
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                long sum = comb[i - 1][j - 1] + comb[i - 1][j];
                comb[i][j] = sum >= INF ? INF : sum; // cap to avoid overflow
            }
        }

        StringBuilder sb = new StringBuilder();
        long kk = k; // use long for safety

        while (h > 0 || v > 0) {
            if (h == 0) {
                sb.append('V');
                v--;
                continue;
            }
            if (v == 0) {
                sb.append('H');
                h--;
                continue;
            }

            // Number of strings that start with 'H' given remaining moves
            long cnt = comb[h + v - 1][v]; // choose positions for v 'V's among remaining slots

            if (kk <= cnt) {
                sb.append('H');
                h--;
            } else {
                sb.append('V');
                kk -= cnt;
                v--;
            }
        }

        return sb.toString();
    }
}

