import java.util.*;

public class Solution {
    private static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) return;
            if (rank[rx] < rank[ry]) {
                parent[rx] = ry;
            } else if (rank[rx] > rank[ry]) {
                parent[ry] = rx;
            } else {
                parent[ry] = rx;
                rank[rx]++;
            }
        }
    }

    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] answer = new int[m][n];

        // Collect all cells
        List<int[]> cells = new ArrayList<>(m * n);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells.add(new int[]{matrix[i][j], i, j});
            }
        }

        // Sort by value
        cells.sort(Comparator.comparingInt(a -> a[0]));

        int[] rowMax = new int[m];
        int[] colMax = new int[n];

        int idx = 0;
        while (idx < cells.size()) {
            int start = idx;
            int curVal = cells.get(idx)[0];
            // gather same value batch
            while (idx < cells.size() && cells.get(idx)[0] == curVal) {
                idx++;
            }
            int end = idx; // exclusive

            // Union-Find for this batch
            UnionFind uf = new UnionFind(m * n);
            Map<Integer, Integer> rowMap = new HashMap<>();
            Map<Integer, Integer> colMap = new HashMap<>();

            for (int k = start; k < end; k++) {
                int i = cells.get(k)[1];
                int j = cells.get(k)[2];
                int id = i * n + j;

                if (rowMap.containsKey(i)) {
                    uf.union(id, rowMap.get(i));
                } else {
                    rowMap.put(i, id);
                }

                if (colMap.containsKey(j)) {
                    uf.union(id, colMap.get(j));
                } else {
                    colMap.put(j, id);
                }
            }

            // Determine rank for each component
            Map<Integer, Integer> rootRank = new HashMap<>();
            for (int k = start; k < end; k++) {
                int i = cells.get(k)[1];
                int j = cells.get(k)[2];
                int id = i * n + j;
                int root = uf.find(id);
                int needed = Math.max(rowMax[i], colMax[j]) + 1;
                rootRank.merge(root, needed, Math::max);
            }

            // Assign ranks and update row/col maxes
            for (int k = start; k < end; k++) {
                int i = cells.get(k)[1];
                int j = cells.get(k)[2];
                int id = i * n + j;
                int root = uf.find(id);
                int rank = rootRank.get(root);
                answer[i][j] = rank;
                rowMax[i] = rank;
                colMax[j] = rank;
            }
        }

        return answer;
    }
}

