import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int[] frequencySort(int[] nums) {
        // Count frequency of each number
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }

        // Convert to Integer array for custom sorting
        Integer[] boxed = new Integer[nums.length];
        for (int i = 0; i < nums.length; i++) {
            boxed[i] = nums[i];
        }

        // Sort by frequency (ascending), then by value (descending)
        Arrays.sort(boxed, (a, b) -> {
            int fa = freq.get(a);
            int fb = freq.get(b);
            if (fa != fb) {
                return Integer.compare(fa, fb); // lower frequency first
            }
            return Integer.compare(b, a); // higher value first when frequencies equal
        });

        // Write back to original array
        for (int i = 0; i < nums.length; i++) {
            nums[i] = boxed[i];
        }
        return nums;
    }
}

