public class Solution {

    private static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return;
            }
            // union by rank
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public List<Boolean> areConnected(int n, int threshold, int[][] queries) {
        UnionFind uf = new UnionFind(n + 1); // 1‑based indexing

        // If threshold >= n, no unions are needed because no divisor > threshold exists.
        for (int d = threshold + 1; d <= n; d++) {
            // Union all multiples of d together.
            for (int multiple = 2 * d; multiple <= n; multiple += d) {
                uf.union(d, multiple);
            }
        }

        List<Boolean> answer = new ArrayList<>(queries.length);
        for (int[] q : queries) {
            int a = q[0];
            int b = q[1];
            answer.add(uf.find(a) == uf.find(b));
        }
        return answer;
    }
}

