import java.util.*;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            graph[u].add(v);
            graph[v].add(u);
        }

        int[] answer = new int[n - 1];
        int totalMasks = 1 << n;
        int[] queue = new int[n]; // reusable queue for BFS

        for (int mask = 1; mask < totalMasks; mask++) {
            int nodeCount = Integer.bitCount(mask);
            if (nodeCount < 2) {
                continue; // diameter 0, not counted
            }

            // Find any node inside the subset to start BFS
            int start = Integer.numberOfTrailingZeros(mask);

            // First BFS: check connectivity and obtain a farthest node
            boolean[] visited = new boolean[n];
            int head = 0, tail = 0;
            visited[start] = true;
            queue[tail++] = start;
            int visitedCnt = 0;
            int farNode = start;

            while (head < tail) {
                int cur = queue[head++];
                visitedCnt++;
                farNode = cur;
                for (int nb : graph[cur]) {
                    if (((mask >> nb) & 1) == 1 && !visited[nb]) {
                        visited[nb] = true;
                        queue[tail++] = nb;
                    }
                }
            }

            if (visitedCnt != nodeCount) {
                continue; // subset is not connected
            }

            // Second BFS from farNode to compute the diameter
            int[] dist = new int[n];
            Arrays.fill(dist, -1);
            head = 0;
            tail = 0;
            dist[farNode] = 0;
            queue[tail++] = farNode;
            int maxDist = 0;

            while (head < tail) {
                int cur = queue[head++];
                for (int nb : graph[cur]) {
                    if (((mask >> nb) & 1) == 1 && dist[nb] == -1) {
                        dist[nb] = dist[cur] + 1;
                        maxDist = Math.max(maxDist, dist[nb]);
                        queue[tail++] = nb;
                    }
                }
            }

            // Diameter is maxDist (number of edges)
            answer[maxDist - 1]++; // convert to 0‑based index
        }

        return answer;
    }
}

