import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numWays(String[] words, String target) {
        int m = words[0].length();          // length of each word
        int n = target.length();            // length of target

        // count[c][pos] = how many words have character c at position pos
        int[][] count = new int[26][m];
        for (String w : words) {
            for (int pos = 0; pos < m; pos++) {
                char ch = w.charAt(pos);
                count[ch - 'a'][pos]++;
            }
        }

        // dp[i] = number of ways to form first i characters of target
        long[] dp = new long[n + 1];
        dp[0] = 1; // empty target can always be formed

        // iterate over each column (position) of the words
        for (int pos = 0; pos < m; pos++) {
            // update dp in reverse to avoid overwriting needed values
            for (int i = n - 1; i >= 0; i--) {
                char need = target.charAt(i);
                int waysHere = count[need - 'a'][pos];
                if (waysHere > 0) {
                    dp[i + 1] = (dp[i + 1] + dp[i] * waysHere) % MOD;
                }
            }
        }

        return (int) dp[n];
    }
}

