public class Solution {
    public int minDeletions(String s) {
        int[] freq = new int[26];
        for (char c : s.toCharArray()) {
            // assuming input consists of lowercase English letters
            if (c >= 'a' && c <= 'z') {
                freq[c - 'a']++;
            } else if (c >= 'A' && c <= 'Z') {
                // handle uppercase letters as well, mapping them to 0‑25
                freq[c - 'A']++;
            }
        }

        Set<Integer> used = new HashSet<>();
        int deletions = 0;

        for (int f : freq) {
            while (f > 0 && used.contains(f)) {
                f--;
                deletions++;
            }
            if (f > 0) {
                used.add(f);
            }
        }

        return deletions;
    }
}

