import java.util.HashMap;
import java.util.Map;

public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;

        // Count frequencies in nums1 and nums2
        Map<Integer, Integer> freq1 = new HashMap<>();
        Map<Integer, Integer> freq2 = new HashMap<>();

        for (int v : nums1) {
            freq1.put(v, freq1.getOrDefault(v, 0) + 1);
        }
        for (int v : nums2) {
            freq2.put(v, freq2.getOrDefault(v, 0) + 1);
        }

        // Feasibility check: for each value, its occurrences in nums1 must fit into positions
        // where nums2 does NOT have that value.
        for (Map.Entry<Integer, Integer> entry : freq1.entrySet()) {
            int val = entry.getKey();
            int cnt1 = entry.getValue();
            int cnt2 = freq2.getOrDefault(val, 0);
            if (cnt1 > n - cnt2) {
                return -1L;
            }
        }

        // If feasible, the minimum total cost is always the sum of all indices:
        // 0 + 1 + ... + (n-1) = n * (n - 1) / 2
        return (long) n * (n - 1) / 2;
    }
}

