import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int maxResult(int[] nums, int k) {
        int n = nums.length;
        int[] dp = new int[n];
        dp[0] = nums[0];

        Deque<Integer> deque = new ArrayDeque<>();
        deque.addLast(0); // store indices with decreasing dp values

        for (int i = 1; i < n; i++) {
            // Remove indices that are out of the current window [i-k, i-1]
            while (!deque.isEmpty() && deque.peekFirst() < i - k) {
                deque.pollFirst();
            }

            // The front of the deque holds the index with the maximum dp value in the window
            dp[i] = nums[i] + dp[deque.peekFirst()];

            // Maintain deque in decreasing order of dp values
            while (!deque.isEmpty() && dp[deque.peekLast()] <= dp[i]) {
                deque.pollLast();
            }
            deque.addLast(i);
        }

        return dp[n - 1];
    }
}

