            }
            String addedStr = new String(added);
            if (!visited.contains(addedStr)) {
                visited.add(addedStr);
                queue.offer(addedStr);
            }

            // Operation 2: rotate right by b positions
            int len = cur.length();
            int rot = b % len;
            String rotated = cur.substring(len - rot) + cur.substring(0, len - rot);
            if (!visited.contains(rotated)) {
                visited.add(rotated);
                queue.offer(rotated);
            }
        }

        return best;
    }
}

