import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        // If the field of view covers the whole circle, all points are visible.
        if (angle >= 360) {
            return points.size();
        }

        int sameLocationCount = 0;
        List<Double> angles = new ArrayList<>();

        int locX = location.get(0);
        int locY = location.get(1);

        for (List<Integer> p : points) {
            int x = p.get(0);
            int y = p.get(1);
            if (x == locX && y == locY) {
                sameLocationCount++;
                continue;
            }
            double dx = x - locX;
            double dy = y - locY;
            double theta = Math.toDegrees(Math.atan2(dy, dx));
            if (theta < 0) {
                theta += 360.0;
            }
            angles.add(theta);
        }

        Collections.sort(angles);
        int n = angles.size();
        // Duplicate the list with each angle + 360 to handle circular wrap‑around.
        List<Double> extended = new ArrayList<>(2 * n);
        extended.addAll(angles);
        for (double a : angles) {
            extended.add(a + 360.0);
        }

        int maxInWindow = 0;
        int j = 0;
        double eps = 1e-9; // tolerance for inclusive comparison

        for (int i = 0; i < n; i++) {
            // Expand the right end of the window as far as possible.
            while (j < i + n && extended.get(j) - extended.get(i) <= angle + eps) {
                j++;
            }
            maxInWindow = Math.max(maxInWindow, j - i);
        }

        return maxInWindow + sameLocationCount;
    }
}

