public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];
        if (k == 0) {
            // all zeros already by default
            return result;
        }

        if (k > 0) {
            // sum of next k elements
            int windowSum = 0;
            // initial window for i = 0: indices 1 .. k
            for (int i = 1; i <= k; i++) {
                windowSum += code[i % n];
            }
            for (int i = 0; i < n; i++) {
                result[i] = windowSum;
                // slide window: remove element at (i+1) and add element at (i+1+k)
                int outIdx = (i + 1) % n;
                int inIdx = (i + 1 + k) % n;
                windowSum = windowSum - code[outIdx] + code[inIdx];
            }
        } else { // k < 0
            int kk = -k; // number of previous elements to sum
            // initial window for i = 0: previous kk elements are the last kk elements
            int windowSum = 0;
            for (int i = n - kk; i < n; i++) {
                windowSum += code[i];
            }
            for (int i = 0; i < n; i++) {
                result[i] = windowSum;
                // slide window: for next i+1, we remove element that is now out of range
                // out element is at (i - kk + n) % n
                // in element is at i (the current element becomes part of the next window)
                int outIdx = (i - kk + n) % n;
                int inIdx = i;
                windowSum = windowSum - code[outIdx] + code[inIdx];
            }
        }

        return result;
    }
}

