import java.util.*;

public class Solution {

    private static class Pair {
        int pos;
        boolean lastBackward; // true if the previous jump was a backward jump

        public Pair(int pos, boolean lastBackward) {
            this.pos = pos;
            this.lastBackward = lastBackward;
        }
    }

    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        if (x == 0) {
            return 0;
        }

        int maxForbidden = 0;
        for (int f : forbidden) {
            maxForbidden = Math.max(maxForbidden, f);
        }

        // Upper bound for search space.
        int limit = Math.max(maxForbidden, x) + a + b + 1000;

        boolean[] isForbidden = new boolean[limit + 1];
        for (int f : forbidden) {
            if (f <= limit) {
                isForbidden[f] = true;
            }
        }

        // visited[position][0] -> arrived here with last jump NOT backward
        // visited[position][1] -> arrived here with last jump backward
        boolean[][] visited = new boolean[limit + 1][2];
        Queue<Pair> queue = new LinkedList<>();

        queue.offer(new Pair(0, false));
        visited[0][0] = true;

        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            steps++;
            for (int i = 0; i < size; i++) {
                Pair cur = queue.poll();
                int pos = cur.pos;
                boolean lastBackward = cur.lastBackward;

                // Forward jump
                int forwardPos = pos + a;
                if (forwardPos == x) {
                    return steps;
                }
                if (forwardPos <= limit && !isForbidden[forwardPos] && !visited[forwardPos][0]) {
                    visited[forwardPos][0] = true;
                    queue.offer(new Pair(forwardPos, false));
                }

                // Backward jump (only if previous jump was not backward)
                if (!lastBackward) {
                    int backwardPos = pos - b;
                    if (backwardPos == x) {
                        return steps;
                    }
                    if (backwardPos >= 0 && !isForbidden[backwardPos] && !visited[backwardPos][1]) {
                        visited[backwardPos][1] = true;
                        queue.offer(new Pair(backwardPos, true));
                    }
                }
            }
        }

        return -1; // unreachable
    }
}

