public class Solution {
    public int waysToMakeFair(int[] nums) {
        int n = nums.length;
        // prefix sums for even and odd indices
        int[] prefEven = new int[n];
        int[] prefOdd = new int[n];
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                prefEven[i] = (i % 2 == 0) ? nums[i] : 0;
                prefOdd[i] = (i % 2 != 0) ? nums[i] : 0;
            } else {
                prefEven[i] = prefEven[i - 1];
                prefOdd[i] = prefOdd[i - 1];
                if (i % 2 == 0) {
                    prefEven[i] += nums[i];
                } else {
                    prefOdd[i] += nums[i];
                }
            }
        }

        int totalEven = prefEven[n - 1];
        int totalOdd = prefOdd[n - 1];
        int count = 0;

        for (int i = 0; i < n; i++) {
            int leftEven = (i > 0) ? prefEven[i - 1] : 0;
            int leftOdd = (i > 0) ? prefOdd[i - 1] : 0;

            int rightEven = totalEven - prefEven[i];
            int rightOdd = totalOdd - prefOdd[i];

            // after removal, right side indices flip parity
            int newEven = leftEven + rightOdd;
            int newOdd = leftOdd + rightEven;

            if (newEven == newOdd) {
                count++;
            }
        }

        return count;
    }
}

