public class Solution {
    public int countStudents(int[] students, int[] sandwiches) {
        // Count how many students prefer each type of sandwich
        int[] prefCount = new int[2]; // index 0 for circular, 1 for square
        for (int s : students) {
            if (s == 0 || s == 1) {
                prefCount[s]++;
            }
        }

        // Process sandwiches in order (top of the stack is index 0)
        for (int sandwich : sandwiches) {
            if (prefCount[sandwich] > 0) {
                // A student who likes this sandwich exists; serve one
                prefCount[sandwich]--;
            } else {
                // No student wants this sandwich; all remaining students cannot eat
                break;
            }
        }

        // Remaining students are those still counted in prefCount
        return prefCount[0] + prefCount[1];
    }
}

