import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public int minimumMountainRemovals(int[] nums) {
        int n = nums.length;
        if (n < 3) {
            return n;
        }

        int[] inc = new int[n]; // LIS ending at i
        List<Integer> tails = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int pos = Collections.binarySearch(tails, nums[i]);
            if (pos < 0) {
                pos = -pos - 1;
            }
            if (pos == tails.size()) {
                tails.add(nums[i]);
            } else {
                tails.set(pos, nums[i]);
            }
            inc[i] = pos + 1;
        }

        int[] dec = new int[n]; // LDS starting at i
        tails.clear();

        for (int i = n - 1; i >= 0; i--) {
            int pos = Collections.binarySearch(tails, nums[i]);
            if (pos < 0) {
                pos = -pos - 1;
            }
            if (pos == tails.size()) {
                tails.add(nums[i]);
            } else {
                tails.set(pos, nums[i]);
            }
            dec[i] = pos + 1;
        }

        int maxMountain = 0;
        for (int i = 0; i < n; i++) {
            if (inc[i] > 1 && dec[i] > 1) {
                int len = inc[i] + dec[i] - 1;
                if (len > maxMountain) {
                    maxMountain = len;
                }
            }
        }

        return n - maxMountain;
    }
}

