import java.util.Arrays;
import java.util.Comparator;
import java.util.PriorityQueue;

public class Solution {
    public int minimumEffortPath(int[][] heights) {
        int rows = heights.length;
        int cols = heights[0].length;

        int[][] effort = new int[rows][cols];
        for (int[] row : effort) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        effort[0][0] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[2]));
        // each element: {row, col, currentEffort}
        pq.offer(new int[]{0, 0, 0});

        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, 1, 0, -1};

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int r = cur[0];
            int c = cur[1];
            int curEffort = cur[2];

            if (r == rows - 1 && c == cols - 1) {
                return curEffort;
            }

            if (curEffort > effort[r][c]) {
                continue; // already found a better path to this cell
            }

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                int diff = Math.abs(heights[r][c] - heights[nr][nc]);
                int nextEffort = Math.max(curEffort, diff);
                if (nextEffort < effort[nr][nc]) {
                    effort[nr][nc] = nextEffort;
                    pq.offer(new int[]{nr, nc, nextEffort});
                }
            }
        }

        // Should never reach here for a valid grid
        return -1;
    }
}

