public class Solution {
    public int stoneGameVII(int[] stones) {
        int n = stones.length;
        if (n == 0) return 0;
        // prefix sums for O(1) interval sum queries
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + stones[i];
        }

        // dp[i][j] = maximum score difference the current player can achieve
        // over the opponent for the subarray stones[i..j]
        int[][] dp = new int[n][n];

        // consider intervals of increasing length
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                int total = prefix[j + 1] - prefix[i]; // sum of stones[i..j]

                // Remove leftmost stone
                int removeLeft = (total - stones[i]) - dp[i + 1][j];
                // Remove rightmost stone
                int removeRight = (total - stones[j]) - dp[i][j - 1];

                dp[i][j] = Math.max(removeLeft, removeRight);
            }
        }

        return dp[0][n - 1];
    }
}

