import com_github_leetcode.ListNode;

/**
 * Solution for merging {@code list2} into {@code list1} by removing the nodes from index {@code a}
 * to index {@code b} (inclusive) and inserting {@code list2} in their place.
 */
public class Solution {

    /**
     * Merges {@code list2} into {@code list1} by removing the nodes from index {@code a}
     * to index {@code b} (inclusive) and inserting {@code list2} in their place.
     *
     * @param list1 the first linked list
     * @param a     start index (0‑based) of the segment to be removed from {@code list1}
     * @param b     end index (0‑based) of the segment to be removed from {@code list1}
     * @param list2 the linked list to insert (may be {@code null})
     * @return the head of the merged linked list
     */
    public ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
        // Dummy node simplifies handling when a == 0
        ListNode dummy = new ListNode(0);
        dummy.next = list1;

        // Locate the node just before position a
        ListNode prev = dummy;
        for (int i = 0; i < a; i++) {
            if (prev == null) {
                // Invalid input; return original list
                return dummy.next;
            }
            prev = prev.next;
        }

        // Locate the node right after position b
        ListNode cur = prev;
        for (int i = 0; i <= b - a; i++) {
            if (cur == null) {
                // Invalid input; return original list
                return dummy.next;
            }
            cur = cur.next;
        }
        ListNode post = cur; // node after b‑th node

        // If list2 is null, just connect prev directly to post
        if (list2 == null) {
            prev.next = post;
            return dummy.next;
        }

        // Connect the part before a with list2
        prev.next = list2;

        // Find the tail of list2
        ListNode tail = list2;
        while (tail.next != null) {
            tail = tail.next;
        }

        // Connect the tail of list2 with the remaining part of list1
        tail.next = post;

        return dummy.next;
    }
}

