import java.util.PriorityQueue;

public class Solution {
    public int furthestBuilding(int[] heights, int bricks, int ladders) {
        // Min-heap to store the climbs where we have used ladders so far
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        long remainingBricks = bricks; // use long to avoid overflow when subtracting

        for (int i = 0; i < heights.length - 1; i++) {
            int climb = heights[i + 1] - heights[i];
            if (climb <= 0) {
                // No resources needed for non‑positive climb
                continue;
            }

            // Assume we use a ladder for this climb for now
            minHeap.offer(climb);

            // If we have used more ladders than available, replace the smallest ladder usage with bricks
            if (minHeap.size() > ladders) {
                int smallestClimb = minHeap.poll();
                remainingBricks -= smallestClimb;
                if (remainingBricks < 0) {
                    // Not enough bricks to cover this climb, cannot reach building i+1
                    return i;
                }
            }
        }

        // If we processed all climbs successfully, we can reach the last building
        return heights.length - 1;
    }
}

