import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    private static long modPow(long base, long exp) {
        long result = 1L;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    private static long[] factorial;
    private static long[] invFactorial;

    private static void prepareFactorials(int limit) {
        factorial = new long[limit + 1];
        invFactorial = new long[limit + 1];
        factorial[0] = 1L;
        for (int i = 1; i <= limit; i++) {
            factorial[i] = (factorial[i - 1] * i) % MOD;
        }
        invFactorial[limit] = modPow(factorial[limit], MOD - 2);
        for (int i = limit; i > 0; i--) {
            invFactorial[i - 1] = (invFactorial[i] * i) % MOD;
        }
    }

    private static long nCr(int n, int r) {
        if (r < 0 || r > n) return 0L;
        return (((factorial[n] * invFactorial[r]) % MOD) * invFactorial[n - r]) % MOD;
    }

    public int numberOfSets(int n, int k) {
        // Minimum number of points needed is k + 1 (each segment needs at least two points,
        // and they can share endpoints).
        if (k == 0) return 1;
        if (n < k + 1) return 0;

        int total = n + k - 1;          // N in the formula C(N, 2k)
        int choose = 2 * k;             // r in the formula

        if (choose > total) return 0;

        prepareFactorials(total);
        long ans = nCr(total, choose);
        return (int) ans;
    }
}

