import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;
import java.util.TreeSet;

public class Solution {

    private static class Server {
        int id;
        long finishTime; // use long to avoid overflow

        Server(int id, long finishTime) {
            this.id = id;
            this.finishTime = finishTime;
        }
    }

    /**
     * Returns the list of server IDs that handled the most requests.
     *
     * @param k       number of servers
     * @param arrival arrival times of the requests (strictly increasing)
     * @param load    processing time of each request
     * @return list of busiest server IDs
     */
    public List<Integer> busiestServers(int k, int[] arrival, int[] load) {
        int n = arrival.length;
        int[] handled = new int[k];

        // servers that are currently free
        TreeSet<Integer> free = new TreeSet<>();
        for (int i = 0; i < k; i++) {
            free.add(i);
        }

        // servers that are busy, ordered by when they become free
        PriorityQueue<Server> busy = new PriorityQueue<>(Comparator.comparingLong(s -> s.finishTime));

        for (int i = 0; i < n; i++) {
            long curTime = arrival[i];

            // release servers that have finished by curTime
            while (!busy.isEmpty() && busy.peek().finishTime <= curTime) {
                Server s = busy.poll();
                free.add(s.id);
            }

            if (free.isEmpty()) {
                // all servers are busy, drop the request
                continue;
            }

            int target = i % k;
            Integer serverId = free.ceiling(target);
            if (serverId == null) {
                // wrap around
                serverId = free.first();
            }

            // assign request to serverId
            handled[serverId]++;
            free.remove(serverId);
            long finish = curTime + load[i];
            busy.offer(new Server(serverId, finish));
        }

        // find maximum handled count
        int max = 0;
        for (int cnt : handled) {
            if (cnt > max) {
                max = cnt;
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            if (handled[i] == max) {
                result.add(i);
            }
        }
        return result;
    }
}

