        int n = aliceValues.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) {
            idx[i] = i;
        }

        // Sort stones by the sum of both players' values in descending order
        Arrays.sort(idx, new Comparator<Integer>() {
            @Override
            public int compare(Integer i1, Integer i2) {
                long sum1 = (long) aliceValues[i1] + bobValues[i1];
                long sum2 = (long) aliceValues[i2] + bobValues[i2];
                return Long.compare(sum2, sum1); // descending
            }
        });

        long aliceScore = 0;
        long bobScore = 0;

        // Simulate the game: Alice picks on even turns, Bob on odd turns
        for (int turn = 0; turn < n; turn++) {
            int i = idx[turn];
            if ((turn & 1) == 0) { // Alice's turn
                aliceScore += aliceValues[i];
            } else { // Bob's turn
                bobScore += bobValues[i];
            }
        }

        if (aliceScore > bobScore) {
            return 1;
        } else if (aliceScore < bobScore) {
            return -1;
        } else {
            return 0;
        }
    }
}

