import java.util.Arrays;

public class Solution {

    // Disjoint Set Union (Union-Find) implementation
    private static class Dsu {
        private final int[] parent;
        private final int[] rank;

        public Dsu(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return;
            }
            // union by rank
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    /**
     * Determines for each query whether there exists a path between p and q such that
     * every edge on the path has a distance strictly less than the given limit.
     *
     * @param n        number of nodes in the graph (nodes are labeled from 0 to n-1)
     * @param edgeList array of edges, each edge is [u, v, distance]
     * @param queries  array of queries, each query is [p, q, limit]
     * @return boolean array where each element corresponds to the answer of a query
     */
    public boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        // Sort edges by distance (ascending)
        Arrays.sort(edgeList, (a, b) -> Integer.compare(a[2], b[2]));

        // Prepare queries with original indices
        int m = queries.length;
        int[][] queriesWithIndex = new int[m][4]; // [p, q, limit, originalIndex]
        for (int i = 0; i < m; i++) {
            queriesWithIndex[i][0] = queries[i][0];
            queriesWithIndex[i][1] = queries[i][1];
            queriesWithIndex[i][2] = queries[i][2];
            queriesWithIndex[i][3] = i;
        }
        // Sort queries by limit (ascending)
        Arrays.sort(queriesWithIndex, (a, b) -> Integer.compare(a[2], b[2]));

        boolean[] answer = new boolean[m];
        Dsu dsu = new Dsu(n);
        int edgeIdx = 0;
        int edgeCount = edgeList.length;

        // Process each query in order of increasing limit
        for (int[] q : queriesWithIndex) {
            int p = q[0];
            int r = q[1];
            int limit = q[2];
            int idx = q[3];

            // Add all edges with distance < limit to DSU
            while (edgeIdx < edgeCount && edgeList[edgeIdx][2] < limit) {
                dsu.union(edgeList[edgeIdx][0], edgeList[edgeIdx][1]);
                edgeIdx++;
            }

            // After adding relevant edges, check connectivity
            answer[idx] = dsu.find(p) == dsu.find(r);
        }

        return answer;
    }
}

