public class Solution {
    private int max;
    private int[] balance;
    private int[][] reqs;

    public int maximumRequests(int n, int[][] requests) {
        this.max = 0;
        this.balance = new int[n];
        this.reqs = requests;
        dfs(0, 0);
        return max;
    }

    private void dfs(int idx, int count) {
        if (idx == reqs.length) {
            if (isBalanced()) {
                if (count > max) {
                    max = count;
                }
            }
            return;
        }

        // Choose current request
        int from = reqs[idx][0];
        int to = reqs[idx][1];
        balance[from]--;
        balance[to]++;
        dfs(idx + 1, count + 1);
        // Backtrack
        balance[from]++;
        balance[to]--;

        // Skip current request
        dfs(idx + 1, count);
    }

    private boolean isBalanced() {
        for (int b : balance) {
            if (b != 0) {
                return false;
            }
        }
        return true;
    }
}

