public class Solution {
    public int minimumOneBitOperations(int n) {
        return dfs(n);
    }

    private int dfs(int n) {
        if (n == 0) {
            return 0;
        }
        int msb = Integer.highestOneBit(n);               // highest power of two ≤ n
        int k = 31 - Integer.numberOfLeadingZeros(msb);   // position of that bit
        long allOnes = (1L << (k + 1)) - 1;                // binary number with (k+1) ones
        return (int) (allOnes - dfs(n - msb));
    }
}

