public class Solution {
    public int maxLengthBetweenEqualCharacters(String s) {
        // Array to store first occurrence index for each lowercase letter.
        // Assuming input may contain any ASCII characters, we can use a map,
        // but using an int array of size 256 works for all possible char values.
        int[] firstPos = new int[256];
        // Initialize with -1 indicating not seen yet.
        for (int i = 0; i < firstPos.length; i++) {
            firstPos[i] = -1;
        }

        int maxLen = -1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            int idx = c; // implicit cast to int (0‑255 for standard ASCII/Unicode BMP)
            if (firstPos[idx] == -1) {
                // first time we see this character
                firstPos[idx] = i;
            } else {
                // character seen before, compute length between the two equal chars
                int lenBetween = i - firstPos[idx] - 1;
                if (lenBetween > maxLen) {
                    maxLen = lenBetween;
                }
                // No need to update firstPos because we want the earliest occurrence
                // to maximize the distance; keeping the first index yields the longest
                // possible substring for this character.
            }
        }
        return maxLen;
    }
}

