import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int minOperations(int[] nums, int x) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        int target = total - x; // we need a subarray with this sum
        if (target < 0) {
            return -1; // cannot exceed total sum
        }
        // If target is 0, we need to remove all elements
        if (target == 0) {
            return nums.length;
        }

        Map<Integer, Integer> firstIndex = new HashMap<>();
        firstIndex.put(0, -1); // prefix sum 0 at index -1
        int prefix = 0;
        int maxLen = -1;

        for (int i = 0; i < nums.length; i++) {
            prefix += nums[i];
            // store earliest occurrence of this prefix sum
            if (!firstIndex.containsKey(prefix)) {
                firstIndex.put(prefix, i);
            }
            // check if there is a previous prefix that makes a subarray sum == target
            if (firstIndex.containsKey(prefix - target)) {
                int prevIdx = firstIndex.get(prefix - target);
                int len = i - prevIdx;
                if (len > maxLen) {
                    maxLen = len;
                }
            }
        }

        return maxLen == -1 ? -1 : nums.length - maxLen;
    }
}

