public class Solution {
    public int countVowelStrings(int n) {
        // The number of lexicographically sorted vowel strings of length n
        // equals the number of multisets of size n drawn from 5 vowels:
        // C(n + 5 - 1, 5 - 1) = C(n + 4, 4)
        long result = 1;
        for (int i = 1; i <= 4; i++) {
            result = result * (n + i) / i;
        }
        return (int) result;
    }
