public class Solution {
    public int minimumDeletions(String s) {
        int n = s.length();
        // total number of 'a' characters in the whole string
        int totalA = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == 'a') {
                totalA++;
            }
        }

        int minDeletions = totalA; // delete all 'a's (split before first character)
        int bCount = 0;            // number of 'b's seen so far (to the left of split)
        int aSeen = 0;             // number of 'a's seen so far (to the left of split)

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == 'b') {
                bCount++;
            } else { // c == 'a'
                aSeen++;
            }
            // deletions needed if we split after position i (i.e., keep prefix [0..i])
            // need to delete all 'b's in the prefix and all 'a's in the suffix
            int deletions = bCount + (totalA - aSeen);
            if (deletions < minDeletions) {
                minDeletions = deletions;
            }
        }

        return minDeletions;
    }
}

