public class Solution {
    public List<String> alertNames(String[] keyName, String[] keyTime) {
        // Map each worker to a list of minutes when they used the key-card
        Map<String, List<Integer>> timeMap = new HashMap<>();
        for (int i = 0; i < keyName.length; i++) {
            String name = keyName[i];
            int minutes = toMinutes(keyTime[i]);
            timeMap.computeIfAbsent(name, k -> new ArrayList<>()).add(minutes);
        }

        List<String> alerted = new ArrayList<>();

        // Check each worker's usage times
        for (Map.Entry<String, List<Integer>> entry : timeMap.entrySet()) {
            List<Integer> times = entry.getValue();
            Collections.sort(times);
            // Sliding window of size 3
            for (int i = 0; i + 2 < times.size(); i++) {
                if (times.get(i + 2) - times.get(i) <= 60) {
                    alerted.add(entry.getKey());
                    break; // no need to check further for this worker
                }
            }
        }

        Collections.sort(alerted);
        return alerted;
    }

    // Helper to convert "HH:MM" to total minutes since 00:00
    private int toMinutes(String time) {
        int hour = Integer.parseInt(time.substring(0, 2));
        int minute = Integer.parseInt(time.substring(3, 5));
        return hour * 60 + minute;
    }
}

