import java.util.Arrays;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int maxProfit(int[] inventory, int orders) {
        Arrays.sort(inventory);
        int n = inventory.length;
        long result = 0;
        int idx = n - 1; // start from the largest count

        while (orders > 0 && idx >= 0) {
            int cur = inventory[idx];
            int next = (idx == 0) ? 0 : inventory[idx - 1];
            int count = n - idx; // number of colors with at least 'cur' balls

            long diff = cur - next; // how many levels we can drop
            long ballsCanSell = diff * count;

            if (orders >= ballsCanSell) {
                // sell all balls from cur down to next+1
                long sum = arithmeticSum(next + 1, cur);
                result = (result + sum % MOD * count) % MOD;
                orders -= ballsCanSell;
                idx--;
            } else {
                // we can only sell part of this range
                long fullLevels = orders / count; // complete levels we can drop
                long remainder = orders % count;   // remaining single balls

                long low = cur - fullLevels + 1;
                long high = cur;
                long sum = arithmeticSum(low, high);
                result = (result + sum % MOD * count) % MOD;

                // sell the remaining 'remainder' balls at price (cur - fullLevels)
                long price = cur - fullLevels;
                result = (result + (price % MOD) * remainder) % MOD;

                orders = 0; // all orders fulfilled
            }
        }

        return (int) (result % MOD);
    }

    // sum of integers from low to high inclusive
    private long arithmeticSum(long low, long high) {
        long terms = high - low + 1;
        return (low + high) * terms / 2;
    }
}

