import java.util.Arrays;

public class Solution {
    public int minimumEffort(int[][] tasks) {
        // Sort tasks according to the greedy strategy:
        // 1) Gain tasks (actual >= minimum) first, sorted by ascending minimum.
        // 2) Loss tasks (actual < minimum) after, sorted by descending actual.
        Arrays.sort(tasks, (a, b) -> {
            boolean aGain = a[0] >= a[1];
            boolean bGain = b[0] >= b[1];
            if (aGain && bGain) {
                return Integer.compare(a[1], b[1]); // both gain: by minimum asc
            }
            if (!aGain && !bGain) {
                return Integer.compare(b[0], a[0]); // both loss: by actual desc
            }
            // gain tasks should come before loss tasks
            return aGain ? -1 : 1;
        });

        long need = 0;    // minimal initial energy required
        long current = 0; // energy after completing processed tasks

        for (int[] task : tasks) {
            int actual = task[0];
            int minimum = task[1];

            if (current < minimum) {
                // accumulate the whole deficit to the required initial energy
                need += (minimum - current);
                current = minimum;
            }

            // Apply the net change of this task
            current += (actual - minimum);
        }

        return (int) need;
    }
}

