public class Solution {
    public int maximalNetworkRank(int n, int[][] roads) {
        if (n <= 1) {
            return 0;
        }

        int[] degree = new int[n];
        boolean[][] connected = new boolean[n][n];

        // Build degree array and adjacency matrix
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            degree[a]++;
            degree[b]++;
            connected[a][b] = true;
            connected[b][a] = true;
        }

        int maxRank = 0;
        // Evaluate every unordered pair of distinct cities
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int rank = degree[i] + degree[j];
                if (connected[i][j]) {
                    rank--; // road counted twice, subtract once
                }
                if (rank > maxRank) {
                    maxRank = rank;
                }
            }
        }

        return maxRank;
    }
}

