public class Solution {
    public int countBinarySubstrings(String s) {
        if (s == null || s.length() == 0) {
            return 0;
        }
        int prevRun = 0;   // length of the previous run of identical characters
        int curRun = 1;    // length of the current run (starts with first character)
        int result = 0;

        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                curRun++;
            } else {
                // transition to a new run
                result += Math.min(prevRun, curRun);
                prevRun = curRun;
                curRun = 1;
            }
        }
        // add the last comparison
        result += Math.min(prevRun, curRun);
        return result;
    }
}

