public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int maxSum = 2 * limit;
        // difference array for prefix sum, size maxSum + 2 to handle hi+1 and sum+1
        int[] diff = new int[maxSum + 2];

        for (int i = 0; i < n / 2; i++) {
            int a = nums[i];
            int b = nums[n - 1 - i];

            int low = Math.min(a, b) + 1;          // smallest sum achievable with 1 change
            int high = Math.max(a, b) + limit;    // largest sum achievable with 1 change
            int sum = a + b;                       // sum with 0 changes

            // Initially assume 2 moves for every possible sum [2, 2*limit]
            diff[2] += 2;
            diff[maxSum + 1] -= 2;

            // Reduce by 1 move for sums that can be achieved with a single change
            diff[low] -= 1;
            diff[high + 1] += 1;

            // Reduce by another 1 move for the exact original sum (0 moves needed)
            diff[sum] -= 1;
            diff[sum + 1] += 1;
        }

        int minMoves = Integer.MAX_VALUE;
        int cur = 0;
        for (int s = 2; s <= maxSum; s++) {
            cur += diff[s];
            if (cur < minMoves) {
                minMoves = cur;
            }
        }
        return minMoves;
    }
}

