        int n = stickers.length;
        int m = target.length();
        // Preprocess sticker character counts
        int[][] stickerCounts = new int[n][26];
        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) {
                stickerCounts[i][c - 'a']++;
            }
        }

        // Quick impossibility check: every character in target must appear in at least one sticker
        boolean[] present = new boolean[26];
        for (int[] cnt : stickerCounts) {
            for (int j = 0; j < 26; j++) {
                if (cnt[j] > 0) present[j] = true;
            }
        }
        for (char c : target.toCharArray()) {
            if (!present[c - 'a']) return -1;
        }

        char[] tChars = target.toCharArray();
        int fullMask = (1 << m) - 1;
        int INF = m + 1; // worst case each character needs a sticker
        int[] dp = new int[1 << m];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        // Iterate over all masks
        for (int mask = 0; mask <= fullMask; mask++) {
            if (dp[mask] == INF) continue; // unreachable state
            // Try each sticker
            for (int i = 0; i < n; i++) {
                int newMask = applySticker(stickerCounts[i], tChars, mask);
                if (newMask != mask) {
                    dp[newMask] = Math.min(dp[newMask], dp[mask] + 1);
                }
            }
        }

        return dp[fullMask] == INF ? -1 : dp[fullMask];
    }

    // Apply a sticker to the current mask and return the new mask after covering characters
    private int applySticker(int[] stickerCount, char[] target, int mask) {
        int[] remain = stickerCount.clone(); // remaining letters in the sticker
        int newMask = mask;
        for (int i = 0; i < target.length; i++) {
            if ((mask & (1 << i)) != 0) continue; // already covered
            int idx = target[i] - 'a';
            if (remain[idx] > 0) {
                remain[idx]--;
                newMask |= (1 << i); // cover this character
            }
        }
        return newMask;
    }
}

