import java.util.*;

public class Solution {
    public int cutOffTree(List<List<Integer>> forest) {
        if (forest == null || forest.isEmpty() || forest.get(0).isEmpty()) {
            return -1;
        }
        int m = forest.size();
        int n = forest.get(0).size();

        // Collect all trees with height > 1
        List<int[]> trees = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int val = forest.get(i).get(j);
                if (val > 1) {
                    trees.add(new int[]{val, i, j}); // {height, row, col}
                }
            }
        }

        // Sort trees by height (ascending)
        trees.sort(Comparator.comparingInt(a -> a[0]));

        int totalSteps = 0;
        int curR = 0, curC = 0;

        // If starting cell is blocked, cannot move
        if (forest.get(0).get(0) == 0) {
            return -1;
        }

        for (int[] tree : trees) {
            int targetR = tree[1];
            int targetC = tree[2];
            int steps = bfs(forest, curR, curC, targetR, targetC);
            if (steps == -1) {
                return -1;
            }
            totalSteps += steps;
            // Cut the tree: set cell to 1 (walkable)
            forest.get(targetR).set(targetC, 1);
            curR = targetR;
            curC = targetC;
        }

        return totalSteps;
    }

    // Breadth‑first search to find shortest distance between two points.
    private int bfs(List<List<Integer>> forest, int sr, int sc, int tr, int tc) {
        if (sr == tr && sc == tc) {
            return 0;
        }
        int m = forest.size();
        int n = forest.get(0).size();
        boolean[][] visited = new boolean[m][n];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{sr, sc, 0});
        visited[sr][sc] = true;

        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, 1, 0, -1};

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            int dist = cur[2];

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) {
                    continue;
                }
                if (visited[nr][nc] || forest.get(nr).get(nc) == 0) {
                    continue;
                }
                if (nr == tr && nc == tc) {
                    return dist + 1;
                }
                visited[nr][nc] = true;
                queue.offer(new int[]{nr, nc, dist + 1});
            }
        }
        return -1; // target not reachable
    }
}

