public class Solution {

    public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        int m = n - k + 1;                     // number of possible windows
        int[] windowSum = new int[m];

        // 1️⃣ Compute sums of all windows of size k
        int sum = 0;
        for (int i = 0; i < k; i++) {
            sum += nums[i];
        }
        windowSum[0] = sum;
        for (int i = k; i < n; i++) {
            sum += nums[i] - nums[i - k];
            windowSum[i - k + 1] = sum;
        }

        // 2️⃣ left[i] = index of max‑sum window in [0 … i]
        int[] left = new int[m];
        int bestIdx = 0;
        for (int i = 0; i < m; i++) {
            if (windowSum[i] > windowSum[bestIdx]) {
                bestIdx = i;
            }
            left[i] = bestIdx;
        }

        // 3️⃣ right[i] = index of max‑sum window in [i … m‑1]
        int[] right = new int[m];
        bestIdx = m - 1;
        for (int i = m - 1; i >= 0; i--) {
            // '>=' keeps the earlier index when sums tie (lexicographically smaller)
            if (windowSum[i] >= windowSum[bestIdx]) {
                bestIdx = i;
            }
            right[i] = bestIdx;
        }

        // 4️⃣ Scan possible middle windows
        int[] answer = new int[3];
        int maxTotal = -1;

        // middle window start must leave at least k elements on each side
        for (int i = k; i <= m - k - 1; i++) {
            int l = left[i - k];
            int r = right[i + k];
            int total = windowSum[l] + windowSum[i] + windowSum[r];

            if (total > maxTotal) {
                maxTotal = total;
                answer[0] = l;
                answer[1] = i;
                answer[2] = r;
            } else if (total == maxTotal) {
                // lexicographically smaller check
                if (l < answer[0] ||
                    (l == answer[0] && (i < answer[1] ||
                    (i == answer[1] && r < answer[2])))) {
                    answer[0] = l;
                    answer[1] = i;
                    answer[2] = r;
                }
            }
        }

        return answer;
    }
}

