public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numDecodings(String s) {
        int n = s.length();
        if (n == 0) return 0;

        long dpPrevPrev = 1; // dp[i-2]
        long dpPrev;         // dp[i-1]

        // initialize dpPrev for the first character
        char first = s.charAt(0);
        if (first == '*') {
            dpPrev = 9;
        } else if (first != '0') {
            dpPrev = 1;
        } else {
            dpPrev = 0;
        }

        for (int i = 2; i <= n; i++) {
            char curChar = s.charAt(i - 1);
            char prevChar = s.charAt(i - 2);
            long cur = 0;

            // single character decoding
            long singleWays = 0;
            if (curChar == '*') {
                singleWays = 9;
            } else if (curChar != '0') {
                singleWays = 1;
            }
            cur = (cur + singleWays * dpPrev) % MOD;

            // two‑character decoding
            long twoWays = 0;
            if (prevChar == '*' && curChar == '*') {
                // 11‑19 and 21‑26
                twoWays = 15;
            } else if (prevChar == '*') {
                if (curChar == '0') {
                    twoWays = 2; // 10 or 20
                } else if (curChar >= '1' && curChar <= '6') {
                    twoWays = 2; // 1x or 2x
                } else { // '7'‑'9'
                    twoWays = 1; // only 1x
                }
            } else if (curChar == '*') {
                if (prevChar == '1') {
                    twoWays = 9; // 11‑19
                } else if (prevChar == '2') {
                    twoWays = 6; // 21‑26
                }
            } else {
                int val = (prevChar - '0') * 10 + (curChar - '0');
                if (val >= 10 && val <= 26) {
                    twoWays = 1;
                }
            }
            cur = (cur + twoWays * dpPrevPrev) % MOD;

            // shift dp values
            dpPrevPrev = dpPrev;
            dpPrev = cur;
        }

        return (int) dpPrev;
    }
}

