public class Solution {
    public int findKthNumber(int m, int n, int k) {
        // Ensure m is the smaller dimension to potentially reduce loop iterations
        if (m > n) {
            int temp = m;
            m = n;
            n = temp;
        }

        long low = 1;
        long high = (long) m * n; // maximum possible value in the table

        while (low < high) {
            long mid = low + (high - low) / 2;
            long count = countLessOrEqual(mid, m, n);

            if (count >= k) {
                high = mid; // mid could be the answer, try smaller
            } else {
                low = mid + 1; // need larger values
            }
        }

        return (int) low;
    }

    /**
     * Counts how many numbers in the m x n multiplication table are less than or equal to x.
     */
    private long countLessOrEqual(long x, int m, int n) {
        long cnt = 0;
        for (int i = 1; i <= m; i++) {
            cnt += Math.min(n, (int) (x / i));
            // Early exit if count already exceeds possible k (optional optimization)
            // Not required for correctness.
        }
        return cnt;
    }
}

