import java.util.Arrays;

public class Solution {
    public int maximumProduct(int[] nums) {
        // Ensure the array has at least three elements (as per problem statement)
        if (nums == null || nums.length < 3) {
            throw new IllegalArgumentException("Input array must contain at least three numbers.");
        }

        // Sort the array to easily access the largest and smallest values
        Arrays.sort(nums);
        int n = nums.length;

        // The maximum product can be obtained either by:
        // 1) The product of the three largest numbers.
        // 2) The product of the two smallest (most negative) numbers and the largest number.
        long product1 = (long) nums[n - 1] * nums[n - 2] * nums[n - 3];
        long product2 = (long) nums[0] * nums[1] * nums[n - 1];

        long maxProduct = Math.max(product1, product2);
        return (int) maxProduct;
    }
}

