import java.util.ArrayList;
import java.util.List;

public class Solution {
    private static final double TARGET = 24.0;
    private static final double EPS = 1e-6;

    public boolean judgePoint24(int[] cards) {
        List<Double> nums = new ArrayList<>(4);
        for (int c : cards) {
            nums.add((double) c);
        }
        return dfs(nums);
    }

    private boolean dfs(List<Double> nums) {
        int n = nums.size();
        if (n == 1) {
            return Math.abs(nums.get(0) - TARGET) < EPS;
        }

        // try every ordered pair (i, j)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;

                List<Double> next = new ArrayList<>(n - 1);
                // add all numbers except i and j
                for (int k = 0; k < n; k++) {
                    if (k != i && k != j) {
                        next.add(nums.get(k));
                    }
                }

                double a = nums.get(i);
                double b = nums.get(j);

                // generate all possible results of applying an operator to a and b
                for (double val : compute(a, b)) {
                    next.add(val);
                    if (dfs(next)) {
                        return true;
                    }
                    next.remove(next.size() - 1); // backtrack
                }
            }
        }
        return false;
    }

    private double[] compute(double a, double b) {
        // +, -, *, / (both orders for - and /)
        // Use a list to avoid duplicate results for commutative ops
        List<Double> res = new ArrayList<>(6);
        res.add(a + b);
        res.add(a - b);
        res.add(b - a);
        res.add(a * b);
        if (Math.abs(b) > EPS) {
            res.add(a / b);
        }
        if (Math.abs(a) > EPS) {
            res.add(b / a);
        }
        // convert to primitive array
        double[] arr = new double[res.size()];
        for (int i = 0; i < res.size(); i++) {
            arr[i] = res.get(i);
        }
        return arr;
    }
}

