import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.TreeSet;

public class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        // 1. coordinate compression
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] p : positions) {
            int left = p[0];
            int right = p[0] + p[1];
            set.add(left);
            set.add(right);
        }
        List<Integer> coords = new ArrayList<>(set);
        Collections.sort(coords);
        HashMap<Integer, Integer> index = new HashMap<>();
        for (int i = 0; i < coords.size(); i++) {
            index.put(coords.get(i), i);
        }

        // number of elementary intervals = coords.size() - 1
        int n = Math.max(0, coords.size() - 1);
        SegmentTree seg = new SegmentTree(n);

        List<Integer> answer = new ArrayList<>();
        int globalMax = 0;

        for (int[] p : positions) {
            int left = p[0];
            int size = p[1];
            int right = left + size;

            int lIdx = index.get(left);
            int rIdx = index.get(right) - 1; // inclusive index for intervals

            int baseHeight = seg.query(lIdx, rIdx);
            int newHeight = baseHeight + size;

            seg.update(lIdx, rIdx, newHeight);
            globalMax = Math.max(globalMax, newHeight);
            answer.add(globalMax);
        }

        return answer;
    }

    // Segment tree supporting range max query and range assign (override) with lazy propagation
    private static class SegmentTree {
        private final int n;
        private final int[] tree;
        private final int[] lazy; // 0 means no pending assignment (heights are always positive)

        SegmentTree(int n) {
            this.n = n;
            this.tree = new int[4 * Math.max(1, n)];
            this.lazy = new int[4 * Math.max(1, n)];
        }

        private void push(int node) {
            if (lazy[node] != 0) {
                int leftChild = node << 1;
                int rightChild = leftChild | 1;
                tree[leftChild] = lazy[node];
                tree[rightChild] = lazy[node];
                lazy[leftChild] = lazy[node];
                lazy[rightChild] = lazy[node];
                lazy[node] = 0;
            }
        }

        private int query(int node, int l, int r, int ql, int qr) {
            if (ql > r || qr < l) {
                return 0;
            }
            if (ql <= l && r <= qr) {
                return tree[node];
            }
            push(node);
            int mid = (l + r) >>> 1;
            return Math.max(
                    query(node << 1, l, mid, ql, qr),
                    query((node << 1) | 1, mid + 1, r, ql, qr)
            );
        }

        private void update(int node, int l, int r, int ul, int ur, int val) {
            if (ul > r || ur < l) {
                return;
            }
            if (ul <= l && r <= ur) {
                tree[node] = val;
                lazy[node] = val;
                return;
            }
            push(node);
            int mid = (l + r) >>> 1;
            update(node << 1, l, mid, ul, ur, val);
            update((node << 1) | 1, mid + 1, r, ul, ur, val);
            tree[node] = Math.max(tree[node << 1], tree[(node << 1) | 1]);
        }

        // public wrappers
        int query(int l, int r) {
            if (n == 0 || l > r) {
                return 0;
            }
            return query(1, 0, n - 1, l, r);
        }

        void update(int l, int r, int val) {
            if (n == 0 || l > r) {
                return;
            }
            update(1, 0, n - 1, l, r, val);
        }
    }
}

