import java.util.List;

public class Solution {
    // Trie node definition
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word = null; // stores the root word when this node marks the end of a root
    }

    private final TrieNode root = new TrieNode();

    // Insert a root into the trie
    private void insert(String rootWord) {
        TrieNode node = root;
        for (char c : rootWord.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
        }
        // store the root word at the terminal node (shortest root will be kept automatically)
        if (node.word == null) {
            node.word = rootWord;
        }
    }

    // Find the shortest root that is a prefix of the given word; return null if none
    private String searchRoot(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                return null; // no matching prefix
            }
            node = node.children[idx];
            if (node.word != null) {
                return node.word; // earliest (shortest) root found
            }
        }
        return null;
    }

    public String replaceWords(List<String> dictionary, String sentence) {
        // Build the trie from the dictionary
        for (String rootWord : dictionary) {
            if (rootWord != null && !rootWord.isEmpty()) {
                insert(rootWord);
            }
        }

        StringBuilder result = new StringBuilder();
        int n = sentence.length();
        StringBuilder currentWord = new StringBuilder();

        for (int i = 0; i <= n; i++) {
            char ch = i < n ? sentence.charAt(i) : ' '; // sentinel space at the end
            if (ch == ' ') {
                if (currentWord.length() > 0) {
                    String word = currentWord.toString();
                    String replacement = searchRoot(word);
                    if (replacement != null) {
                        result.append(replacement);
                    } else {
                        result.append(word);
                    }
                    currentWord.setLength(0);
                }
                if (i < n) {
                    result.append(' ');
                }
            } else {
                currentWord.append(ch);
            }
        }

        return result.toString();
    }
}

