public class Solution {
    public int strangePrinter(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        int n = s.length();
        int[][] dp = new int[n][n];
        // Fill DP table
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1; // single character needs one turn
            for (int j = i + 1; j < n; j++) {
                // worst case: print s[j] separately
                dp[i][j] = dp[i][j - 1] + 1;
                // try to merge prints where s[k] == s[j]
                for (int k = i; k < j; k++) {
                    if (s.charAt(k) == s.charAt(j)) {
                        int merged = dp[i][k] + (k + 1 <= j - 1 ? dp[k + 1][j - 1] : 0);
                        if (merged < dp[i][j]) {
                            dp[i][j] = merged;
                        }
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

