/**
 * Solution for trimming a Binary Search Tree so that all its values lie within the
 * inclusive range [low, high]. The relative structure of the remaining nodes is
 * preserved.
 *
 * The {@code TreeNode} public class Solution defined as a static nested public class Solution ensure the
 * code compiles without requiring an external definition.
 */
public class Solution {

    /**
     * Definition for a binary tree node.
     */
    public static class TreeNode {
        public int val;
        public TreeNode left;
        public TreeNode right;

        public TreeNode() {}

        public TreeNode(int val) {
            this.val = val;
        }

        public TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }

    /**
     * Trims the given BST so that all its node values lie within the inclusive
     * range {@code [low, high]}. The relative structure of the remaining nodes
     * is preserved.
     *
     * @param root the root of the BST
     * @param low  lower bound of the allowed range (inclusive)
     * @param high upper bound of the allowed range (inclusive)
     * @return the root of the trimmed BST
     */
    public TreeNode trimBST(TreeNode root, int low, int high) {
        if (root == null) {
            return null;
        }

        // If current node's value is less than low, discard left subtree
        if (root.val < low) {
            return trimBST(root.right, low, high);
        }

        // If current node's value is greater than high, discard right subtree
        if (root.val > high) {
            return trimBST(root.left, low, high);
        }

        // Node is within range; recursively trim both subtrees
        root.left = trimBST(root.left, low, high);
        root.right = trimBST(root.right, low, high);
        return root;
    }
}

