public class Solution {
    private static final int MOD = 1_000_000_007;

    public int kInversePairs(int n, int k) {
        // dp[i][j] = number of arrays of length i with exactly j inverse pairs
        int[][] dp = new int[n + 1][k + 1];
        dp[0][0] = 1; // empty array has 0 inverse pairs

        for (int i = 1; i <= n; i++) {
            dp[i][0] = 1; // only one way to have 0 inverse pairs (sorted array)
            for (int j = 1; j <= k; j++) {
                // dp[i][j] = dp[i][j-1] + dp[i-1][j]
                int val = dp[i][j - 1] + dp[i - 1][j];
                if (val >= MOD) val -= MOD;

                // subtract dp[i-1][j-i] if j >= i
                if (j >= i) {
                    val -= dp[i - 1][j - i];
                    if (val < 0) val += MOD;
                }
                dp[i][j] = val;
            }
        }
        return dp[n][k];
    }
}

