public class Solution {
    public int findLongestChain(int[][] pairs) {
        if (pairs == null || pairs.length == 0) {
            return 0;
        }
        // Sort pairs by their right endpoint to apply the greedy approach
        Arrays.sort(pairs, (a, b) -> Integer.compare(a[1], b[1]));
        int count = 0;
        int currentEnd = Integer.MIN_VALUE;
        for (int[] pair : pairs) {
            // A pair can follow the previous one only if its left value is greater than the previous right value
            if (pair[0] > currentEnd) {
                count++;
                currentEnd = pair[1];
            }
        }
        return count;
    }
}

