public class Solution {
    public int flipLights(int n, int m) {
        // No presses, only the initial state
        if (m == 0) {
            return 1;
        }

        // Reduce the number of presses because after 3 presses the pattern repeats
        m = Math.min(m, 3);

        if (n == 1) {
            // With one bulb we can have either on or off after at least one press
            return 2;
        }

        if (n == 2) {
            // With two bulbs:
            //   1 press  → 3 possible states
            //   2 or more presses → all 4 possible states (after capping m to 3)
            if (m == 1) {
                return 3;
            } else {
                // m == 2 or m == 3
                return 4;
            }
        }

        // n >= 3
        if (m == 1) {
            return 4;
        } else if (m == 2) {
            return 7;
        } else { // m == 3
            return 8;
        }
    }
}

