import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    /**
     * Finds groups of duplicate files based on their contents.
     *
     * @param paths an array of directory information strings.
     * @return a list of groups, each containing the full paths of files that share the same content.
     */
    public List<List<String>> findDuplicate(String[] paths) {
        // Map from file content to list of full file paths having that content
        Map<String, List<String>> contentToPaths = new HashMap<>();

        for (String entry : paths) {
            if (entry == null || entry.isEmpty()) {
                continue;
            }
            // Split the entry by spaces. The first token is the directory path.
            String[] parts = entry.split(" ");
            String dir = parts[0];

            // Process each file token: "filename.txt(content)"
            for (int i = 1; i < parts.length; i++) {
                String fileToken = parts[i];
                int openIdx = fileToken.indexOf('(');
                int closeIdx = fileToken.lastIndexOf(')');
                if (openIdx == -1 || closeIdx == -1 || openIdx > closeIdx) {
                    // malformed token, skip
                    continue;
                }
                String fileName = fileToken.substring(0, openIdx);
                String content = fileToken.substring(openIdx + 1, closeIdx);
                String fullPath = dir + "/" + fileName;

                // Add the full path to the list for this content
                contentToPaths.computeIfAbsent(content, k -> new ArrayList<>()).add(fullPath);
            }
        }

        // Collect groups with more than one file (duplicates)
        List<List<String>> duplicates = new ArrayList<>();
        for (List<String> group : contentToPaths.values()) {
            if (group.size() > 1) {
                duplicates.add(group);
            }
        }

        return duplicates;
    }
}

