import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Finds all duplicate subtrees in a binary tree.
 * For each set of duplicate subtrees, only one root node is returned.
 */
public class Solution {

    /**
     * Definition for a binary tree node.
     */
    public static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        public TreeNode(int val) {
            this.val = val;
        }
    }

    // Maps a subtree serialization to the number of times it has been seen.
    private final Map<String, Integer> countMap = new HashMap<>();
    // Stores the roots of duplicate subtrees (only once per duplicate kind).
    private final List<TreeNode> duplicates = new ArrayList<>();

    /**
     * Returns a list of TreeNode objects, each being the root of a duplicate subtree.
     *
     * @param root the root of the binary tree
     * @return list of duplicate subtree roots
     */
    public List<TreeNode> findDuplicateSubtrees(TreeNode root) {
        serialize(root);
        return duplicates;
    }

    /**
     * Serializes the subtree rooted at the given node.
     * The serialization format is: nodeValue,leftSerialization,rightSerialization.
     * A special marker "#" is used for null children.
     *
     * While serializing, the method updates {@code countMap} and records a node
     * in {@code duplicates} when its serialization is seen for the second time.
     *
     * @param node the current tree node
     * @return the serialization string of the subtree
     */
    private String serialize(TreeNode node) {
        if (node == null) {
            return "#";
        }
        String left = serialize(node.left);
        String right = serialize(node.right);
        String key = node.val + "," + left + "," + right;

        int cnt = countMap.getOrDefault(key, 0);
        if (cnt == 1) { // second occurrence -> record duplicate
            duplicates.add(node);
        }
        countMap.put(key, cnt + 1);
        return key;
    }
}

