public class Solution {
    public String solveEquation(String equation) {
        String[] sides = equation.split("=");
        int[] left = parseSide(sides[0]);
        int[] right = parseSide(sides[1]);

        // left[0] = coeff of x on left, left[1] = constant on left
        // right[0] = coeff of x on right, right[1] = constant on right
        int a = left[0] - right[0];          // coefficient of x after moving terms
        int b = right[1] - left[1];          // constant after moving terms

        if (a == 0) {
            if (b == 0) {
                return "Infinite solutions";
            } else {
                return "No solution";
            }
        } else {
            int x = b / a; // guaranteed to be integer per problem statement
            return "x=" + x;
        }
    }

    // Returns an array where result[0] = total coefficient of x,
    // result[1] = total constant term.
    private int[] parseSide(String s) {
        int coeff = 0;
        int constant = 0;
        int i = 0;
        int n = s.length();
        int sign = 1; // current sign

        while (i < n) {
            char ch = s.charAt(i);
            if (ch == '+') {
                sign = 1;
                i++;
            } else if (ch == '-') {
                sign = -1;
                i++;
            } else {
                int num = 0;
                boolean hasNumber = false;
                // parse number if present
                while (i < n && Character.isDigit(s.charAt(i))) {
                    hasNumber = true;
                    num = num * 10 + (s.charAt(i) - '0');
                    i++;
                }
                // check if variable follows
                if (i < n && s.charAt(i) == 'x') {
                    // it's a term with x
                    int termCoeff = hasNumber ? num : 1;
                    coeff += sign * termCoeff;
                    i++; // skip 'x'
                } else {
                    // it's a constant term
                    constant += sign * num;
                }
                // after processing a term, reset sign to positive for next term
                sign = 1;
            }
        }
        return new int[]{coeff, constant};
    }
}

