public class Solution {
    public int minSteps(int n) {
        int steps = 0;
        int divisor = 2;
        while (n > 1) {
            while (n % divisor == 0) {
                steps += divisor;
                n /= divisor;
            }
            divisor++;
            // No need to go beyond sqrt of current n, but loop will exit when n becomes 1
        }
        return steps;
    }
}

