import java.util.*;

public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            parent[i] = i;
        }

        int[] indegreeParent = new int[n + 1]; // stores the first parent of each node
        int[] candidate1 = null; // first edge causing two parents
        int[] candidate2 = null; // second edge causing two parents (the later one)

        // Step 1: detect a node with two parents
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (indegreeParent[v] != 0) {
                // v already has a parent
                candidate1 = new int[]{indegreeParent[v], v};
                candidate2 = new int[]{u, v};
                // we keep candidate2 in the list but will skip it later
            } else {
                indegreeParent[v] = u;
            }
        }

        // Union-Find helper
        class DSU {
            int[] p;

            DSU(int size) {
                p = new int[size];
                for (int i = 0; i < size; i++) {
                    p[i] = i;
                }
            }

            int find(int x) {
                if (p[x] != x) {
                    p[x] = find(p[x]);
                }
                return p[x];
            }

            boolean union(int a, int b) {
                int pa = find(a);
                int pb = find(b);
                if (pa == pb) {
                    return false; // cycle
                }
                p[pa] = pb;
                return true;
            }
        }

        DSU dsu = new DSU(n + 1);

        // Step 2: perform unions, skipping candidate2 if it exists
        for (int[] edge : edges) {
            if (candidate2 != null && edge[0] == candidate2[0] && edge[1] == candidate2[1]) {
                continue; // skip the later edge of the two‑parent situation
            }
            if (!dsu.union(edge[0], edge[1])) {
                // Cycle detected
                if (candidate1 == null) {
                    // No two‑parent issue, the current edge creates the cycle
                    return edge;
                } else {
                    // Two‑parent issue exists, the earlier edge is part of the cycle
                    return candidate1;
                }
            }
        }

        // If we reach here, there was a two‑parent issue but no cycle when candidate2 is ignored
        // Removing candidate2 resolves the problem
        return candidate2;
    }
}

