public class Solution {
    public int[] findErrorNums(int[] nums) {
        int duplicate = -1;
        int n = nums.length;

        // First pass: identify the duplicate by marking visited indices
        for (int i = 0; i < n; i++) {
            int val = Math.abs(nums[i]);
            int idx = val - 1; // map value to index (0‑based)

            if (nums[idx] < 0) {
                // already visited -> duplicate found
                duplicate = val;
            } else {
                nums[idx] = -nums[idx];
            }
        }

        // Second pass: find the missing number (the index that remains positive)
        int missing = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] > 0) {
                missing = i + 1; // convert index back to value
                break;
            }
        }

        return new int[] { duplicate, missing };
    }
}

