public class Solution {
    public int repeatedStringMatch(String a, String b) {
        if (b.isEmpty()) {
            return 0;
        }
        if (a.isEmpty()) {
            return -1;
        }

        StringBuilder sb = new StringBuilder();
        int count = 0;

        // Append until the built string is at least as long as b
        while (sb.length() < b.length()) {
            sb.append(a);
            count++;
        }

        // Check if b is now a substring
        if (sb.indexOf(b) != -1) {
            return count;
        }

        // One more repetition might be needed to cover the case where b spans the boundary
        sb.append(a);
        count++;
        if (sb.indexOf(b) != -1) {
            return count;
        }

        // Not found after the necessary repetitions
        return -1;
    }
}

