import java.util.HashMap;
import java.util.List;
import java.util.Map;
import com_github_leetcode.Employee;

/**
 * Solution for calculating the total importance of an employee and all of their subordinates.
 */
public class Solution {

    /**
     * Returns the total importance value for the employee with the given id,
     * including the importance of all direct and indirect subordinates.
     *
     * @param employees list of all employees
     * @param id        the id of the employee whose total importance is required
     * @return total importance
     */
    public int getImportance(List<Employee> employees, int id) {
        Map<Integer, Employee> employeeMap = new HashMap<>();
        for (Employee e : employees) {
            employeeMap.put(e.id, e);
        }
        return dfs(employeeMap, id);
    }

    /**
     * Depth‑first search that accumulates importance values.
     *
     * @param map map from employee id to Employee object
     * @param id  current employee id
     * @return total importance for this employee subtree
     */
    private int dfs(Map<Integer, Employee> map, int id) {
        Employee e = map.get(id);
        if (e == null) {
            return 0; // safety check: if the id does not exist, contribute nothing
        }
        int total = e.importance;
        for (Integer subId : e.subordinates) {
            total += dfs(map, subId);
        }
        return total;
    }
}

