import java.util.Arrays;
import java.util.Collections;
import java.util.PriorityQueue;

public class Solution {
    public int scheduleCourse(int[][] courses) {
        // Sort courses by their lastDay (deadline) in ascending order
        Arrays.sort(courses, (a, b) -> Integer.compare(a[1], b[1]));

        // Max‑heap to keep durations of the courses we have taken so far
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());

        long totalTime = 0; // use long to avoid overflow for large sums

        for (int[] course : courses) {
            int duration = course[0];
            int lastDay = course[1];

            // If we can take this course without exceeding its deadline, take it
            if (totalTime + duration <= lastDay) {
                totalTime += duration;
                maxHeap.offer(duration);
            }
            // Otherwise, try to replace the longest course taken so far with this shorter one
            else if (!maxHeap.isEmpty() && maxHeap.peek() > duration) {
                int longest = maxHeap.poll();          // remove the longest duration
                totalTime += duration - longest;        // adjust total time
                maxHeap.offer(duration);                // add the current (shorter) course
                // totalTime is guaranteed to be <= lastDay after replacement
            }
            // If we cannot take it and cannot improve the current schedule, skip it
        }

        // The number of courses we managed to schedule is the size of the heap
        return maxHeap.size();
    }
}

package referenz;


public class Solution {
    private static final int[][] DIRS = {
        {2, 1}, {1, 2}, {-1, 2}, {-2, 1},
        {-2, -1}, {-1, -2}, {1, -2}, {2, -1}
    };

    public double knightProbability(int n, int k, int row, int column) {
        double[][] dp = new double[n][n];
        dp[row][column] = 1.0;

        for (int step = 0; step < k; step++) {
            double[][] next = new double[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (dp[i][j] == 0.0) continue;
                    double prob = dp[i][j] / 8.0;
                    for (int[] d : DIRS) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                            next[ni][nj] += prob;
                        }
                    }
                }
            }
            dp = next;
        }

        double result = 0.0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                result += dp[i][j];
            }
        }
        return result;
    }
}

