import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int calPoints(String[] ops) {
        List<Integer> scores = new ArrayList<>();
        for (String op : ops) {
            int size = scores.size();
            switch (op) {
                case "C":
                    // Invalidate the previous score
                    if (size > 0) {
                        scores.remove(size - 1);
                    }
                    break;
                case "D":
                    // Double the previous score
                    if (size > 0) {
                        scores.add(2 * scores.get(size - 1));
                    }
                    break;
                case "+":
                    // Sum of the previous two scores
                    if (size >= 2) {
                        int sum = scores.get(size - 1) + scores.get(size - 2);
                        scores.add(sum);
                    }
                    break;
                default:
                    // It's an integer value
                    scores.add(Integer.parseInt(op));
                    break;
            }
        }

        int total = 0;
        for (int score : scores) {
            total += score;
        }
        return total;
    }
}

