import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean isPossible(int[] nums) {
        // Frequency map of each number
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }

        // Map that records how many subsequences are waiting for a specific next number
        Map<Integer, Integer> need = new HashMap<>();

        for (int num : nums) {
            int count = freq.getOrDefault(num, 0);
            if (count == 0) {
                continue; // this number has already been used
            }

            // Use one occurrence of num
            freq.put(num, count - 1);

            // If there is a subsequence that needs this number, extend it
            if (need.getOrDefault(num, 0) > 0) {
                need.put(num, need.get(num) - 1);
                need.put(num + 1, need.getOrDefault(num + 1, 0) + 1);
            }
            // Otherwise try to create a new subsequence of length at least 3
            else if (freq.getOrDefault(num + 1, 0) > 0 && freq.getOrDefault(num + 2, 0) > 0) {
                // consume num+1 and num+2
                freq.put(num + 1, freq.get(num + 1) - 1);
                freq.put(num + 2, freq.get(num + 2) - 1);
                // now we need num+3 for this new subsequence
                need.put(num + 3, need.getOrDefault(num + 3, 0) + 1);
            } else {
                // cannot use this number
                return false;
            }
        }
        return true;
    }
}

