import java.util.HashMap;
import java.util.Map;

public class Solution {

    private static class Value {
        int count;
        int start;
        int end;

        public Value(int c, int s, int e) {
            this.count = c;
            this.start = s;
            this.end = e;
        }
    }

    /**
     * Returns the length of the smallest contiguous subarray that has the same degree as the whole array.
     *
     * @param nums non‑empty array of non‑negative integers
     * @return minimal length of a subarray with the same degree
     */
    public int findShortestSubArray(int[] nums) {
        Map<Integer, Value> map = new HashMap<>();
        int degree = 0;

        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            if (!map.containsKey(num)) {
                map.put(num, new Value(1, i, i));
            } else {
                Value v = map.get(num);
                v.count++;
                v.end = i; // update last occurrence
            }
            degree = Math.max(degree, map.get(num).count);
        }

        int minLen = Integer.MAX_VALUE;
        for (Value v : map.values()) {
            if (v.count == degree) {
                int len = v.end - v.start + 1;
                if (len < minLen) {
                    minLen = len;
                }
            }
        }
        return minLen;
    }
}

