/**
 * Solution for finding the second minimum value in a special binary tree.
 * The tree satisfies the property that each non‑leaf node's value equals
 * the minimum of its two children's values.
 */
public class Solution {

    /**
     * Returns the second minimum value among all nodes in the tree.
     * If such a value does not exist, returns -1.
     *
     * @param root the root of the binary tree
     * @return the second minimum value, or -1 if none exists
     */
    public int findSecondMinimumValue(TreeNode root) {
        if (root == null) {
            return -1;
        }
        int candidate = dfs(root, root.val);
        return candidate == Integer.MAX_VALUE ? -1 : candidate;
    }

    /**
     * Depth‑first search that looks for the smallest value greater than {@code min}.
     *
     * @param node current node
     * @param min  the minimum value (root value)
     * @return the smallest value greater than {@code min} found in the subtree,
     *         or {@code Integer.MAX_VALUE} if none exists
     */
    private int dfs(TreeNode node, int min) {
        if (node == null) {
            return Integer.MAX_VALUE;
        }
        if (node.val > min) {
            return node.val;
        }
        int left = dfs(node.left, min);
        int right = dfs(node.right, min);
        return Math.min(left, right);
    }

    /**
     * Simple binary‑tree node definition required for the algorithm.
     */
    public static class TreeNode {
        public int val;
        public TreeNode left;
        public TreeNode right;

        public TreeNode() {}

        public TreeNode(int val) {
            this.val = val;
        }

        public TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }
}

