public class Solution {
    public boolean checkValidString(String s) {
        int low = 0;   // minimum possible number of '('
        int high = 0;  // maximum possible number of '('
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                low++;
                high++;
            } else if (c == ')') {
                low--;
                high--;
            } else { // '*'
                low--;   // treat as ')'
                high++;  // treat as '('
            }
            if (high < 0) {
                // too many ')'
                return false;
            }
            if (low < 0) {
                // we can consider extra '(' as empty
                low = 0;
            }
        }
        // if we can balance all '(' to zero
        return low == 0;
    }
}

