import java.util.List;
import java.util.PriorityQueue;
import java.util.Comparator;

public class Solution {

    private static class Node {
        int value; // current number
        int row;   // which list
        int col;   // index inside the list

        Node(int value, int row, int col) {
            this.value = value;
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Finds the smallest inclusive range [a, b] such that each of the k input
     * sorted lists contributes at least one number inside the range.
     *
     * @param nums a list containing k non‑empty lists of integers sorted in non‑decreasing order
     * @return an int array of size 2 where result[0] = upper bound, result[1] = lower bound
     */
    public int[] smallestRange(List<List<Integer>> nums) {
        if (nums == null || nums.isEmpty()) {
            return new int[0];
        }

        int k = nums.size();
        PriorityQueue<Node> minHeap = new PriorityQueue<>(k, Comparator.comparingInt(n -> n.value));
        int currentMax = Integer.MIN_VALUE;

        // initialise heap with the first element of each list
        for (int i = 0; i < k; i++) {
            int val = nums.get(i).get(0);
            minHeap.offer(new Node(val, i, 0));
            if (val > currentMax) {
                currentMax = val;
            }
        }

        // best range found so far (lower bound = bestStart, upper bound = bestEnd)
        int bestStart = minHeap.peek().value;
        int bestEnd = currentMax;
        int bestLen = bestEnd - bestStart;

        while (true) {
            Node minNode = minHeap.poll();
            int currentMin = minNode.value;

            // update best range if current one is better
            int currentLen = currentMax - currentMin;
            if (currentLen < bestLen ||
                (currentLen == bestLen && currentMin < bestStart)) {
                bestStart = currentMin;
                bestEnd = currentMax;
                bestLen = currentLen;
            }

            // move to the next element in the list from which the min came
            if (minNode.col + 1 == nums.get(minNode.row).size()) {
                // one list is exhausted; cannot improve further
                break;
            }

            int nextCol = minNode.col + 1;
            int nextVal = nums.get(minNode.row).get(nextCol);
            minHeap.offer(new Node(nextVal, minNode.row, nextCol));
            if (nextVal > currentMax) {
                currentMax = nextVal;
            }
        }

        // Return with higher value first as required by the test suite
        return new int[]{bestEnd, bestStart};
    }
}

