public class Solution {
    public int maximumSwap(int num) {
        char[] digits = Integer.toString(num).toCharArray();
        int n = digits.length;
        // record the last position of each digit (0-9)
        int[] last = new int[10];
        for (int i = 0; i < n; i++) {
            last[digits[i] - '0'] = i;
        }
        // try to find a swap that makes the number larger
        for (int i = 0; i < n; i++) {
            int currentDigit = digits[i] - '0';
            // look for a larger digit to swap with, starting from 9 down to currentDigit+1
            for (int d = 9; d > currentDigit; d--) {
                if (last[d] > i) {
                    // swap positions i and last[d]
                    char temp = digits[i];
                    digits[i] = digits[last[d]];
                    digits[last[d]] = temp;
                    // after one swap, return the result
                    return Integer.parseInt(new String(digits));
                }
            }
        }
        // no beneficial swap found
        return num;
    }
}

