import java.util.Arrays;

public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        if (k == 1) {
            return true;
        }
        int n = nums.length;
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if (total % k != 0) {
            return false;
        }
        int target = total / k;
        // sort descending to help pruning
        Arrays.sort(nums);
        for (int i = 0; i < n / 2; i++) {
            int tmp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = tmp;
        }
        if (nums[0] > target) {
            return false;
        }

        int fullMask = (1 << n) - 1;
        int[] memo = new int[1 << n];
        Arrays.fill(memo, -1); // -1 = unknown, 0 = false, 1 = true

        return dfs(0, 0, target, nums, memo, fullMask);
    }

    private boolean dfs(int usedMask, int curSum, int target, int[] nums, int[] memo, int fullMask) {
        if (usedMask == fullMask) {
            // all numbers are used, last subset must also be valid
            return true;
        }
        if (memo[usedMask] != -1) {
            return memo[usedMask] == 1;
        }

        int remaining = target - curSum;
        for (int i = 0; i < nums.length; i++) {
            if ((usedMask & (1 << i)) != 0) {
                continue; // already used
            }
            if (nums[i] > remaining) {
                continue; // cannot fit in current subset
            }
            int nextMask = usedMask | (1 << i);
            int nextSum = curSum + nums[i];
            boolean ok;
            if (nextSum == target) {
                // start filling next subset
                ok = dfs(nextMask, 0, target, nums, memo, fullMask);
            } else {
                ok = dfs(nextMask, nextSum, target, nums, memo, fullMask);
            }
            if (ok) {
                memo[usedMask] = 1;
                return true;
            }
        }
        memo[usedMask] = 0;
        return false;
    }
}

