import java.util.*;
import java.util.stream.*;

public class Solution {
    private final Map<String, Integer> memo = new HashMap<>();

    /**
     * Original method signature required by the problem.
     */
    public int shoppingOffers(int[] price, List<List<Integer>> special, int[] needs) {
        return dfs(price, special, needs);
    }

    /**
     * Overloaded helper to accommodate test cases that pass List<Integer> for price and needs.
     * It converts the lists to primitive int arrays and delegates to the original method.
     */
    public int shoppingOffers(List<Integer> priceList, List<List<Integer>> special, List<Integer> needsList) {
        int[] price = priceList.stream().mapToInt(Integer::intValue).toArray();
        int[] needs = needsList.stream().mapToInt(Integer::intValue).toArray();
        return shoppingOffers(price, special, needs);
    }

    private int dfs(int[] price, List<List<Integer>> special, int[] needs) {
        String key = encode(needs);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        // Cost without using any special offer
        int minCost = 0;
        for (int i = 0; i < price.length; i++) {
            minCost += price[i] * needs[i];
        }

        // Try every special offer
        for (List<Integer> offer : special) {
            int[] nextNeeds = new int[needs.length];
            boolean valid = true;
            for (int i = 0; i < needs.length; i++) {
                int remain = needs[i] - offer.get(i);
                if (remain < 0) {
                    valid = false;
                    break;
                }
                nextNeeds[i] = remain;
            }
            if (!valid) {
                continue;
            }
            int offerPrice = offer.get(offer.size() - 1);
            int costWithOffer = offerPrice + dfs(price, special, nextNeeds);
            if (costWithOffer < minCost) {
                minCost = costWithOffer;
            }
        }

        memo.put(key, minCost);
        return minCost;
    }

    private String encode(int[] needs) {
        StringBuilder sb = new StringBuilder();
        for (int need : needs) {
            sb.append(need).append('#');
        }
        return sb.toString();
    }
}

