import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;

public class Solution {
    public int[] exclusiveTime(int n, List<String> logs) {
        int[] result = new int[n];
        Deque<Integer> stack = new ArrayDeque<>();
        int prevTime = 0;

        for (String log : logs) {
            String[] parts = log.split(":");
            int id = Integer.parseInt(parts[0]);
            String type = parts[1];
            int timestamp = Integer.parseInt(parts[2]);

            if ("start".equals(type)) {
                if (!stack.isEmpty()) {
                    // time spent by the function on top of the stack until now
                    result[stack.peek()] += timestamp - prevTime;
                }
                stack.push(id);
                prevTime = timestamp;
            } else { // "end"
                // the function on top ends now; include the current timestamp
                result[stack.pop()] += timestamp - prevTime + 1;
                prevTime = timestamp + 1; // next interval starts after this timestamp
            }
        }

        return result;
    }
}

