import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        int n = arr.length;
        // If k equals the whole array, just return all elements.
        if (k >= n) {
            List<Integer> all = new ArrayList<>(n);
            for (int value : arr) {
                all.add(value);
            }
            return all;
        }

        int left = 0;
        int right = n - k; // inclusive upper bound for the start index

        while (left < right) {
            int mid = left + (right - left) / 2;
            // Compare distances between x and the two border elements of the window
            int distLeft = Math.abs(x - arr[mid]);
            int distRight = Math.abs(arr[mid + k] - x);

            if (distLeft > distRight) {
                // The right side is closer, shift window to the right
                left = mid + 1;
            } else {
                // Left side is closer or equal (tie -> smaller element preferred)
                right = mid;
            }
        }

        List<Integer> result = new ArrayList<>(k);
        for (int i = left; i < left + k; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

