public class Solution {
    private int maxLength = 0;

    /**
     * Returns the length (in edges) of the longest univalue path in the binary tree.
     *
     * @param root the root of the binary tree
     * @return the maximum number of edges in a path where all nodes share the same value
     */
    public int longestUnivaluePath(TreeNode root) {
        dfs(root);
