    }

    /**
     * Depth‑first search that returns the length of the longest univalue path
     * extending from the current node downwards.
     *
     * @param node current tree node
     * @return longest same‑value path length starting at this node (in edges)
     */
    private int dfs(TreeNode node) {
        if (node == null) {
            return 0;
        }

        int left = dfs(node.left);
        int right = dfs(node.right);

        int leftPath = 0;
        int rightPath = 0;

        if (node.left != null && node.left.val == node.val) {
            leftPath = left + 1;
        }

        if (node.right != null && node.right.val == node.val) {
            rightPath = right + 1;
        }

        maxLength = Math.max(maxLength, leftPath + rightPath);

        return Math.max(leftPath, rightPath);
    }
