/**
 * Definition for a binary tree node.
 * This class is placed in the same package as {@link Solution} to avoid import issues.
 */
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    TreeNode(int val) {
        this.val = val;
    }
}

/**
 * Solution for adding a row of nodes with a given value at a specified depth in a binary tree.
 */
public class Solution {

    /**
     * Adds a row of nodes with the given value at the specified depth.
     *
     * @param root  the root of the binary tree
     * @param val   the value for the new nodes
     * @param depth the depth at which to insert the new row (1‑based)
     * @return the root of the modified tree
     */
    public TreeNode addOneRow(TreeNode root, int val, int depth) {
        if (depth == 1) {
            TreeNode newRoot = new TreeNode(val);
            newRoot.left = root; // original tree becomes left subtree
            return newRoot;
        }
        insert(root, val, depth, 1);
        return root;
    }

    /**
     * Recursively traverses the tree to the level just above the target depth
     * and inserts new nodes.
     *
     * @param node          current node in the traversal
     * @param val           value for the new nodes
     * @param targetDepth   depth where the new row should appear
     * @param currentDepth  depth of the current node (root is 1)
     */
    private void insert(TreeNode node, int val, int targetDepth, int currentDepth) {
        if (node == null) {
            return;
        }
        if (currentDepth == targetDepth - 1) {
            TreeNode originalLeft = node.left;
            TreeNode originalRight = node.right;

            TreeNode leftNode = new TreeNode(val);
            leftNode.left = originalLeft;   // attach original left subtree

            TreeNode rightNode = new TreeNode(val);
            rightNode.right = originalRight; // attach original right subtree

            node.left = leftNode;
            node.right = rightNode;
        } else {
            insert(node.left, val, targetDepth, currentDepth + 1);
            insert(node.right, val, targetDepth, currentDepth + 1);
        }
    }
}

