public class Solution {

    /**
     * Constructs a formatted string matrix representation of a binary tree.
     *
     * @param root the root of the binary tree
     * @return a 2‑D list of strings representing the tree layout
     */
    public List<List<String>> printTree(TreeNode root) {
        if (root == null) {
            return new ArrayList<>();
        }

        int height = getHeight(root);               // height of the tree (leaf = 0)
        int rows = height + 1;                      // number of rows = height + 1
        int cols = (1 << (height + 1)) - 1;          // 2^(height+1) - 1 columns

        // Initialise matrix with empty strings
        List<List<String>> res = new ArrayList<>(rows);
        for (int i = 0; i < rows; i++) {
            List<String> row = new ArrayList<>(cols);
            for (int j = 0; j < cols; j++) {
                row.add("");
            }
            res.add(row);
        }

        // Start placing nodes: root goes to the middle of the top row
        int startCol = (cols - 1) / 2;
        fill(root, 0, startCol, height, res);
        return res;
    }

    /**
     * Computes the height of the tree.
     * Returns -1 for a null node so that a leaf node has height 0.
     *
     * @param node the current node
     * @return height of the subtree rooted at {@code node}
     */
    private int getHeight(TreeNode node) {
        if (node == null) {
            return -1;
        }
        int left = getHeight(node.left);
        int right = getHeight(node.right);
        return Math.max(left, right) + 1;
    }

    /**
     * Recursively places node values into the matrix according to the required offsets.
     *
     * @param node        current tree node
     * @param row         current row in the matrix
     * @param col         current column in the matrix
     * @param totalHeight total height of the tree (used to compute offsets)
     * @param matrix      the matrix being filled
     */
    private void fill(TreeNode node, int row, int col, int totalHeight,
                      List<List<String>> matrix) {
        if (node == null) {
            return;
        }
        matrix.get(row).set(col, Integer.toString(node.val));

        // Offset for children: 2^(height - row - 1)
        int offset = 1 << (totalHeight - row - 1);
        if (node.left != null) {
            fill(node.left, row + 1, col - offset, totalHeight, matrix);
        }
        if (node.right != null) {
            fill(node.right, row + 1, col + offset, totalHeight, matrix);
        }
    }
}

