public class Solution {
    public boolean checkPossibility(int[] nums) {
        int violations = 0;
        for (int i = 0; i < nums.length - 1 && violations <= 1; i++) {
            if (nums[i] > nums[i + 1]) {
                violations++;
                // If we cannot adjust nums[i] to nums[i+1], adjust nums[i+1] to nums[i]
                if (i > 0 && nums[i - 1] > nums[i + 1]) {
                    // modify nums[i+1] to nums[i]; no need to actually change array
                    // because further checks use original nums[i+1] which is now larger,
                    // but we can set nums[i+1] = nums[i] to keep consistency
                    nums[i + 1] = nums[i];
                } else {
                    // modify nums[i] to nums[i+1]
                    nums[i] = nums[i + 1];
                }
            }
        }
        return violations <= 1;
    }
}

