import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        // Count frequencies
        Map<String, Integer> freqMap = new HashMap<>();
        for (String w : words) {
            freqMap.put(w, freqMap.getOrDefault(w, 0) + 1);
        }

        // Create a list of unique words
        List<String> uniqueWords = new ArrayList<>(freqMap.keySet());

        // Sort by descending frequency, then lexicographically ascending
        Collections.sort(uniqueWords, (a, b) -> {
            int freqA = freqMap.get(a);
            int freqB = freqMap.get(b);
            if (freqA != freqB) {
                return Integer.compare(freqB, freqA); // higher frequency first
            }
            return a.compareTo(b); // lexicographically smaller first
        });

        // Return the first k elements
        if (k > uniqueWords.size()) {
            k = uniqueWords.size();
        }
        return new ArrayList<>(uniqueWords.subList(0, k));
    }
}

