/** Solution class that computes the maximum width of a binary tree. */
public class Solution {

    /** Helper class to store a node together with its position index. */
    private static class Pair {
        TreeNode node;
        long index;

        Pair(TreeNode node, long index) {
            this.node = node;
            this.index = index;
        }
    }

    /**
     * Returns the maximum width of the binary tree rooted at {@code root}.
     *
     * @param root the root of the binary tree
     * @return the maximum width among all levels
     */
    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) {
            return 0;
        }

        long maxWidth = 0;
        Queue<Pair> queue = new ArrayDeque<>();
        queue.offer(new Pair(root, 0L));

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            long levelStart = -1;
            long levelEnd = -1;

            for (int i = 0; i < levelSize; i++) {
                Pair cur = queue.poll();
                if (i == 0) {
                    levelStart = cur.index;
                }
                if (i == levelSize - 1) {
                    levelEnd = cur.index;
                }

                if (cur.node.left != null) {
                    queue.offer(new Pair(cur.node.left, cur.index * 2));
                }
                if (cur.node.right != null) {
                    queue.offer(new Pair(cur.node.right, cur.index * 2 + 1));
                }
            }

            long width = levelEnd - levelStart + 1;
            if (width > maxWidth) {
                maxWidth = width;
            }
        }

        return (int) maxWidth;
    }
}

