import java.util.Stack;

/* Solution class that flattens a binary tree to a linked list in-place. */
public class Solution {

    /* Definition for a binary tree node. */
    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode() {}

        TreeNode(int val) {
            this.val = val;
        }

        TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }

    /**
     * Flattens the binary tree rooted at {@code root} into a "linked list"
     * following the preorder traversal order. After flattening, each node's
     * left child is set to {@code null} and the right child points to the next
     * node in the preorder sequence.
     *
     * @param root the root of the binary tree
     */
    public void flatten(TreeNode root) {
        if (root == null) {
            return;
        }

        Stack<TreeNode> stack = new Stack<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();

            // Push right child first so that left child is processed next
            if (node.right != null) {
                stack.push(node.right);
            }
            if (node.left != null) {
                stack.push(node.left);
            }

            // Rewire the current node
            node.left = null;
            node.right = stack.isEmpty() ? null : stack.peek();
        }
    }
}

