public class Solution {
    /**
     * Returns the number of '1' bits (Hamming weight) in the binary representation of the given integer.
     *
     * @param n the integer whose bits are to be counted (treated as unsigned)
     * @return the count of bits set to 1
     */
    public int hammingWeight(int n) {
        int count = 0;
        // Use Brian Kernighan's algorithm: repeatedly clear the least‑significant 1‑bit.
        while (n != 0) {
            count++;
            n &= (n - 1);
        }
        return count;
