import java.util.*;

public class Solution {
    /**
     * Constructs a permutation of the numbers 1..n such that the absolute differences
     * between consecutive elements contain exactly k distinct values.
     *
     * @param n the size of the permutation (1 ≤ n ≤ 10⁴)
     * @param k the required number of distinct absolute differences (0 ≤ k < n)
     * @return an int array representing a valid permutation
     */
    public int[] constructArray(int n, int k) {
        int[] answer = new int[n];

        // Special case: when k is 0 or 1 the descending order satisfies the requirement
        if (k == 0 || k == 1) {
            for (int i = 0; i < n; i++) {
                answer[i] = n - i; // descending: n, n‑1, … , 1
            }
            return answer;
        }

        int left = 1;
        int right = k + 1; // limit the alternating range to 1..k+1
        int idx = 0;

        // First k+1 elements: alternating low/high to create differences k, k-1, ..., 1
        for (int i = 0; i <= k; i++) {
            if ((i & 1) == 0) {
                answer[idx++] = left++;
            } else {
                answer[idx++] = right--;
            }
        }

        // Remaining elements: fill with the rest of the numbers in increasing order
        for (int num = k + 2; num <= n; num++) {
            answer[idx++] = num;
        }

        return answer;
    }
}

