public class Solution {
    /**
     * Determines if the binary tree has a root‑to‑leaf path whose sum equals the given target.
     *
     * @param root the root of the binary tree
     * @param sum  the target sum
     * @return {@code true} if such a path exists, otherwise {@code false}
     */
    public boolean hasPathSum(TreeNode root, int sum) {
        if (root == null) {
            return false;
        }
        // If this is a leaf node, check whether the remaining sum matches the node's value.
        if (root.left == null && root.right == null) {
            return sum == root.val;
        }
        int remaining = sum - root.val;
        return hasPathSum(root.left, remaining) || hasPathSum(root.right, remaining);
    }
}

