public class Solution {
    public String largestNumber(int[] nums) {
        if (nums == null || nums.length == 0) {
            return "";
        }

        // Convert integers to strings for easy concatenation comparison
        String[] strNums = new String[nums.length];
        for (int i = 0; i < nums.length; i++) {
            strNums[i] = String.valueOf(nums[i]);
        }

        // Sort using custom comparator: order by which concatenation yields a larger number
        Arrays.sort(strNums, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                String order1 = a + b;
                String order2 = b + a;
                // Descending order: larger concatenation comes first
                return order2.compareTo(order1);
            }
        });

        // Edge case: when the highest number is "0", the whole number is zero
        if (strNums[0].equals("0")) {
            return "0";
        }

        // Build the final result
        StringBuilder sb = new StringBuilder();
        for (String s : strNums) {
            sb.append(s);
        }
        return sb.toString();
    }
}

