public class Solution {
    public int maxProfit(int k, int[] prices) {
        int n = prices.length;
        if (n == 0 || k == 0) {
            return 0;
        }
        // If k is large enough, it becomes the unlimited transactions case
        if (k >= n / 2) {
            int profit = 0;
            for (int i = 1; i < n; i++) {
                if (prices[i] > prices[i - 1]) {
                    profit += prices[i] - prices[i - 1];
                }
            }
            return profit;
        }

        // DP arrays: buy[j] = max profit after j-th buy, sell[j] = max profit after j-th sell
        int[] buy = new int[k + 1];
        int[] sell = new int[k + 1];

        // Initialize buy array with very small numbers
        for (int j = 0; j <= k; j++) {
            buy[j] = Integer.MIN_VALUE / 2; // avoid overflow when adding price
            sell[j] = 0;
        }

        for (int price : prices) {
            for (int j = 1; j <= k; j++) {
                // either keep previous buy, or buy today after (j-1) sells
                buy[j] = Math.max(buy[j], sell[j - 1] - price);
                // either keep previous sell, or sell today after j-th buy
                sell[j] = Math.max(sell[j], buy[j] + price);
            }
        }

        return sell[k];
    }
}

