public class Solution {
    /**
     * Rotates the given array to the right by {@code k} steps.
     * The rotation is performed in‑place with O(1) extra space.
     *
     * @param nums the array to rotate
     * @param k    number of steps to rotate to the right (non‑negative)
     */
    public void rotate(int[] nums, int k) {
        if (nums == null || nums.length == 0) {
            return;
        }
        int n = nums.length;
        // Normalize k to avoid unnecessary rotations
        k = k % n;
        if (k == 0) {
            return;
        }

        // Reverse the whole array
        reverse(nums, 0, n - 1);
        // Reverse first k elements
        reverse(nums, 0, k - 1);
        // Reverse the remaining n‑k elements
        reverse(nums, k, n - 1);
    }

    // Helper method to reverse a sub‑array in‑place
    private void reverse(int[] arr, int left, int right) {
        while (left < right) {
            int tmp = arr[left];
            arr[left] = arr[right];
            arr[right] = tmp;
            left++;
            right--;
        }
    }
}

