/**
 * Solution for the "Minimum Depth of Binary Tree" problem.
 */
public class Solution {

    /**
     * Definition for a binary tree node.
     */
    public static class TreeNode {
        public int val;
        public TreeNode left;
        public TreeNode right;

        public TreeNode() {}

        public TreeNode(int val) {
            this.val = val;
        }

        public TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }

    /**
     * Builds a binary tree from a level‑order array representation.
     * {@code null} values represent missing nodes.
     *
     * @param values array of Integer values in level order
     * @return the root of the constructed binary tree, or {@code null} if the array is empty
     */
    public static TreeNode buildTree(Integer[] values) {
        if (values == null || values.length == 0) {
            return null;
        }
        TreeNode[] nodes = new TreeNode[values.length];
        for (int i = 0; i < values.length; i++) {
            if (values[i] != null) {
                nodes[i] = new TreeNode(values[i]);
            }
        }
        for (int i = 0; i < values.length; i++) {
            if (nodes[i] != null) {
                int leftIdx = 2 * i + 1;
                int rightIdx = 2 * i + 2;
                if (leftIdx < values.length) {
                    nodes[i].left = nodes[leftIdx];
                }
                if (rightIdx < values.length) {
                    nodes[i].right = nodes[rightIdx];
                }
            }
        }
        return nodes[0];
    }

    /**
     * Returns the minimum depth of a binary tree.
     *
     * @param root the root of the binary tree
     * @return the number of nodes along the shortest path from the root down to the nearest leaf
     */
    public int minDepth(TreeNode root) {
        if (root == null) {
            return 0;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int depth = 1;

        while (!queue.isEmpty()) {
            int levelSize = queue.size();

            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();

                // If this node is a leaf, we have found the minimum depth.
                if (node.left == null && node.right == null) {
                    return depth;
                }

                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }

            depth++;
        }

        // This line is never reached, but the compiler requires a return statement.
        return depth;
    }
}

