public class Solution {
    /**
     * Finds a peak element in the given array.
     * A peak element is strictly greater than its neighbors.
     * The algorithm runs in O(log n) time using binary search.
     *
     * @param nums the input array (non‑empty)
     * @return the index of any peak element
     */
    public int findPeakElement(int[] nums) {
        // Edge case: single element array
        if (nums == null || nums.length == 0) {
            throw new IllegalArgumentException("Array must contain at least one element.");
        }
        int left = 0;
        int right = nums.length - 1;

        // Binary search: keep the invariant that a peak exists in [left, right]
        while (left < right) {
            int mid = left + (right - left) / 2; // avoid overflow
            // Compare mid with its right neighbor
            if (nums[mid] > nums[mid + 1]) {
                // Peak is in the left half (including mid)
                right = mid;
            } else {
                // Peak is in the right half (excluding mid)
                left = mid + 1;
            }
        }
        // When left == right, we have found a peak
        return left;
    }
}

