public class Solution {

    /**
     * Returns {@code true} if the binary tree rooted at {@code root} is
     * height‑balanced; otherwise returns {@code false}.
     *
     * @param root the root of the binary tree
     * @return {@code true} if the tree is balanced, {@code false} otherwise
     */
    public boolean isBalanced(TreeNode root) {
        // The helper returns -1 if an imbalance is found; otherwise it returns
        // the height of the subtree. A non‑negative result means the whole tree
        // is balanced.
        return checkHeight(root) != -1;
    }

    /**
     * Computes the height of the subtree rooted at {@code node}.
     *
     * <p>If the subtree is unbalanced, the method returns {@code -1} immediately
     * to propagate the failure up the recursion stack.</p>
     *
     * @param node the current node (may be {@code null})
     * @return the height of the subtree, or {@code -1} if it is unbalanced
     */
    private int checkHeight(TreeNode node) {
        if (node == null) {
            return 0; // An empty subtree has height 0 and is balanced.
        }

        int leftHeight = checkHeight(node.left);
        if (leftHeight == -1) {
            return -1; // Left subtree is already unbalanced.
        }

        int rightHeight = checkHeight(node.right);
        if (rightHeight == -1) {
            return -1; // Right subtree is already unbalanced.
        }

        if (Math.abs(leftHeight - rightHeight) > 1) {
            return -1; // Current node violates the balance condition.
        }

        // Height of the current node is max of its sub‑heights plus one for itself.
        return Math.max(leftHeight, rightHeight) + 1;
    }
}

