public class Solution {
    public int singleNumber(int[] nums) {
        int ones = 0;   // bits that have appeared once
        int twos = 0;   // bits that have appeared twice

        for (int num : nums) {
            // Update twos with bits that have appeared twice
            twos = twos | (ones & num);

            // Update ones with bits that have appeared once
            ones = ones ^ num;

            // common bits that have appeared three times
            int commonMask = ~(ones & twos);

            // Remove bits that have appeared three times from ones and twos
            ones &= commonMask;
            twos &= commonMask;
        }

        // 'ones' holds the bits of the unique number
        return ones;
    }
}

