public class Solution {
    public List<Integer> getRow(int rowIndex) {
        // Initialize the row with 1's
        List<Integer> row = new ArrayList<>(rowIndex + 1);
        for (int i = 0; i <= rowIndex; i++) {
            row.add(1);
        }

        // Build the row using the previous values (in‑place DP)
        // Start from the second row (index 2) because the first two rows are already correct.
        for (int i = 2; i <= rowIndex; i++) {
            // Update the current row from right to left to avoid overwriting values needed for computation.
            for (int j = i - 1; j > 0; j--) {
                int updatedValue = row.get(j) + row.get(j - 1);
                row.set(j, updatedValue);
            }
        }

        return row;
    }
}

