/**
 * Computes the maximum path sum in a binary tree.
 *
 * A path is any sequence of nodes where each adjacent pair is connected by an edge.
 * Nodes may appear at most once in the sequence, and the path does not need to pass
 * through the root. The path sum is the sum of the node values along the path.
 *
 * This implementation uses a depth‑first search that returns the maximum gain
 * that can be contributed to the parent node while updating a global maximum
 * with the best path that passes through the current node.
 */
public class Solution {
    private int maxSum;

    /**
     * Returns the maximum sum of values along any non‑empty path in the binary tree.
     *
     * @param root the root of the binary tree
     * @return the maximum path sum
     */
    public int maxPathSum(TreeNode root) {
        maxSum = Integer.MIN_VALUE;
        dfs(root);
        return maxSum;
    }

    /**
     * Depth‑first search that returns the maximum gain that can be contributed
     * to the parent node. While traversing, it updates the global {@code maxSum}
     * with the best path that passes through the current node.
     *
     * @param node the current tree node
     * @return maximum gain from this node to its parent
     */
    private int dfs(TreeNode node) {
        if (node == null) {
            return 0;
        }

        // Gains from left and right sub‑trees; ignore negative contributions
        int leftGain = Math.max(dfs(node.left), 0);
        int rightGain = Math.max(dfs(node.right), 0);

        // Path sum that uses the current node as the highest point
        int currentPathSum = node.val + leftGain + rightGain;

        // Update the overall maximum path sum
        maxSum = Math.max(maxSum, currentPathSum);

        // Return the best gain to propagate upward
        return node.val + Math.max(leftGain, rightGain);
    }
}

