import java.util.*;

public class Solution {

    /**
     * Definition for an undirected graph node.
     */
    public static class Node {
        public int val;
        public List<Node> neighbors;

        public Node() {
            this.val = 0;
            this.neighbors = new ArrayList<>();
        }

        public Node(int val) {
            this.val = val;
            this.neighbors = new ArrayList<>();
        }

        public Node(int val, List<Node> neighbors) {
            this.val = val;
            this.neighbors = neighbors;
        }
    }

    /**
     * Clones an undirected connected graph.
     *
     * @param node the reference node of the original graph
     * @return the reference node of the cloned graph
     */
    public Node cloneGraph(Node node) {
        if (node == null) {
            return null;
        }

        // Map original node -> cloned node
        Map<Node, Node> clonedMap = new HashMap<>();
        Queue<Node> queue = new LinkedList<>();

        // Clone the starting node and enqueue it
        clonedMap.put(node, new Node(node.val));
        queue.add(node);

        while (!queue.isEmpty()) {
            Node current = queue.poll();
            Node currentClone = clonedMap.get(current);

            for (Node neighbor : current.neighbors) {
                // If neighbor hasn't been cloned yet, clone and enqueue it
                if (!clonedMap.containsKey(neighbor)) {
                    clonedMap.put(neighbor, new Node(neighbor.val));
                    queue.add(neighbor);
                }
                // Add the cloned neighbor to the current clone's neighbor list
                currentClone.neighbors.add(clonedMap.get(neighbor));
            }
        }

        return clonedMap.get(node);
    }
}

