import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordDict) {
        // Edge case: if beginWord equals endWord
        if (beginWord.equals(endWord)) {
            return 1;
        }

        // Put all words into a set for O(1) look‑ups
        Set<String> wordSet = new HashSet<>(wordDict);
        if (!wordSet.contains(endWord)) {
            return 0; // endWord must be reachable
        }

        // Bidirectional BFS initialization
        Set<String> beginSet = new HashSet<>();
        Set<String> endSet = new HashSet<>();
        Set<String> visited = new HashSet<>();

        beginSet.add(beginWord);
        endSet.add(endWord);
        visited.add(beginWord);
        visited.add(endWord);

        int step = 1; // start from beginWord

        while (!beginSet.isEmpty() && !endSet.isEmpty()) {
            // Always expand the smaller frontier for efficiency
            if (beginSet.size() > endSet.size()) {
                Set<String> tmp = beginSet;
                beginSet = endSet;
                endSet = tmp;
            }

            Set<String> nextLevel = new HashSet<>();

            for (String word : beginSet) {
                char[] chars = word.toCharArray();
                for (int i = 0; i < chars.length; i++) {
                    char originalChar = chars[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == originalChar) continue;
                        chars[i] = c;
                        String newWord = new String(chars);

                        // If the opposite frontier contains the new word, we have met
                        if (endSet.contains(newWord)) {
                            return step + 1;
                        }

                        // Otherwise, add to next level if it's a valid, unvisited word
                        if (wordSet.contains(newWord) && !visited.contains(newWord)) {
                            nextLevel.add(newWord);
                            visited.add(newWord);
                        }
                    }
                    chars[i] = originalChar; // restore for next position
                }
            }

            beginSet = nextLevel;
            step++;
        }

        // No transformation sequence found
        return 0;
    }
}

