import java.util.*;

public class Solution {

    /**
     * Definition for a binary tree node.
     */
    public static class TreeNode {
        public int val;
        public TreeNode left;
        public TreeNode right;

        public TreeNode(int val) {
            this.val = val;
        }
    }

    /**
     * Returns the zigzag level order traversal of a binary tree.
     *
     * @param root the root of the binary tree
     * @return a list of levels, each level being a list of node values in zigzag order
     */
    public List<List<Integer>> zigzagLevelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        boolean leftToRight = true;

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            List<Integer> level = new ArrayList<>(levelSize);

            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();
                level.add(node.val);

                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }

            if (!leftToRight) {
                Collections.reverse(level);
            }
            result.add(level);
            leftToRight = !leftToRight;
        }

        return result;
    }

    /**
     * Utility class to build a binary tree from a level‑order array representation.
     */
    public static class TreeUtils {
        /**
         * Builds a binary tree from an array where {@code null} represents missing nodes.
         *
         * @param values level‑order representation of the tree
         * @return the root of the constructed binary tree, or {@code null} if the array is empty
         */
        public static TreeNode buildTree(Integer[] values) {
            if (values == null || values.length == 0) {
                return null;
            }
            TreeNode root = new TreeNode(values[0]);
            Queue<TreeNode> queue = new LinkedList<>();
            queue.offer(root);
            int index = 1;
            while (index < values.length) {
                TreeNode current = queue.poll();
                if (current == null) {
                    continue;
                }
                // left child
                if (index < values.length && values[index] != null) {
                    current.left = new TreeNode(values[index]);
                    queue.offer(current.left);
                }
                index++;
                // right child
                if (index < values.length && values[index] != null) {
                    current.right = new TreeNode(values[index]);
                    queue.offer(current.right);
                }
                index++;
            }
            return root;
        }
    }

    /**
     * Utility class to convert nested lists to a 2‑D int array for easy assertions.
     */
    public static class ArrayUtils {
        /**
         * Converts a {@code List<List<Integer>>} to a primitive {@code int[][]}.
         *
         * @param list the nested list to convert
         * @return a 2‑D int array containing the same values
         */
        public static int[][] to2DArray(List<List<Integer>> list) {
            if (list == null) {
                return new int[0][];
            }
            int[][] result = new int[list.size()][];
            for (int i = 0; i < list.size(); i++) {
                List<Integer> inner = list.get(i);
                int[] row = new int[inner.size()];
                for (int j = 0; j < inner.size(); j++) {
                    row[j] = inner.get(j);
                }
                result[i] = row;
            }
            return result;
        }
    }
}

