/**
 * Solution for finding all root‑to‑leaf paths where the sum of node values equals a target value.
 */
public class Solution {

    /**
     * Definition for a binary tree node.
     */
    public static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        public TreeNode() {}

        public TreeNode(int val) {
            this.val = val;
        }

        public TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }

    /**
     * Returns a list of all root‑to‑leaf paths where the sum of node values equals {@code targetSum}.
     *
     * @param root the root of the binary tree
     * @param targetSum the required sum of values along a path
     * @return a list of paths, each path itself being a list of integer values
     */
    public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
        List<List<Integer>> result = new ArrayList<>();
        dfs(root, targetSum, new ArrayList<>(), result);
        return result;
    }

    private void dfs(TreeNode node, int remainingSum, List<Integer> path,
                     List<List<Integer>> result) {
        if (node == null) {
            return;
        }

        path.add(node.val);

        // If it's a leaf and the remaining sum matches the node's value, record the path.
        if (node.left == null && node.right == null && node.val == remainingSum) {
            result.add(new ArrayList<>(path));
        } else {
            dfs(node.left, remainingSum - node.val, path, result);
            dfs(node.right, remainingSum - node.val, path, result);
        }

        // Backtrack to explore other paths.
        path.remove(path.size() - 1);
    }
}

