import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxPoints(int[][] points) {
        if (points == null) {
            return 0;
        }
        int n = points.length;
        if (n <= 2) {
            return n;
        }

        int globalMax = 0;

        for (int i = 0; i < n; i++) {
            Map<String, Integer> slopeCount = new HashMap<>();
            int duplicates = 0;
            int localMax = 0;

            int xi = points[i][0];
            int yi = points[i][1];

            for (int j = i + 1; j < n; j++) {
                int xj = points[j][0];
                int yj = points[j][1];

                int dx = xj - xi;
                int dy = yj - yi;

                if (dx == 0 && dy == 0) {
                    // Same point as i
                    duplicates++;
                    continue;
                }

                // Reduce the fraction dy/dx to its simplest form
                int gcd = gcd(dy, dx);
                dy /= gcd;
                dx /= gcd;

                // Ensure a unique representation for the direction
                // Keep dx positive; if dx is zero, keep dy positive
                if (dx < 0) {
                    dx = -dx;
                    dy = -dy;
                } else if (dx == 0 && dy < 0) {
                    dy = -dy;
                }

                String key = dy + "/" + dx;
                int count = slopeCount.getOrDefault(key, 0) + 1;
                slopeCount.put(key, count);
                localMax = Math.max(localMax, count);
            }

            // Points on the best line through i = localMax + duplicates + the point i itself
            globalMax = Math.max(globalMax, localMax + duplicates + 1);
        }

        return globalMax;
    }

    // Euclidean algorithm for greatest common divisor
    private int gcd(int a, int b) {
        a = Math.abs(a);
        b = Math.abs(b);
        if (a == 0) return b;
        if (b == 0) return a;
        while (b != 0) {
            int tmp = a % b;
            a = b;
            b = tmp;
        }
        return a;
    }
}

