/**
 * Solution for the "Binary Tree Right Side View" problem.
 * Performs a level‑order (BFS) traversal and records the last node
 * encountered at each depth, which corresponds to the node visible
 * from the right side.
 */
public class Solution {

    /**
     * Returns the values of the nodes visible from the right side of the tree.
     *
     * @param root the root of the binary tree
     * @return a list of node values ordered from top to bottom
     */
    public List<Integer> rightSideView(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();

            for (int i = 0; i < levelSize; i++) {
                TreeNode node = queue.poll();

                // The last node of the current level is visible from the right side
                if (i == levelSize - 1) {
                    result.add(node.val);
                }

                if (node.left != null) {
                    queue.offer(node.left);
                }
                if (node.right != null) {
                    queue.offer(node.right);
                }
            }
        }

        return result;
    }
}

