public class Solution {
    public void solve(char[][] board) {
        // Edge case: empty board
        if (board == null || board.length == 0 || board[0].length == 0) {
            return;
        }

        int m = board.length;
        int n = board[0].length;

        // Mark border-connected 'O's with a temporary marker '#'
        for (int i = 0; i < m; i++) {
            // First column
            if (board[i][0] == 'O') {
                dfs(board, i, 0, m, n);
            }
            // Last column
            if (board[i][n - 1] == 'O') {
                dfs(board, i, n - 1, m, n);
            }
        }

        for (int j = 0; j < n; j++) {
            // First row
            if (board[0][j] == 'O') {
                dfs(board, 0, j, m, n);
            }
            // Last row
            if (board[m - 1][j] == 'O') {
                dfs(board, m - 1, j, m, n);
            }
        }

        // Convert the remaining cells
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'O') {
                    board[i][j] = 'X'; // captured region
                } else if (board[i][j] == '#') {
                    board[i][j] = 'O'; // restore border region
                }
            }
        }
    }

    // Depth‑first search to mark connected 'O's
    private void dfs(char[][] board, int i, int j, int m, int n) {
        if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] != 'O') {
            return;
        }
        board[i][j] = '#';
        dfs(board, i - 1, j, m, n);
        dfs(board, i + 1, j, m, n);
