import java.util.List;

/**
 * Solution class containing utility methods and the required algorithm
 * for the "Triangle – Minimum Path Sum" problem.
 */
public class Solution {

    /**
     * Converts an {@link Integer} array to a primitive {@code int} array.
     *
     * @param array the {@link Integer} array, may be {@code null}
     * @return a new {@code int[]} containing the same values, or {@code null} if the input is {@code null}
     */
    public static int[] toPrimitive(Integer[] array) {
        if (array == null) {
            return null;
        }
        int[] result = new int[array.length];
        for (int i = 0; i < array.length; i++) {
            result[i] = array[i];
        }
        return result;
    }

    /**
     * Checks whether an array is {@code null} or has zero length.
     *
     * @param array the array to check
     * @return {@code true} if the array is {@code null} or empty, {@code false} otherwise
     */
    public static boolean isEmpty(Object[] array) {
        return array == null || array.length == 0;
    }

    /**
     * Returns the minimum path sum from top to bottom of the given triangle.
     *
     * @param triangle a list of rows, each row i contains i+1 integers
     * @return the smallest possible sum when moving only to adjacent numbers
     *         on the row directly below
     */
    public static int minimumTotal(List<List<Integer>> triangle) {
        if (triangle == null || triangle.isEmpty()) {
            return 0;
        }

        int n = triangle.size();
        int[] dp = new int[n];

        // Initialise dp with the last row of the triangle
        List<Integer> lastRow = triangle.get(n - 1);
        for (int i = 0; i < n; i++) {
            dp[i] = lastRow.get(i);
        }

        // Bottom‑up DP: combine each row with the row below
        for (int row = n - 2; row >= 0; row--) {
            List<Integer> current = triangle.get(row);
            for (int col = 0; col <= row; col++) {
                dp[col] = current.get(col) + Math.min(dp[col], dp[col + 1]);
            }
        }

        return dp[0];
    }
}

