import java.util.*;

public class Solution {

    public static class Node {
        public int val;
        public Node left;
        public Node right;
        public Node next;

        public Node(int val) {
            this.val = val;
        }
    }

    /**
     * Connects each node's {@code next} pointer to its next right node in a perfect binary tree.
     *
     * @param root the root of the perfect binary tree
     * @return the root after establishing all {@code next} pointers
     */
    public Node connect(Node root) {
        if (root == null) {
            return null;
        }

        // Start with the leftmost node of the current level.
        Node leftmost = root;

        // Since the tree is perfect, we can stop when there is no left child.
        while (leftmost.left != null) {
            Node head = leftmost;
            // Iterate over the nodes in the current level.
            while (head != null) {
                // Connect left child to right child.
                head.left.next = head.right;

                // Connect right child to the next subtree's left child, if it exists.
                if (head.next != null) {
                    head.right.next = head.next.left;
                }

                // Move to the next node in the current level.
                head = head.next;
            }
            // Move down to the next level.
            leftmost = leftmost.left;
        }

        return root;
    }
}

