import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    /**
     * Determines if the string {@code s} can be segmented into a sequence of one or more
     * words from {@code wordDict}. Words may be reused multiple times.
     *
     * @param s        the input string to be segmented
     * @param wordDict the list of allowed words
     * @return {@code true} if {@code s} can be segmented, {@code false} otherwise
     */
    public boolean wordBreak(String s, List<String> wordDict) {
        if (s == null) {
            return false;
        }

        // Convert the list to a HashSet for O(1) look‑ups.
        Set<String> dict = new HashSet<>(wordDict);

        // Determine the maximum word length in the dictionary to limit inner loop work.
        int maxWordLen = 0;
        for (String w : dict) {
            if (w != null) {
                maxWordLen = Math.max(maxWordLen, w.length());
            }
        }

        int n = s.length();
        // dp[i] == true means s[0..i) can be segmented.
        boolean[] dp = new boolean[n + 1];
        dp[0] = true; // empty string is always segmentable

        for (int i = 1; i <= n; i++) {
            // Only need to check substrings whose length does not exceed maxWordLen.
            int start = Math.max(0, i - maxWordLen);
            for (int j = start; j < i; j++) {
                if (!dp[j]) {
                    continue; // prefix s[0..j) cannot be segmented, skip
                }
                String sub = s.substring(j, i);
                if (dict.contains(sub)) {
                    dp[i] = true;
                    break; // found a valid break, no need to check further for this i
                }
            }
        }

        return dp[n];
    }
}

