import com_github_leetcode.TreeNode;

/**
 * Reconstructs a binary tree from its preorder and inorder traversal arrays.
 */
public class Solution {
    private Map<Integer, Integer> inorderIndexMap;
    private int preorderIndex;

    /**
     * Constructs the binary tree from preorder and inorder traversal arrays.
     *
     * @param preorder preorder traversal of the tree
     * @param inorder  inorder traversal of the same tree
     * @return the root of the reconstructed binary tree
     */
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        inorderIndexMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderIndexMap.put(inorder[i], i);
        }
        preorderIndex = 0;
        return buildSubTree(preorder, 0, inorder.length - 1);
    }

    private TreeNode buildSubTree(int[] preorder, int left, int right) {
        if (left > right) {
            return null;
        }

        int rootVal = preorder[preorderIndex++];
        TreeNode root = new TreeNode(rootVal);

        int inorderPos = inorderIndexMap.get(rootVal);
        root.left = buildSubTree(preorder, left, inorderPos - 1);
        root.right = buildSubTree(preorder, inorderPos + 1, right);

        return root;
    }

    /**
     * Retrieves the inorder index of a given key if the tree has been built,
     * otherwise returns -1.
     *
     * @param key the value whose inorder index is requested
     * @return the inorder index or -1 if not available
     */
    public int get(int key) {
        if (inorderIndexMap == null) {
            return -1;
        }
        return inorderIndexMap.getOrDefault(key, -1);
    }
}

