public class Solution {
    public int minCut(String s) {
        if (s == null || s.length() <= 1) {
            return 0;
        }
        int n = s.length();
        int[] cuts = new int[n];
        // maximum cuts: cut each character
        for (int i = 0; i < n; i++) {
            cuts[i] = i;
        }

        for (int center = 0; center < n; center++) {
            // odd length palindromes
            expandAndUpdate(s, center, center, cuts);
            // even length palindromes
            expandAndUpdate(s, center - 1, center, cuts);
        }

        return cuts[n - 1];
    }

    private void expandAndUpdate(String s, int left, int right, int[] cuts) {
        int n = s.length();
        while (left >= 0 && right < n && s.charAt(left) == s.charAt(right)) {
            // If palindrome starts at 0, no cut needed before it
            if (left == 0) {
                cuts[right] = 0;
            } else {
                cuts[right] = Math.min(cuts[right], cuts[left - 1] + 1);
            }
            left--;
            right++;
        }
    }
}

