import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class Solution {
    public List<String> findRepeatedDnaSequences(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() < 10) {
            return result;
        }

        // Map nucleotides to 2‑bit values
        int[] map = new int[128];
        map['A'] = 0; // 00
        map['C'] = 1; // 01
        map['G'] = 2; // 10
        map['T'] = 3; // 11

        int hash = 0;
        int mask = (1 << 20) - 1; // keep only 20 bits (10 * 2)

        // Build hash for the first 10 characters
        for (int i = 0; i < 10; i++) {
            hash = (hash << 2) | map[s.charAt(i)];
        }

        Set<Integer> seen = new HashSet<>();
        Set<Integer> added = new HashSet<>();
        seen.add(hash);

        // Slide the window across the string
        for (int i = 10; i < s.length(); i++) {
            // Shift left 2 bits, add new character, and keep only last 20 bits
            hash = ((hash << 2) | map[s.charAt(i)]) & mask;

            if (seen.contains(hash)) {
                if (!added.contains(hash)) {
                    result.add(s.substring(i - 9, i + 1));
                    added.add(hash);
                }
            } else {
                seen.add(hash);
            }
        }

        return result;
    }
}

