/**
 * Reconstructs a binary tree from its inorder and postorder traversal arrays.
 */
public class Solution {
    private Map<Integer, Integer> inorderIndexMap;

    /**
     * Builds the binary tree.
     *
     * @param inorder   inorder traversal of the tree
     * @param postorder postorder traversal of the same tree
     * @return the root of the reconstructed binary tree, or {@code null} if input is invalid
     */
    public TreeNode buildTree(int[] inorder, int[] postorder) {
        if (inorder == null || postorder == null || inorder.length != postorder.length) {
            return null;
        }

        // Map each value to its index in the inorder array for O(1) look‑ups.
        inorderIndexMap = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderIndexMap.put(inorder[i], i);
        }

        return build(inorder, 0, inorder.length - 1,
                     postorder, 0, postorder.length - 1);
    }

    /**
     * Recursive helper that constructs the subtree defined by the current slices
     * of the inorder and postorder arrays.
     *
     * @param inorder   full inorder array
     * @param inStart   start index (inclusive) for the current inorder slice
     * @param inEnd     end index (inclusive) for the current inorder slice
     * @param postorder full postorder array
     * @param postStart start index (inclusive) for the current postorder slice
     * @param postEnd   end index (inclusive) for the current postorder slice
     * @return root node of the constructed subtree
     */
    private TreeNode build(int[] inorder, int inStart, int inEnd,
                           int[] postorder, int postStart, int postEnd) {
        if (inStart > inEnd || postStart > postEnd) {
            return null;
        }

        // The last element in postorder slice is the root of the current subtree.
        int rootVal = postorder[postEnd];
        TreeNode root = new TreeNode(rootVal);

        // Locate root in inorder to separate left and right subtrees.
        int inorderRootIndex = inorderIndexMap.get(rootVal);
        int leftTreeSize = inorderRootIndex - inStart;

        // Recursively build left and right subtrees.
        root.left = build(inorder, inStart, inorderRootIndex - 1,
                          postorder, postStart, postStart + leftTreeSize - 1);
        root.right = build(inorder, inorderRootIndex + 1, inEnd,
                           postorder, postStart + leftTreeSize, postEnd - 1);

        return root;
    }
}

