public class Solution {
    public int maxProduct(int[] nums) {
        // Initialize the maximum, minimum products ending at the current position
        // and the global maximum product.
        int maxEndingHere = nums[0];
        int minEndingHere = nums[0];
        int globalMax = nums[0];

        for (int i = 1; i < nums.length; i++) {
            int current = nums[i];

            // If the current number is negative, swapping max and min
            // accounts for the sign change when multiplied.
            if (current < 0) {
                int temp = maxEndingHere;
                maxEndingHere = minEndingHere;
                minEndingHere = temp;
            }

            // Compute the new max/min products ending at this index.
            maxEndingHere = Math.max(current, maxEndingHere * current);
            minEndingHere = Math.min(current, minEndingHere * current);

            // Update the global maximum product found so far.
            globalMax = Math.max(globalMax, maxEndingHere);
        }

        return globalMax;
    }
}

