public class Solution {
    public int numDistinct(String text, String text2) {
        // Edge cases
        if (text2 == null) {
            return 0;
        }
        if (text2.length() == 0) {
            return 1; // empty string is a subsequence of any string
        }
        if (text == null || text.length() == 0) {
            return 0;
        }

        int n = text.length();
        int m = text2.length();

        // dp[j] = number of ways to form text2[0..j) using processed prefix of text
        long[] dp = new long[m + 1];
        dp[0] = 1; // empty target

        for (int i = 1; i <= n; i++) {
            char cS = text.charAt(i - 1);
            // iterate backwards to avoid overwriting dp[j-1] needed for current i
            for (int j = m; j >= 1; j--) {
                if (cS == text2.charAt(j - 1)) {
                    dp[j] += dp[j - 1];
                }
            }
        }

        // The problem guarantees the result fits in a 32‑bit signed integer
        return (int) dp[m];
    }
}

