/**
 * Detects the node where a cycle begins in a singly‑linked list.
 * If there is no cycle, returns {@code null}.
 */
public class Solution {
    /**
     * Returns the node where the cycle begins in the given linked list,
     * or {@code null} if the list does not contain a cycle.
     *
     * @param head the head of the linked list
     * @return the entry node of the cycle, or {@code null} if none exists
     */
    public ListNode detectCycle(ListNode head) {
        if (head == null || head.next == null) {
            return null;
        }

        // Phase 1: Determine whether a cycle exists using Floyd's Tortoise and Hare algorithm.
        ListNode slow = head;
        ListNode fast = head;
        boolean hasCycle = false;

        while (fast != null && fast.next != null) {
            slow = slow.next;          // move one step
            fast = fast.next.next;     // move two steps
            if (slow == fast) {
                hasCycle = true;
                break;
            }
        }

        // No cycle found.
        if (!hasCycle) {
            return null;
        }

        // Phase 2: Find the entry point of the cycle.
        ListNode ptr1 = head;
        ListNode ptr2 = slow; // both are k steps from the start of the cycle

        while (ptr1 != ptr2) {
            ptr1 = ptr1.next;
            ptr2 = ptr2.next;
        }

        return ptr1; // or ptr2, both point to the start of the cycle
    }
}

