/**
 * Provides a method to find the intersection node of two singly linked lists.
 */
public class Solution {

    /**
     * Returns the node at which the two singly linked lists intersect.
     * If there is no intersection, returns {@code null}.
     *
     * @param headA head of the first linked list
     * @param headB head of the second linked list
     * @return the intersecting node or {@code null}
     */
    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        if (headA == null || headB == null) {
            return null;
        }

        ListNode a = headA;
        ListNode b = headB;

        // Traverse both lists; when one pointer reaches the end,
        // continue from the head of the other list.
        // This equalises the total distance travelled by each pointer.
        while (a != b) {
            a = (a == null) ? headB : a.next;
            b = (b == null) ? headA : b.next;
        }

        // Either both are null (no intersection) or both point to the intersecting node.
        return a;
    }
}

