/**
 * Converts a sorted (ascending) integer array into a height‑balanced binary search tree.
 */
public class Solution {

    /**
     * Converts a sorted (ascending) integer array into a height‑balanced binary search tree.
     *
     * @param nums the sorted array
     * @return the root of the constructed BST, or {@code null} if the array is empty
     */
    public TreeNode sortedArrayToBST(int[] nums) {
        if (nums == null || nums.length == 0) {
            return null;
        }
        return buildBST(nums, 0, nums.length - 1);
    }

    private TreeNode buildBST(int[] nums, int left, int right) {
        if (left > right) {
            return null;
        }
        int mid = left + (right - left) / 2;
        TreeNode node = new TreeNode(nums[mid]);
        node.left = buildBST(nums, left, mid - 1);
        node.right = buildBST(nums, mid + 1, right);
        return node;
    }

    /**
     * Definition for a binary tree node.
     */
    public static class TreeNode {
        public int val;
        public TreeNode left;
        public TreeNode right;

        public TreeNode(int val) {
            this.val = val;
        }

        @Override
        public String toString() {
            List<String> parts = new ArrayList<>();
            preOrder(this, parts);

            // Trim trailing "null" entries
            int last = parts.size() - 1;
            while (last >= 0 && "null".equals(parts.get(last))) {
                last--;
            }
            return String.join(",", parts.subList(0, last + 1));
        }

        /** Recursive pre‑order traversal that records "null" for missing children. */
        private static void preOrder(TreeNode node, List<String> parts) {
            if (node == null) {
                parts.add("null");
                return;
            }
            parts.add(String.valueOf(node.val));
            preOrder(node.left, parts);
            preOrder(node.right, parts);
        }
    }
}

