public class Solution {
    public TreeNode sortedListToBST(ListNode head) {
        return buildBST(head);
    }

    private TreeNode buildBST(ListNode head) {
        if (head == null) {
            return null;
        }
        if (head.next == null) {
            return new TreeNode(head.val);
        }

        ListNode prev = null;
        ListNode slow = head;
        ListNode fast = head;

        while (fast != null && fast.next != null) {
            prev = slow;
            slow = slow.next;
            fast = fast.next.next;
        }

        // Disconnect left half from the middle node
        if (prev != null) {
            prev.next = null;
        }

        TreeNode root = new TreeNode(slow.val);
        root.left = (prev == null) ? null : buildBST(head);
        root.right = buildBST(slow.next);
        return root;
    }
}

