/**
 * Reorders a singly‑linked list in-place to the pattern:
 * L0 → Ln → L1 → Ln‑1 → L2 → Ln‑2 → …
 *
 * The ListNode public class Solution expected to be available in the same package
 * (or in the default package) as this Solution class.
 */
public class Solution {

    public void reorderList(ListNode head) {
        if (head == null || head.next == null) {
            return;
        }

        // 1. Find the middle of the list (slow will point to the end of the first half)
        ListNode slow = head;
        ListNode fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // 2. Split and reverse the second half
        ListNode second = slow.next;
        slow.next = null; // terminate first half

        ListNode prev = null;
        ListNode curr = second;
        while (curr != null) {
            ListNode nextTmp = curr.next;
            curr.next = prev;
            prev = curr;
            curr = nextTmp;
        }
        // 'prev' is now the head of the reversed second half

        // 3. Merge the two halves alternately
        ListNode first = head;
        ListNode secondHead = prev;
        while (secondHead != null) {
            ListNode tmp1 = first.next;
            ListNode tmp2 = secondHead.next;

            first.next = secondHead;
            secondHead.next = tmp1;

            first = tmp1;
            secondHead = tmp2;
        }
    }
}

