/**
 * Utility class for constructing binary trees from level‑order data.
 */
class TreeUtils {

    /**
     * Constructs a binary tree from a {@link List} that represents a level‑order
     * traversal where {@code null} denotes a missing node.
     *
     * @param values level‑order representation of the tree
     * @return the root of the constructed binary tree, or {@code null} if the list is empty or {@code null}
     */
    public static TreeNode constructBinaryTree(List<Integer> values) {
        if (values == null || values.isEmpty()) {
            return null;
        }
        Integer[] arr = values.toArray(new Integer[0]);
        return buildTree(arr);
    }

    /**
     * Internal helper that builds a tree from an {@code Integer[]} array.
     *
     * @param values level‑order array representation (may contain {@code null})
     * @return root of the binary tree
     */
    private static TreeNode buildTree(Integer[] values) {
        if (values == null || values.length == 0) {
            return null;
        }
        TreeNode root = new TreeNode(values[0]);
        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        int index = 1;
        while (index < values.length) {
            TreeNode current = queue.poll();
            if (current == null) {
                continue;
            }
            // left child
            Integer leftVal = values[index++];
            if (leftVal != null) {
                TreeNode leftNode = new TreeNode(leftVal);
                current.left = leftNode;
                queue.add(leftNode);
            }
            // right child
            if (index < values.length) {
                Integer rightVal = values[index++];
                if (rightVal != null) {
                    TreeNode rightNode = new TreeNode(rightVal);
                    current.right = rightNode;
                    queue.add(rightNode);
                }
            }
        }
        return root;
    }
}

