public class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int totalTank = 0;
        int currTank = 0;
        int startingStation = 0;
        for (int i = 0; i < gas.length; i++) {
            int diff = gas[i] - cost[i];
            totalTank += diff;
            currTank += diff;
            // If at any point current tank is negative, cannot start from previous start
            if (currTank < 0) {
                // reset start to next station
                startingStation = i + 1;
                currTank = 0;
            }
        }
        return totalTank >= 0 ? startingStation % gas.length : -1;
    }
}

