import java.util.ArrayDeque;
import java.util.Queue;

public class Solution {

    /**
     * Definition for a binary tree node with a next pointer.
     */
    public static class Node {
        public int val;
        public Node left;
        public Node right;
        public Node next; // defaults to null

        public Node() {
        }

        public Node(int val) {
            this.val = val;
        }
    }

    /**
     * Connects each node's {@code next} pointer to its next right node at the same depth.
     *
     * @param root the root of the binary tree
     * @return the same root after linking {@code next} pointers
     */
    public Node connect(Node root) {
        if (root == null) {
            return null;
        }

        Queue<Node> queue = new ArrayDeque<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            Node prev = null;

            for (int i = 0; i < levelSize; i++) {
                Node current = queue.poll();

                if (prev != null) {
                    prev.next = current;
                }
                prev = current;

                if (current.left != null) {
                    queue.offer(current.left);
                }
                if (current.right != null) {
                    queue.offer(current.right);
                }
            }
            // The last node of each level already has next == null by default
        }

        return root;
    }
}

