import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String fractionToDecimal(int numerator, int denominator) {
        // Handle division by zero (though problem guarantees denominator != 0)
        if (denominator == 0) {
            throw new ArithmeticException("Division by zero");
        }

        // Use long to avoid overflow when taking absolute values
        long num = numerator;
        long den = denominator;

        StringBuilder sb = new StringBuilder();

        // Determine sign
        if ((num < 0) ^ (den < 0) && num != 0) {
            sb.append('-');
        }

        // Work with absolute values
        num = Math.abs(num);
        den = Math.abs(den);

        // Integer part
        long integerPart = num / den;
        sb.append(integerPart);

        // Remainder
        long remainder = num % den;
        if (remainder == 0) {
            return sb.toString(); // No fractional part
        }

        sb.append('.');

        // Map to store previously seen remainders and their corresponding index in the result
        Map<Long, Integer> remainderIndexMap = new HashMap<>();

        while (remainder != 0) {
            // If this remainder has been seen before, we have a repeating cycle
            if (remainderIndexMap.containsKey(remainder)) {
                int index = remainderIndexMap.get(remainder);
                sb.insert(index, '(');
                sb.append(')');
                break;
            }

            // Store the index where this remainder's digit will be placed
            remainderIndexMap.put(remainder, sb.length());

            remainder *= 10;
            long digit = remainder / den;
            sb.append(digit);
            remainder %= den;
        }

        return sb.toString();
    }
}

