import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

/**
 * Solution for the Word Ladder II problem.
 * Returns all shortest transformation sequences from beginWord to endWord.
 */
public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        List<List<String>> results = new ArrayList<>();
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) {
            return results;
        }

        // distance map stores the level (shortest distance) from beginWord
        Map<String, Integer> distance = new HashMap<>();
        // children map stores forward edges for the BFS tree (only edges that belong to shortest paths)
        Map<String, List<String>> children = new HashMap<>();

        bfs(beginWord, endWord, wordSet, distance, children);
        if (!distance.containsKey(endWord)) {
            return results; // endWord not reachable
        }

        List<String> path = new ArrayList<>();
        path.add(beginWord);
        dfs(beginWord, endWord, children, path, results);
        return results;
    }

    private void bfs(String beginWord,
                     String endWord,
                     Set<String> wordSet,
                     Map<String, Integer> distance,
                     Map<String, List<String>> children) {

        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);
        distance.put(beginWord, 0);

        int wordLen = beginWord.length();
        int foundLevel = Integer.MAX_VALUE;

        while (!queue.isEmpty()) {
            int size = queue.size();
            Set<String> visitedThisLevel = new HashSet<>();

            for (int i = 0; i < size; i++) {
                String cur = queue.poll();
                int curDist = distance.get(cur);
                if (curDist > foundLevel) {
                    continue; // we already found the shortest level
                }

                char[] curArr = cur.toCharArray();
                for (int pos = 0; pos < wordLen; pos++) {
                    char original = curArr[pos];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) continue;
                        curArr[pos] = c;
                        String next = new String(curArr);

                        // Only consider words that are in the set or the endWord itself
                        if (!wordSet.contains(next) && !next.equals(endWord)) {
                            continue;
                        }

                        // Record edge for possible paths
                        children.computeIfAbsent(cur, k -> new ArrayList<>()).add(next);

                        if (!distance.containsKey(next)) {
                            distance.put(next, curDist + 1);
                            visitedThisLevel.add(next);
                            queue.offer(next);
                        }

                        if (next.equals(endWord)) {
                            foundLevel = curDist + 1;
                        }
                    }
                    curArr[pos] = original;
                }
            }
            // Remove visited words of this layer to avoid revisiting them later
            wordSet.removeAll(visitedThisLevel);
        }
    }

    private void dfs(String cur,
                     String endWord,
                     Map<String, List<String>> children,
                     List<String> path,
                     List<List<String>> results) {
        if (cur.equals(endWord)) {
            results.add(new ArrayList<>(path));
            return;
        }
        List<String> nextList = children.get(cur);
        if (nextList == null) {
            return;
        }
        for (String next : nextList) {
            path.add(next);
            dfs(next, endWord, children, path, results);
            path.remove(path.size() - 1);
        }
    }
}

