/**
 * Solution class that sorts a singly‑linked list using merge sort.
 */
public class Solution {

    /**
     * Sorts the linked list in ascending order.
     *
     * @param head the head of the list to sort
     * @return the head of the sorted list
     */
    public ListNode sortList(ListNode head) {
        // Base case: empty list or single node is already sorted
        if (head == null || head.next == null) {
            return head;
        }

        // Split the list into two halves
        ListNode mid = getMiddle(head);
        ListNode rightHead = mid.next;
        mid.next = null; // break the list

        // Recursively sort both halves
        ListNode leftSorted = sortList(head);
        ListNode rightSorted = sortList(rightHead);

        // Merge the two sorted halves
        return merge(leftSorted, rightSorted);
    }

    /**
     * Finds the middle node of the list (the end of the first half).
     *
     * @param head the head of the list
     * @return the middle node
     */
    private ListNode getMiddle(ListNode head) {
        // Slow and fast pointers; fast starts one step ahead so that
        // the first half is longer when the length is even.
        ListNode slow = head;
        ListNode fast = head.next;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }

    /**
     * Merges two sorted linked lists.
     *
     * @param l1 first sorted list
     * @param l2 second sorted list
     * @return head of the merged sorted list
     */
    private ListNode merge(ListNode l1, ListNode l2) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;

        while (l1 != null && l2 != null) {
            if (l1.val <= l2.val) {
                tail.next = l1;
                l1 = l1.next;
            } else {
                tail.next = l2;
                l2 = l2.next;
            }
            tail = tail.next;
        }

        // Append any remaining nodes
        tail.next = (l1 != null) ? l1 : l2;

        return dummy.next;
    }
}

