public class Solution {
    public int[] corpFlightBookings(int[][] bookings, int n) {
        int[] diff = new int[n + 1];
        for (int[] b : bookings) {
            int first = b[0] - 1; // zero‑based index
            int last = b[1] - 1;
            int seats = b[2];
            diff[first] += seats;
            if (last + 1 < n) {
                diff[last + 1] -= seats;
            }
        }
        int[] answer = new int[n];
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            answer[i] = cur;
        }
        return answer;
    }
}

