import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        // Sort and deduplicate arr2
        int[] sortedArr2 = arr2.clone();
        Arrays.sort(sortedArr2);
        int m = 0;
        for (int i = 0; i < sortedArr2.length; i++) {
            if (i == 0 || sortedArr2[i] != sortedArr2[i - 1]) {
                sortedArr2[m++] = sortedArr2[i];
            }
        }
        sortedArr2 = Arrays.copyOf(sortedArr2, m);

        // dp maps the last value of the processed prefix to the minimal operations needed
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(Integer.MIN_VALUE, 0); // sentinel before the first element

        for (int value : arr1) {
            Map<Integer, Integer> next = new HashMap<>();

            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int prev = entry.getKey();
                int ops = entry.getValue();

                // 1) Keep current arr1 element if it keeps the sequence strictly increasing
                if (value > prev) {
                    next.merge(value, ops, Math::min);
                }

                // 2) Replace current element with the smallest arr2 element greater than prev
                int idx = Arrays.binarySearch(sortedArr2, prev);
                if (idx < 0) {
                    idx = -idx - 1; // insertion point gives first element > prev
                } else {
                    idx = idx + 1; // need strictly greater
                }
                if (idx < sortedArr2.length) {
                    int replaceVal = sortedArr2[idx];
                    next.merge(replaceVal, ops + 1, Math::min);
                }
            }

            dp = next;
            if (dp.isEmpty()) {
                return -1; // no possible state at this position
            }
        }

        int answer = Integer.MAX_VALUE;
        for (int ops : dp.values()) {
            answer = Math.min(answer, ops);
        }
        return answer == Integer.MAX_VALUE ? -1 : answer;
    }
}

