import java.util.*;

public class Solution {
    public int maxNumberOfBalloons(String text) {
        if (text == null || text.isEmpty()) {
            return 0;
        }
        int[] count = new int[26];
        for (char c : text.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                count[c - 'a']++;
            } else if (c >= 'A' && c <= 'Z') {
                count[c - 'A']++;
            }
        }
        int b = count['b' - 'a'];
        int a = count['a' - 'a'];
        int l = count['l' - 'a'] / 2;
        int o = count['o' - 'a'] / 2;
        int n = count['n' - 'a'];
        return Math.min(Math.min(Math.min(b, a), Math.min(l, o)), n);
    }
}

