import java.util.ArrayList;
import java.util.List;

public class Solution {

    private static class Pair {
        char c;
        int count;

        Pair(char c, int count) {
            this.c = c;
            this.count = count;
        }
    }

    /**
     * Returns the length of the longest substring consisting of the same character
     * that can be obtained after swapping at most two characters in the given text.
     *
     * @param text the input string consisting of lowercase English letters
     * @return the maximum possible length of a repeated‑character substring
     */
    public int maxRepOpt1(String text) {
        if (text == null || text.isEmpty()) {
            return 0;
        }

        int n = text.length();
        int[] total = new int[26];
        for (int i = 0; i < n; i++) {
            total[text.charAt(i) - 'a']++;
        }

        // Build blocks of consecutive identical characters
        List<Pair> blocks = new ArrayList<>();
        int i = 0;
        while (i < n) {
            char cur = text.charAt(i);
            int j = i;
            while (j < n && text.charAt(j) == cur) {
                j++;
            }
            blocks.add(new Pair(cur, j - i));
            i = j;
        }

        int answer = 0;

        // Case 1: extend a single block by swapping one matching character from elsewhere
        for (Pair block : blocks) {
            int idx = block.c - 'a';
            int possible = Math.min(block.count + 1, total[idx]);
            answer = Math.max(answer, possible);
        }

        // Case 2: merge two blocks separated by a single different character
        for (int k = 0; k < blocks.size() - 2; k++) {
            Pair left = blocks.get(k);
            Pair middle = blocks.get(k + 1);
            Pair right = blocks.get(k + 2);

            if (left.c == right.c && middle.count == 1) {
                int idx = left.c - 'a';
                int combined = left.count + right.count;
                // If there is at least one more occurrence of this character elsewhere,
                // we can swap it into the middle position.
                if (total[idx] > combined) {
                    combined += 1;
                }
                answer = Math.max(answer, combined);
            }
        }

        return answer;
    }
}

