import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int maxDistance(int[][] grid) {
        int n = grid.length;
        if (n == 0) return -1;

        Queue<int[]> q = new LinkedList<>();
        int landCount = 0;

        // enqueue all land cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    q.offer(new int[]{i, j});
                    landCount++;
                }
            }
        }

        // if there is no land or no water, return -1
        if (landCount == 0 || landCount == n * n) {
            return -1;
        }

        int maxDist = -1;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!q.isEmpty()) {
            int size = q.size();
            maxDist++; // increase distance for the next layer
            for (int s = 0; s < size; s++) {
                int[] cur = q.poll();
                int x = cur[0];
                int y = cur[1];
                for (int[] d : dirs) {
                    int nx = x + d[0];
                    int ny = y + d[1];
                    if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] == 0) {
                        grid[nx][ny] = 1; // mark as visited (convert water to land)
                        q.offer(new int[]{nx, ny});
                    }
                }
            }
        }

        return maxDist;
    }
}

