public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        long movesEvenPeak = 0; // pattern: even indices are peaks, so odd indices must be valleys
        long movesOddPeak = 0;  // pattern: odd indices are peaks, so even indices must be valleys

        for (int i = 0; i < n; i++) {
            int left = i > 0 ? nums[i - 1] : Integer.MAX_VALUE;
            int right = i + 1 < n ? nums[i + 1] : Integer.MAX_VALUE;
            int minNeighbor = Math.min(left, right);

            // For pattern where even indices are peaks, odd indices need to be lower than neighbors
            if ((i & 1) == 1) { // odd index
                if (nums[i] >= minNeighbor) {
                    movesEvenPeak += (long) nums[i] - (minNeighbor - 1);
                }
            } else { // even index for the opposite pattern
                if (nums[i] >= minNeighbor) {
                    movesOddPeak += (long) nums[i] - (minNeighbor - 1);
                }
            }
        }

        return (int) Math.min(movesEvenPeak, movesOddPeak);
    }
}

