import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Boolean> canMakePaliQueries(String s, int[][] queries) {
        int n = s.length();
        // prefix masks: mask[i] represents parity of counts in s[0..i-1]
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            int bit = 1 << (s.charAt(i) - 'a');
            prefix[i + 1] = prefix[i] ^ bit;
        }

        List<Boolean> ans = new ArrayList<>(queries.length);
        for (int[] q : queries) {
            int left = q[0];
            int right = q[1];
            int k = q[2];

            // parity mask for substring [left, right]
            int mask = prefix[right + 1] ^ prefix[left];
            int oddCount = Integer.bitCount(mask);

            // Minimum replacements needed = oddCount / 2
            boolean ok = (oddCount / 2) <= k;
            ans.add(ok);
        }
        return ans;
    }
}

