/**
 * Provides a method to deep‑copy a linked list where each node contains an additional
 * random pointer that may point to any node in the list or be {@code null}.
 */
public class Solution {

    /**
     * Definition for a singly‑linked list node with a random pointer.
     */
    public static class Node {
        public int val;
        public Node next;
        public Node random;

        public Node(int val) {
            this.val = val;
        }
    }

    /**
     * Creates a deep copy of a linked list with random pointers.
     *
     * @param head the head of the original linked list
     * @return the head of the deep‑copied linked list
     */
    public Node copyRandomList(Node head) {
        if (head == null) {
            return null;
        }

        // 1️⃣ First pass: interleave cloned nodes with original nodes.
        Node curr = head;
        while (curr != null) {
            Node clone = new Node(curr.val);
            clone.next = curr.next;
            curr.next = clone;
            curr = clone.next;
        }

        // 2️⃣ Second pass: assign random pointers for the cloned nodes.
        curr = head;
        while (curr != null) {
            Node clone = curr.next;
            clone.random = (curr.random != null) ? curr.random.next : null;
            curr = clone.next;
        }

        // 3️⃣ Third pass: detach the cloned list from the original list.
        Node dummy = new Node(0);
        Node copyCurr = dummy;
        curr = head;
        while (curr != null) {
            Node clone = curr.next;
            // Restore original list's next pointer.
            curr.next = clone.next;
            // Append cloned node to the new list.
            copyCurr.next = clone;
            copyCurr = clone;
            // Move to the next original node.
            curr = curr.next;
        }

        return dummy.next;
    }
}

