import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int mctFromLeafValues(int[] arr) {
        // Monotonic decreasing stack solution.
        // The stack keeps a decreasing sequence of leaf values.
        // When a new value is greater or equal to the top, we can safely
        // combine the top (which is the smallest among its neighbours) with
        // the smaller of its two neighbours to minimize the added cost.
        Deque<Integer> stack = new ArrayDeque<>();
        // Sentinel to avoid empty checks.
        stack.push(Integer.MAX_VALUE);
        int cost = 0;

        for (int num : arr) {
            // While the current number is greater than or equal to the
            // element on the top of the stack, pop and combine.
            while (stack.peek() <= num) {
                int mid = stack.pop();
                int left = stack.peek();          // left neighbour (still larger)
                int right = num;                  // right neighbour (current number)
                cost += mid * Math.min(left, right);
            }
            stack.push(num);
        }

        // After processing all numbers, combine the remaining elements.
        // The stack now holds a decreasing sequence; we just pair from the top.
        while (stack.size() > 2) { // more than sentinel and one leaf left
            int mid = stack.pop();
            cost += mid * stack.peek();
        }

        return cost;
    }
}

