import java.util.Arrays;

public class Solution {
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        // suffix sums: suffix[i] = total stones from i to end
        int[] suffix = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            suffix[i] = suffix[i + 1] + piles[i];
        }

        // memo[i][M] stores the maximum stones the current player can obtain
        // starting from index i with current M.
        int[][] memo = new int[n][n + 1];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }

        return dfs(0, 1, n, suffix, memo);
    }

    private int dfs(int i, int M, int n, int[] suffix, int[][] memo) {
        if (i >= n) {
            return 0;
        }
        if (memo[i][M] != -1) {
            return memo[i][M];
        }

        int maxStones = 0;
        // Try taking X piles where 1 <= X <= 2M
        for (int X = 1; X <= 2 * M && i + X <= n; X++) {
            // Stones opponent can obtain after we take X piles
            int opponentStones = dfs(i + X, Math.max(M, X), n, suffix, memo);
            // Our stones = total remaining stones - opponent's best result
            int currentStones = suffix[i] - opponentStones;
            if (currentStones > maxStones) {
                maxStones = currentStones;
            }
        }

        memo[i][M] = maxStones;
        return maxStones;
    }
}

