import java.util.*;

public class Solution {

    /**
     * Deletes the nodes whose values appear in {@code to_delete} from the binary tree rooted at {@code root}
     * and returns a list containing the roots of the trees in the remaining forest.
     *
     * @param root      the root of the original binary tree
     * @param to_delete array of node values to delete
     * @return list of roots of the trees in the forest after deletions
     */
    public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
        Set<Integer> delSet = new HashSet<>();
        for (int v : to_delete) {
            delSet.add(v);
        }

        List<TreeNode> forest = new ArrayList<>();
        TreeNode newRoot = dfs(root, delSet, forest);
        if (newRoot != null) {
            forest.add(newRoot);
        }
        return forest;
    }

    /**
     * Post‑order traversal that removes nodes marked for deletion.
     *
     * @param node    current node
     * @param delSet  set of values to delete
     * @param forest  collection where new tree roots are added
     * @return the node itself if it remains in the tree, otherwise {@code null}
     */
    private TreeNode dfs(TreeNode node, Set<Integer> delSet, List<TreeNode> forest) {
        if (node == null) {
            return null;
        }

        boolean toDelete = delSet.contains(node.val);
        node.left = dfs(node.left, delSet, forest);
        node.right = dfs(node.right, delSet, forest);

        if (toDelete) {
            if (node.left != null) {
                forest.add(node.left);
            }
            if (node.right != null) {
                forest.add(node.right);
            }
            return null;
        }
        return node;
    }
}

