import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int longestWPI(int[] hours) {
        int n = hours.length;
        // Prefix sum where tiring day (+1) and non‑tiring day (‑1)
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + (hours[i] > 8 ? 1 : -1);
        }

        // Build a monotonic decreasing stack of prefix indices
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i <= n; i++) {
            if (stack.isEmpty() || prefix[i] < prefix[stack.peek()]) {
                stack.push(i);
            }
        }

        int longest = 0;
        // Scan from the end to find the farthest earlier index with smaller prefix sum
        for (int i = n; i >= 0; i--) {
            while (!stack.isEmpty() && prefix[i] > prefix[stack.peek()]) {
                longest = Math.max(longest, i - stack.pop());
            }
        }
        return longest;
    }
}

