import java.util.Stack;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public boolean parseBoolExpr(String expression) {
        Stack<Character> stack = new Stack<>();

        for (char ch : expression.toCharArray()) {
            if (ch != ')') {
                // push everything except closing parenthesis
                stack.push(ch);
            } else {
                // evaluate the sub‑expression inside the most recent '('
                List<Boolean> values = new ArrayList<>();

                // collect literals until '(' is found
                while (!stack.isEmpty() && stack.peek() != '(') {
                    char top = stack.pop();
                    if (top == 't') {
                        values.add(true);
                    } else if (top == 'f') {
                        values.add(false);
                    } // commas are ignored
                }

                // discard '('
                if (!stack.isEmpty() && stack.peek() == '(') {
                    stack.pop();
                }

                // operator is right before '('
                char operator = stack.pop();

                boolean result;
                if (operator == '!') {
                    // NOT has exactly one operand
                    result = !values.get(0);
                } else if (operator == '&') {
                    result = true;
                    for (boolean v : values) {
                        result = result && v;
                        if (!result) break; // short‑circuit
                    }
                } else { // operator == '|'
                    result = false;
                    for (boolean v : values) {
                        result = result || v;
                        if (result) break; // short‑circuit
                    }
                }

                // push the result back as a literal
                stack.push(result ? 't' : 'f');
            }
        }

        // final value is the only element left on the stack
        return stack.pop() == 't';
    }
}

