import java.util.*;

public class Solution {
    private int leftSize;   // size of left subtree of node x
    private int rightSize;  // size of right subtree of node x
    private int target;     // value x chosen by the first player

    /**
     * Determines whether the second player can guarantee a win by choosing an
     * appropriate node y.
     *
     * @param root the root of the binary tree
     * @param n    total number of nodes (odd)
     * @param x    value chosen by the first player
     * @return true if a winning move exists for the second player, false otherwise
     */
    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        this.target = x;
        countSubtree(root); // fills leftSize and rightSize
        int parentSize = n - (leftSize + rightSize + 1); // nodes outside x's subtree
        int maxRegion = Math.max(Math.max(leftSize, rightSize), parentSize);
        return maxRegion > n / 2;
    }

    /**
     * Recursively computes the size of each subtree.
     * When the current node is the target (value x), records the sizes of its
     * left and right subtrees.
     *
     * @param node current node
     * @return size of the subtree rooted at {@code node}
     */
    private int countSubtree(TreeNode node) {
        if (node == null) {
            return 0;
        }
        int leftCount = countSubtree(node.left);
        int rightCount = countSubtree(node.right);
        if (node.val == target) {
            leftSize = leftCount;
            rightSize = rightCount;
        }
        return leftCount + rightCount + 1;
    }

    /**
     * Definition for a binary tree node.
     */
    public static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        public TreeNode() {}

        public TreeNode(int val) {
            this.val = val;
        }

        public TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }

        /**
         * Builds a binary tree from a level‑order list where {@code null}
         * represents a missing node.
         *
         * @param values list of node values in level order
         * @return the root of the constructed binary tree
         */
        public static TreeNode create(List<Integer> values) {
            if (values == null || values.isEmpty()) {
                return null;
            }
            Iterator<Integer> it = values.iterator();
            Integer rootVal = it.next();
            if (rootVal == null) {
                return null;
            }
            TreeNode root = new TreeNode(rootVal);
            Queue<TreeNode> queue = new ArrayDeque<>();
            queue.add(root);
            while (it.hasNext()) {
                TreeNode parent = queue.poll();
                if (parent == null) {
                    continue;
                }
                // left child
                Integer leftVal = it.next();
                if (leftVal != null) {
                    parent.left = new TreeNode(leftVal);
                    queue.add(parent.left);
                }
                // right child (if present)
                if (it.hasNext()) {
                    Integer rightVal = it.next();
                    if (rightVal != null) {
                        parent.right = new TreeNode(rightVal);
                        queue.add(parent.right);
                    }
                }
            }
            return root;
        }
    }
}

