import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    /**
     * Returns any smallest sufficient team.
     *
     * @param req_skills array of required skill names
     * @param people     list where each element is a list of skill names a person possesses
     * @return array of selected person indices forming a smallest sufficient team
     */
    public int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
        int skillCount = req_skills.length;

        // Map each required skill to a unique bit position
        Map<String, Integer> skillToBit = new HashMap<>();
        for (int i = 0; i < skillCount; i++) {
            skillToBit.put(req_skills[i], i);
        }

        // Convert each person's skill list to a bitmask
        int[] personMask = new int[people.size()];
        for (int i = 0; i < people.size(); i++) {
            int mask = 0;
            for (String skill : people.get(i)) {
                Integer bit = skillToBit.get(skill);
                if (bit != null) {
                    mask |= 1 << bit;
                }
            }
            personMask[i] = mask;
        }

        int fullMask = (1 << skillCount) - 1;

        // dp[mask] holds the smallest team (list of indices) that achieves this mask
        @SuppressWarnings("unchecked")
        List<Integer>[] dp = new List[1 << skillCount];
        dp[0] = new ArrayList<>();

        for (int i = 0; i < personMask.length; i++) {
            int pMask = personMask[i];
            if (pMask == 0) {
                continue; // this person adds no new required skill
            }

            // Iterate over a snapshot of current dp states
            for (int mask = 0; mask <= fullMask; mask++) {
                if (dp[mask] == null) {
                    continue;
                }
                int newMask = mask | pMask;
                if (dp[newMask] == null || dp[mask].size() + 1 < dp[newMask].size()) {
                    List<Integer> newTeam = new ArrayList<>(dp[mask]);
                    newTeam.add(i);
                    dp[newMask] = newTeam;
                }
            }
        }

        List<Integer> resultList = dp[fullMask];
        int[] result = new int[resultList.size()];
        for (int i = 0; i < resultList.size(); i++) {
            result[i] = resultList.get(i);
        }
        return result;
    }
}

