public class Solution {
    public String lastSubstring(String s) {
        int n = s.length();
        int i = 0; // start index of the best suffix found so far
        int j = 1; // start index of the candidate suffix
        int k = 0; // offset for comparison

        while (j + k < n) {
            char a = s.charAt(i + k);
            char b = s.charAt(j + k);
            if (a == b) {
                k++;
            } else if (a < b) {
                // candidate suffix is better, move i to j
                i = j;
                j = i + 1;
                k = 0;
            } else { // a > b
                // current best suffix is still better, skip the inferior candidate
                j = j + k + 1;
                k = 0;
            }
        }
        return s.substring(i);
    }
}

