import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int numEquivDominoPairs(int[][] dominoes) {
        // Map to store the frequency of each normalized domino representation
        Map<Integer, Integer> countMap = new HashMap<>();
        int pairs = 0;

        for (int[] domino : dominoes) {
            int a = domino[0];
            int b = domino[1];
            // Normalize so that the smaller number comes first
            int key = (a < b) ? a * 10 + b : b * 10 + a;

            // If this representation has been seen before, each previous occurrence
            // forms a new pair with the current domino.
            int previous = countMap.getOrDefault(key, 0);
            pairs += previous;

            // Update the frequency
            countMap.put(key, previous + 1);
        }

        return pairs;
    }
}

