/**
 * Solution for finding the lowest common ancestor of the deepest leaves
 * in a binary tree.
 *
 * The TreeNode public class Solution expected to be defined in the same package
 * (referenz) or imported from the correct project package.
 */
public class Solution {

    /**
     * Returns the lowest common ancestor of the deepest leaves of the given tree.
     *
     * @param root the root of the binary tree
     * @return the LCA node of the deepest leaves
     */
    public TreeNode lcaDeepestLeaves(TreeNode root) {
        return dfs(root).node;
    }

    /**
     * Helper method that returns both the depth of the deepest leaf in the
     * current subtree and the node that is the LCA of all deepest leaves
     * within that subtree.
     *
     * @param node current tree node
     * @return a Result object containing depth and LCA node
     */
    private Result dfs(TreeNode node) {
        if (node == null) {
            return new Result(0, null);
        }

        Result left = dfs(node.left);
        Result right = dfs(node.right);

        if (left.depth == right.depth) {
            // Both sides have deepest leaves at the same depth;
            // current node becomes their LCA.
            return new Result(left.depth + 1, node);
        } else if (left.depth > right.depth) {
            // Deepest leaves are deeper in the left subtree.
            return new Result(left.depth + 1, left.node);
        } else {
            // Deepest leaves are deeper in the right subtree.
            return new Result(right.depth + 1, right.node);
        }
    }

    /**
     * Simple container for returning both depth and node information from dfs.
     */
    private static class Result {
        final int depth;
        final TreeNode node;

        Result(int depth, TreeNode node) {
            this.depth = depth;
            this.node = node;
        }
    }
}

