import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int kConcatenationMaxSum(int[] arr, int k) {
        if (arr == null || arr.length == 0 || k <= 0) {
            return 0;
        }

        long totalSum = 0;
        for (int num : arr) {
            totalSum += num;
        }

        long maxKadaneOne = kadane(arr);
        if (k == 1) {
            long ans = maxKadaneOne;
            if (ans < 0) {
                ans = 0;
            }
            return (int) (ans % MOD);
        }

        long maxKadaneTwo = kadaneTwoCopies(arr);

        long ans;
        if (totalSum > 0) {
            ans = maxKadaneTwo + totalSum * (k - 2L);
        } else {
            ans = maxKadaneTwo;
        }

        if (ans < 0) {
            ans = 0;
        }
        return (int) (ans % MOD);
    }

    // Kadane's algorithm on a single copy of the array
    private long kadane(int[] arr) {
        long maxEndingHere = arr[0];
        long maxSoFar = arr[0];
        for (int i = 1; i < arr.length; i++) {
            maxEndingHere = Math.max(arr[i], maxEndingHere + arr[i]);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }
        return maxSoFar;
    }

    // Kadane's algorithm on two concatenated copies of the array
    private long kadaneTwoCopies(int[] arr) {
        int n = arr.length;
        long maxEndingHere = arr[0];
        long maxSoFar = arr[0];
        for (int i = 1; i < 2 * n; i++) {
            int val = arr[i % n];
            maxEndingHere = Math.max(val, maxEndingHere + val);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }
        return maxSoFar;
    }
}

