import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.Set;

public class Solution {

    private static class Transaction {
        String name;
        int time;
        int amount;
        String city;
        String raw;

        Transaction(String raw) {
            this.raw = raw;
            String[] parts = raw.split(",");
            this.name = parts[0];
            this.time = Integer.parseInt(parts[1]);
            this.amount = Integer.parseInt(parts[2]);
            this.city = parts[3];
        }
    }

    public List<String> invalidTransactions(String[] transactions) {
        List<Transaction> list = new ArrayList<>();
        Map<String, List<Transaction>> byName = new HashMap<>();

        // Parse all transactions and group by name
        for (String s : transactions) {
            Transaction t = new Transaction(s);
            list.add(t);
            byName.computeIfAbsent(t.name, k -> new ArrayList<>()).add(t);
        }

        // Preserve insertion order of invalid transactions
        Set<String> invalidSet = new LinkedHashSet<>();

        // Check each transaction
        for (Transaction t : list) {
            // Rule 1: amount exceeds 1000
            if (t.amount > 1000) {
                invalidSet.add(t.raw);
            }

            // Rule 2: same name, different city, within 60 minutes
            List<Transaction> sameNameList = byName.get(t.name);
            for (Transaction other : sameNameList) {
                if (t == other) {
                    continue;
                }
                if (!t.city.equals(other.city) && Math.abs(t.time - other.time) <= 60) {
                    invalidSet.add(t.raw);
                    // Ensure the counterpart is also marked invalid (optional but safe)
                    invalidSet.add(other.raw);
                    break;
                }
            }
        }

        return new ArrayList<>(invalidSet);
    }
}

