import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Solution for finding all pairs of elements with the minimum absolute difference.
 */
public class Solution {
    /**
     * Returns a list of pairs [a, b] such that:
     * <ul>
     *   <li>a &lt; b</li>
     *   <li>b - a is the minimum absolute difference among all pairs in {@code arr}</li>
     *   <li>The list is sorted in ascending order (first by a, then by b)</li>
     * </ul>
     *
     * @param arr an array of distinct integers
     * @return list of integer pairs with the minimum absolute difference
     */
    public List<List<Integer>> minimumAbsDifference(int[] arr) {
        // Sort the array so that the closest numbers become neighbours
        Arrays.sort(arr);

        // First pass: determine the smallest difference
        int minDiff = Integer.MAX_VALUE;
        for (int i = 1; i < arr.length; i++) {
            int diff = arr[i] - arr[i - 1];
            if (diff < minDiff) {
                minDiff = diff;
            }
        }

        // Second pass: collect all pairs that have this smallest difference
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 1; i < arr.length; i++) {
            int diff = arr[i] - arr[i - 1];
            if (diff == minDiff) {
                List<Integer> pair = new ArrayList<>(2);
                pair.add(arr[i - 1]);
                pair.add(arr[i]);
                result.add(pair);
            }
        }

        return result;
    }
}

