import java.util.*;

public class Solution {
    public int[] relativeSortArray(int[] arr1, int[] arr2) {
        // Determine the maximum value to size the counting array efficiently
        int max = 0;
        for (int num : arr1) {
            if (num > max) {
                max = num;
            }
        }
        // Counting sort array
        int[] count = new int[max + 1];
        for (int num : arr1) {
            count[num]++;
        }

        int[] result = new int[arr1.length];
        int idx = 0;

        // Place elements according to the order in arr2
        for (int num : arr2) {
            while (count[num] > 0) {
                result[idx++] = num;
                count[num]--;
            }
        }

        // Place remaining elements in ascending order
        for (int i = 0; i < count.length; i++) {
            while (count[i] > 0) {
                result[idx++] = i;
                count[i]--;
            }
        }

        return result;
    }
}

