import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public String reverseParentheses(String s) {
        Deque<StringBuilder> stack = new ArrayDeque<>();
        // Base builder for the final result
        stack.push(new StringBuilder());

        for (char ch : s.toCharArray()) {
            if (ch == '(') {
                // Start a new inner segment
                stack.push(new StringBuilder());
            } else if (ch == ')') {
                // End of current segment: reverse it and append to previous level
                StringBuilder current = stack.pop();
                current.reverse();
                stack.peek().append(current);
            } else {
                // Regular character, add to current segment
                stack.peek().append(ch);
            }
        }

        // The remaining builder contains the answer without any parentheses
        return stack.peek().toString();
    }
}

