import java.util.Collections;
import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> path = new LinkedList<>();
        while (label > 0) {
            path.add(label);
            // determine the level (1‑based) of the current label
            int level = (int) (Math.floor(Math.log(label) / Math.log(2))) + 1;
            // compute the minimum and maximum label of this level in a normal binary tree
            long min = 1L << (level - 1);
            long max = (1L << level) - 1;
            // convert the current zigzag label to the corresponding normal label,
            // then move to its parent (which is in normal order)
            label = (int) ((max + min - label) / 2);
        }
        Collections.reverse(path);
        return path;
    }
}

