import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public List<Integer> findNumOfValidWords(String[] words, String[] puzzles) {
        // Map each word mask to its frequency (ignore words with >7 distinct letters)
        Map<Integer, Integer> wordCount = new HashMap<>();
        for (String word : words) {
            int mask = 0;
            for (int i = 0; i < word.length(); i++) {
                mask |= 1 << (word.charAt(i) - 'a');
            }
            // If a word uses more than 7 distinct letters it can never match any puzzle
            if (Integer.bitCount(mask) <= 7) {
                wordCount.put(mask, wordCount.getOrDefault(mask, 0) + 1);
            }
        }

        List<Integer> answer = new ArrayList<>(puzzles.length);
        for (String puzzle : puzzles) {
            int firstBit = 1 << (puzzle.charAt(0) - 'a');

            // mask of the remaining six letters
            int maskWithoutFirst = 0;
            for (int i = 1; i < puzzle.length(); i++) {
                maskWithoutFirst |= 1 << (puzzle.charAt(i) - 'a');
            }

            int total = 0;
            // Enumerate all subsets of the six letters
            int sub = maskWithoutFirst;
            while (true) {
                int candidateMask = sub | firstBit;
                total += wordCount.getOrDefault(candidateMask, 0);
                if (sub == 0) {
                    break;
                }
                sub = (sub - 1) & maskWithoutFirst;
            }
            answer.add(total);
        }
        return answer;
    }
}

