public class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }
        int m = grid.length;
        int n = grid[0].length;

        // hor[i][j] = number of consecutive 1's to the left ending at (i,j)
        // ver[i][j] = number of consecutive 1's upward ending at (i,j)
        int[][] hor = new int[m][n];
        int[][] ver = new int[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    hor[i][j] = (j > 0 ? hor[i][j - 1] : 0) + 1;
                    ver[i][j] = (i > 0 ? ver[i - 1][j] : 0) + 1;
                } else {
                    hor[i][j] = 0;
                    ver[i][j] = 0;
                }
            }
        }

        int maxSide = 0;

        // iterate over each cell as bottom‑right corner of a square
        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                // the largest possible side length with (i,j) as bottom‑right
                int possibleSide = Math.min(hor[i][j], ver[i][j]);
                while (possibleSide > maxSide) {
                    // top‑left corner of the candidate square
                    int topRow = i - possibleSide + 1;
                    int leftCol = j - possibleSide + 1;
                    if (topRow < 0 || leftCol < 0) {
                        possibleSide--;
                        continue;
                    }
                    // check the other two borders
                    if (hor[topRow][j] >= possibleSide && ver[i][leftCol] >= possibleSide) {
                        maxSide = possibleSide;
                        break; // no need to try smaller sizes for this cell
                    }
                    possibleSide--;
                }
            }
        }

        return maxSide * maxSide;
    }
}

