public class Solution {
    public int longestDecomposition(String text) {
        int n = text.length();
        int left = 0;
        int right = n - 1;
        int count = 0;

        while (left < right) {
            int i = left;
            int j = right;
            boolean found = false;

            // expand the left part until it matches the right part
            while (i < j) {
                String leftPart = text.substring(left, i + 1);
                String rightPart = text.substring(j, right + 1);
                if (leftPart.equals(rightPart)) {
                    // we found a matching pair
                    count += 2;
                    left = i + 1;
                    right = j - 1;
                    found = true;
                    break;
                }
                i++;
                j--;
            }

            // no more matching pairs can be formed
            if (!found) {
                break;
            }
        }

        // any remaining middle part (including empty) contributes at most one piece
        if (left <= right) {
            count += 1;
        }

        return count;
    }
}

