import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    // red -> 0, blue -> 1
    public int[] shortestAlternatingPaths(int n, int[][] redEdges, int[][] blueEdges) {
        // adjacency lists for red and blue edges
        List<Integer>[] redAdj = new ArrayList[n];
        List<Integer>[] blueAdj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            redAdj[i] = new ArrayList<>();
            blueAdj[i] = new ArrayList<>();
        }
        for (int[] e : redEdges) {
            redAdj[e[0]].add(e[1]);
        }
        for (int[] e : blueEdges) {
            blueAdj[e[0]].add(e[1]);
        }

        int[][] dist = new int[n][2]; // dist[node][color]
        for (int i = 0; i < n; i++) {
            dist[i][0] = dist[i][1] = Integer.MAX_VALUE;
        }
        // start from node 0 with both colors (distance 0)
        dist[0][0] = 0;
        dist[0][1] = 0;

        Queue<int[]> q = new LinkedList<>();
        // {node, lastColor}
        q.offer(new int[]{0, 0}); // pretend we arrived via red
        q.offer(new int[]{0, 1}); // pretend we arrived via blue

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int node = cur[0];
            int lastColor = cur[1];
            int curDist = dist[node][lastColor];

            // next edges must be of opposite color
            if (lastColor == 0) { // last was red, take blue edges
                for (int nb : blueAdj[node]) {
                    if (dist[nb][1] > curDist + 1) {
                        dist[nb][1] = curDist + 1;
                        q.offer(new int[]{nb, 1});
                    }
                }
            } else { // last was blue, take red edges
                for (int nb : redAdj[node]) {
                    if (dist[nb][0] > curDist + 1) {
                        dist[nb][0] = curDist + 1;
                        q.offer(new int[]{nb, 0});
                    }
                }
            }
        }

        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            int best = Math.min(dist[i][0], dist[i][1]);
            answer[i] = (best == Integer.MAX_VALUE) ? -1 : best;
        }
        return answer;
    }
}

