import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int countCharacters(String[] words, String chars) {
        // Build frequency map for chars
        Map<Character, Integer> charCount = new HashMap<>();
        for (char c : chars.toCharArray()) {
            charCount.put(c, charCount.getOrDefault(c, 0) + 1);
        }

        int totalLength = 0;

        // Check each word
        for (String word : words) {
            if (canForm(word, charCount)) {
                totalLength += word.length();
            }
        }

        return totalLength;
    }

    private boolean canForm(String word, Map<Character, Integer> baseCount) {
        // Create a copy of the base map to track usage for this word
        Map<Character, Integer> tempCount = new HashMap<>(baseCount);
        for (char c : word.toCharArray()) {
            Integer remaining = tempCount.get(c);
            if (remaining == null || remaining == 0) {
                return false; // character not available enough times
            }
            tempCount.put(c, remaining - 1);
        }
        return true;
    }
}

