public class Solution {
    /**
     * Returns the maximum value of
     * |arr1[i] - arr1[j]| + |arr2[i] - arr2[j]| + |i - j|
     * over all pairs (i, j).
     *
     * @param arr1 first integer array
     * @param arr2 second integer array (same length as arr1)
     * @return the maximum expression value
     */
    public int maxAbsValExpr(int[] arr1, int[] arr2) {
        int n = arr1.length;
        // Initialize min and max for the four transformed expressions
        int min1 = Integer.MAX_VALUE, max1 = Integer.MIN_VALUE;
        int min2 = Integer.MAX_VALUE, max2 = Integer.MIN_VALUE;
        int min3 = Integer.MAX_VALUE, max3 = Integer.MIN_VALUE;
        int min4 = Integer.MAX_VALUE, max4 = Integer.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            int a = arr1[i];
            int b = arr2[i];

            int v1 = a + b + i; // (+,+,+)
            int v2 = a + b - i; // (+,+,-)
            int v3 = a - b + i; // (+,-,+)
            int v4 = a - b - i; // (+,-,-)

            if (v1 < min1) min1 = v1;
            if (v1 > max1) max1 = v1;

            if (v2 < min2) min2 = v2;
            if (v2 > max2) max2 = v2;

            if (v3 < min3) min3 = v3;
            if (v3 > max3) max3 = v3;

            if (v4 < min4) min4 = v4;
            if (v4 > max4) max4 = v4;
        }

        int ans = Math.max(max1 - min1,
                  Math.max(max2 - min2,
                  Math.max(max3 - min3,
                           max4 - min4)));
        return ans;
    }
}

