public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] distribution = new int[numPeople];
        int give = 1;               // amount to give in the current step
        int index = 0;              // current person index

        while (candies > 0) {
            int actualGive = Math.min(give, candies);
            distribution[index] += actualGive;
            candies -= actualGive;

            // move to next person and increase the amount for the next step
            index = (index + 1) % numPeople;
            give++;
        }

        return distribution;
    }
}

