            wordFreq[i] = smallestCharFrequency(words[i]);
        }
        // Sort frequencies to enable binary search
        Arrays.sort(wordFreq);

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int qFreq = smallestCharFrequency(queries[i]);
            int idx = upperBound(wordFreq, qFreq); // first index with value > qFreq
            answer[i] = wordFreq.length - idx;
        }
        return answer;
    }

    // Frequency of the lexicographically smallest character in s
    private int smallestCharFrequency(String s) {
        char minChar = Character.MAX_VALUE;
        int count = 0;
        for (char c : s.toCharArray()) {
            if (c < minChar) {
                minChar = c;
                count = 1;
            } else if (c == minChar) {
                count++;
            }
        }
        return count;
    }

    // Upper bound: first index where arr[idx] > target
    private int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

