public class Solution {
    public String alphabetBoardPath(String target) {
        StringBuilder sb = new StringBuilder();
        int curRow = 0, curCol = 0;
        for (char ch : target.toCharArray()) {
            int idx = ch - 'a';
            int targetRow = idx / 5;
            int targetCol = idx % 5;

            // move left first
            while (curCol > targetCol) {
                sb.append('L');
                curCol--;
            }
            // move up next
            while (curRow > targetRow) {
                sb.append('U');
                curRow--;
            }
            // move down
            while (curRow < targetRow) {
                sb.append('D');
                curRow++;
            }
            // move right
            while (curCol < targetCol) {
                sb.append('R');
                curCol++;
            }
            // add the character
            sb.append('!');
        }
        return sb.toString();
    }
}

