import java.util.HashMap;
import java.util.Map;

/**
 * Definition for singly‑linked list node.
 */
public class Solution {

    /**
     * List node definition.
     */
    public static class ListNode {
        int val;
        ListNode next;

        public ListNode() {
        }

        public ListNode(int val) {
            this.val = val;
        }

        public ListNode(int val, ListNode next) {
            this.val = val;
            this.next = next;
        }
    }

    /**
     * Removes all consecutive sequences of nodes that sum to 0 from the linked list.
     *
     * @param head the head of the input linked list
     * @return the head of the linked list after all zero‑sum sub‑lists have been removed
     */
    public ListNode removeZeroSumSublists(ListNode head) {
        // Dummy node simplifies handling of head deletions
        ListNode dummy = new ListNode(0);
        dummy.next = head;

        // First pass: map each prefix sum to its last occurrence node
        Map<Integer, ListNode> prefixMap = new HashMap<>();
        int sum = 0;
        for (ListNode node = dummy; node != null; node = node.next) {
            sum += node.val;
            prefixMap.put(sum, node);
        }

        // Second pass: skip over zero‑sum sub‑lists using the map
        sum = 0;
        for (ListNode node = dummy; node != null; node = node.next) {
            sum += node.val;
            ListNode farNode = prefixMap.get(sum);
            if (farNode != node) {
                node.next = farNode.next;
            }
        }

        return dummy.next;
    }
}

