import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public String kthLargestNumber(String[] nums, int k) {
        // Sort the array in descending order based on numeric value.
        // Comparison is done first by length (longer string = larger number),
        // then lexicographically when lengths are equal.
        Arrays.sort(nums, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                if (a.length() != b.length()) {
                    // longer string should come first
                    return b.length() - a.length();
                }
                // same length: compare lexicographically
                return b.compareTo(a);
            }
        });
        // k is 1‑based, array index is 0‑based
        return nums[k - 1];
    }
}

