import java.util.*;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        // Convert the array of subset sums to a mutable list and sort it.
        List<Integer> sumList = new ArrayList<>(sums.length);
        for (int s : sums) {
            sumList.add(s);
        }
        Collections.sort(sumList);

        // Recover the original array.
        List<Integer> result = new ArrayList<>(n);
        recover(n, sumList, result);

        // Build the answer array.
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            ans[i] = result.get(i);
        }
        return ans;
    }

    private boolean recover(int n, List<Integer> sums, List<Integer> result) {
        if (n == 0) {
            return true;
        }

        // The smallest sum is the sum of all negative numbers.
        // Find the first sum that is larger than the smallest one.
        int base = sums.get(0);
        int idx = 1;
        while (idx < sums.size() && sums.get(idx) == base) {
            idx++;
        }

        // If every sum is the same, the remaining elements are all zero.
        int diff = (idx == sums.size()) ? 0 : sums.get(idx) - base;

        // Try both possible signs of the candidate element.
        if (tryRecover(diff, n, sums, result)) {
            return true;
        }
        return tryRecover(-diff, n, sums, result);
    }

    private boolean tryRecover(int x, int n, List<Integer> sums, List<Integer> result) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int v : sums) {
            cnt.put(v, cnt.getOrDefault(v, 0) + 1);
        }

        List<Integer> without = new ArrayList<>(sums.size() / 2);

        if (x >= 0) {
            // forward iteration (small -> large)
            for (int v : sums) {
                if (cnt.getOrDefault(v, 0) == 0) {
                    continue;
                }
                without.add(v);
                cnt.put(v, cnt.get(v) - 1);

                int target = v + x;
                if (cnt.getOrDefault(target, 0) == 0) {
                    return false;
                }
                cnt.put(target, cnt.get(target) - 1);
            }
        } else {
            // backward iteration (large -> small)
            for (int i = sums.size() - 1; i >= 0; i--) {
                int v = sums.get(i);
                if (cnt.getOrDefault(v, 0) == 0) {
                    continue;
                }
                without.add(v);
                cnt.put(v, cnt.get(v) - 1);

                int target = v + x; // target < v
                if (cnt.getOrDefault(target, 0) == 0) {
                    return false;
                }
                cnt.put(target, cnt.get(target) - 1);
            }
        }

        Collections.sort(without);
        result.add(x);
        boolean ok = recover(n - 1, without, result);
        if (ok) {
            return true;
        }
        result.remove(result.size() - 1);
        return false;
    }
}

