public class Solution {
    public boolean canBeIncreasing(int[] nums) {
        int n = nums.length;
        // Arrays of length 2 or less are always possible
        if (n <= 2) {
            return true;
        }

        int violationIndex = -1;
        int violations = 0;

        for (int i = 1; i < n; i++) {
            if (nums[i] <= nums[i - 1]) {
                violations++;
                if (violations > 1) {
                    return false;
                }
                violationIndex = i;
            }
        }

        // No violations means already strictly increasing
        if (violations == 0) {
            return true;
        }

        // Exactly one violation at index 'violationIndex'
        // If the violation is at the start or end, removal always works
        if (violationIndex == 1 || violationIndex == n - 1) {
            return true;
        }

        // Check if removing nums[violationIndex] or nums[violationIndex - 1] fixes the sequence
        // Remove nums[violationIndex] -> need nums[violationIndex] > nums[violationIndex - 2]
        // Remove nums[violationIndex - 1] -> need nums[violationIndex + 1] > nums[violationIndex - 1]
        boolean removeCurrent = nums[violationIndex] > nums[violationIndex - 2];
        boolean removePrev = nums[violationIndex + 1] > nums[violationIndex - 1];

        return removeCurrent || removePrev;
    }
}

