import java.util.Collections;
import java.util.PriorityQueue;

public class Solution {
    public int minStoneSum(int[] piles, int k) {
        // Max‑heap to always pick the pile with the most stones
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        for (int pile : piles) {
            maxHeap.offer(pile);
        }

        // Perform exactly k operations
        for (int i = 0; i < k; i++) {
            int current = maxHeap.poll();               // largest pile
            int reduced = current - current / 2;        // remove floor(current/2) stones
            maxHeap.offer(reduced);
        }

        // Sum remaining stones
        int total = 0;
        while (!maxHeap.isEmpty()) {
            total += maxHeap.poll();
        }
        return total;
    }
}

