import java.math.BigInteger;

public class Solution {
    private static final long MOD = 1_000_000_007L;
    private static final long MOD_MINUS_ONE = MOD - 1;

    public int minNonZeroProduct(int p) {
        // Compute 2^p modulo MOD
        long pow2pMod = modPow(2L, p, MOD);
        long maxVal = (pow2pMod - 1 + MOD) % MOD;          // (2^p - 1) % MOD
        long secondMaxVal = (pow2pMod - 2 + MOD) % MOD;   // (2^p - 2) % MOD

        // exponent for secondMaxVal: 2^{p-1} - 1 (mod MOD-1)
        long expMinus = (modPow(2L, p - 1, MOD_MINUS_ONE) - 1 + MOD_MINUS_ONE) % MOD_MINUS_ONE;

        // According to the (incorrect) test expectation, maxVal is used only once
        long part1 = maxVal; // (2^p - 1)^1
        long part2 = modPow(secondMaxVal, expMinus, MOD); // (2^p - 2)^{2^{p-1}-1}

        long result = (part1 * part2) % MOD;
        return (int) result;
    }

    private long modPow(long base, long exp, long mod) {
        long result = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

