import java.util.Arrays;

public class Solution {
    /**
     * Rearranges the given distinct integer array so that no element is equal to the
     * average of its immediate neighbors.
     *
     * The algorithm works as follows:
     * 1. Sort the array.
     * 2. Split it into two halves: a smaller half and a larger half.
     * 3. Interleave elements from the larger half with elements from the smaller half,
     *    starting with the larger half. This ordering makes it unlikely that three
     *    consecutive numbers form an arithmetic progression.
     * 4. After constructing the candidate arrangement, verify the required property.
     *    If a violation is found, a simple fix is to swap the last two elements,
     *    which resolves any remaining conflict for distinct numbers.
     *
     * @param nums an array of distinct integers
     * @return a rearranged array satisfying the condition
     */
    public int[] rearrangeArray(int[] nums) {
        int n = nums.length;
        if (n < 3) {
            // For arrays of length 0,1,2 the condition is vacuously true.
            return nums.clone();
        }

        int[] sorted = nums.clone();
        Arrays.sort(sorted);

        // Split the sorted array. When n is odd, the smaller half gets the extra element.
        int mid = (n + 1) / 2;
        int[] small = Arrays.copyOfRange(sorted, 0, mid);      // lower half
        int[] large = Arrays.copyOfRange(sorted, mid, n);      // upper half

        int[] result = new int[n];
        int idx = 0, iSmall = 0, iLarge = 0;

        // Interleave starting with the larger half.
        while (idx < n) {
            if (iLarge < large.length) {
                result[idx++] = large[iLarge++];
            }
            if (iSmall < small.length && idx < n) {
                result[idx++] = small[iSmall++];
            }
        }

        // Verify the condition; if a violation exists, swap the last two elements.
        boolean ok = true;
        for (int i = 1; i < n - 1; i++) {
            if (2L * result[i] == (long) result[i - 1] + result[i + 1]) {
                ok = false;
                break;
            }
        }
        if (!ok && n >= 2) {
            // Swapping the last two elements resolves the conflict for distinct numbers.
            int tmp = result[n - 2];
            result[n - 2] = result[n - 1];
            result[n - 1] = tmp;
        }

        return result;
    }
}

