public class Solution {
    public long maxMatrixSum(int[][] matrix) {
        long totalAbs = 0L;
        int negativeCount = 0;
        int minAbs = Integer.MAX_VALUE;
        boolean hasZero = false;

        for (int[] row : matrix) {
            for (int val : row) {
                if (val == 0) {
                    hasZero = true;
                }
                if (val < 0) {
                    negativeCount++;
                }
                int absVal = Math.abs(val);
                totalAbs += absVal;
                if (absVal < minAbs) {
                    minAbs = absVal;
                }
            }
        }

        if (hasZero || negativeCount % 2 == 0) {
            return totalAbs;
        } else {
            return totalAbs - 2L * minAbs;
        }
    }
}

