public class Solution {
    public int eliminateMaximum(int[] dist, int[] speed) {
        int n = dist.length;
        long[] reachTimes = new long[n];
        for (int i = 0; i < n; i++) {
            // Compute the latest minute (0‑based) at which we can still eliminate this monster.
            // If the monster would arrive exactly at an integer minute, we lose before that minute,
            // so we subtract 1 before division.
            reachTimes[i] = (dist[i] - 1L) / (long) speed[i];
        }
        Arrays.sort(reachTimes);
        int eliminated = 0;
        for (int i = 0; i < n; i++) {
            // At minute i we can eliminate one monster.
            // If the monster would have arrived at or before minute i, we lose.
            if (reachTimes[i] < i) {
                break;
            }
            eliminated++;
        }
        return eliminated;
    }
}

