public class Solution {
    public int minSwaps(String s) {
        int balance = 0;          // current number of unmatched '[' minus ']'
        int maxDeficit = 0;       // maximum number of excess ']' encountered

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') {
                balance++;
            } else { // c == ']'
                balance--;
                if (balance < 0) {
                    // we have more closing brackets than opening ones up to this point
                    maxDeficit = Math.max(maxDeficit, -balance);
                }
            }
        }

        // Each swap can fix two positions of deficit, so the answer is ceil(maxDeficit / 2)
        return (maxDeficit + 1) / 2;
    }
}

