import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int numberOfUniqueGoodSubsequences(String binary) {
        if (binary == null || binary.isEmpty()) {
            return 0;
        }

        long total = 0;                 // total distinct good subsequences so far
        long[] last = new long[2];      // last contribution for '0' and '1'
        boolean hasZero = false;

        for (int i = 0; i < binary.length(); i++) {
            char ch = binary.charAt(i);
            int idx = ch - '0';
            if (idx == 0) {
                hasZero = true;
            }

            long add = (total + (idx == 1 ? 1 : 0) - last[idx]) % MOD;
            if (add < 0) {
                add += MOD;
            }

            // Update the last contribution for this character
            last[idx] = (total + (idx == 1 ? 1 : 0)) % MOD;

            total = (total + add) % MOD;
        }

        if (hasZero) {
            total = (total + 1) % MOD; // the single-character subsequence "0"
        }

        return (int) total;
    }
}

