import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int rows = grid.length;
        int cols = grid[0].length;
        int layers = Math.min(rows, cols) / 2;

        for (int layer = 0; layer < layers; layer++) {
            int top = layer;
            int left = layer;
            int bottom = rows - 1 - layer;
            int right = cols - 1 - layer;

            List<Integer> vals = new ArrayList<>();

            // top row (left -> right)
            for (int j = left; j <= right; j++) {
                vals.add(grid[top][j]);
            }
            // right column (top+1 -> bottom-1)
            for (int i = top + 1; i <= bottom - 1; i++) {
                vals.add(grid[i][right]);
            }
            // bottom row (right -> left)
            for (int j = right; j >= left; j--) {
                vals.add(grid[bottom][j]);
            }
            // left column (bottom-1 -> top+1)
            for (int i = bottom - 1; i >= top + 1; i--) {
                vals.add(grid[i][left]);
            }

            int len = vals.size();
            int rot = k % len; // counter‑clockwise rotation => left shift

            // rotate left by rot positions
            List<Integer> rotated = new ArrayList<>(len);
            for (int i = 0; i < len; i++) {
                rotated.add(vals.get((i + rot) % len));
            }

            // write back rotated values
            int idx = 0;
            for (int j = left; j <= right; j++) {
                grid[top][j] = rotated.get(idx++);
            }
            for (int i = top + 1; i <= bottom - 1; i++) {
                grid[i][right] = rotated.get(idx++);
            }
            for (int j = right; j >= left; j--) {
                grid[bottom][j] = rotated.get(idx++);
            }
            for (int i = bottom - 1; i >= top + 1; i--) {
                grid[i][left] = rotated.get(idx++);
            }
        }

        return grid;
    }
}

package referenz;

import java.util.*;

public class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.length; // number of students == number of mentors
        int[][] score = new int[m][m];
        // Pre‑compute compatibility scores for every student‑mentor pair
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int cnt = 0;
                for (int k = 0; k < students[i].length; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        cnt++;
                    }
                }
                score[i][j] = cnt;
            }
        }

        int totalMask = 1 << m;
        int[] dp = new int[totalMask];
        Arrays.fill(dp, -1);
        dp[0] = 0; // no assignments yet

        for (int mask = 0; mask < totalMask; mask++) {
            if (dp[mask] == -1) continue; // unreachable state
            int studentIdx = Integer.bitCount(mask); // next student to assign
            if (studentIdx >= m) continue;
            for (int mentor = 0; mentor < m; mentor++) {
                if ((mask & (1 << mentor)) == 0) { // mentor not yet used
                    int newMask = mask | (1 << mentor);
                    dp[newMask] = Math.max(dp[newMask], dp[mask] + score[studentIdx][mentor]);
                }
            }
        }

        return dp[totalMask - 1];
    }
}

package referenz;


import java.util.*;

public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] ans = new int[n];
        // tails will store the minimal possible tail for each length (1‑based index)
        List<Integer> tails = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int x = obstacles[i];
            int pos = upperBound(tails, x); // first element > x
            if (pos == tails.size()) {
                tails.add(x);
            } else {
                tails.set(pos, x);
            }
            ans[i] = pos + 1; // length is index+1
        }
        return ans;
    }

    // returns the index of the first element in list that is greater than key
    private int upperBound(List<Integer> list, int key) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) <= key) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

package referenz;


public class Solution {
    public int[] findPeakGrid(int[][] mat) {
        int rows = mat.length;
        int cols = mat[0].length;
        int left = 0;
        int right = cols - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            // Find the row index of the maximum element in column 'mid'
            int maxRow = 0;
            for (int i = 1; i < rows; i++) {
                if (mat[i][mid] > mat[maxRow][mid]) {
                    maxRow = i;
                }
            }

            int leftVal = (mid - 1 >= 0) ? mat[maxRow][mid - 1] : -1;
            int rightVal = (mid + 1 < cols) ? mat[maxRow][mid + 1] : -1;
            int curVal = mat[maxRow][mid];

            // Check if current element is a peak
            if (curVal > leftVal && curVal > rightVal) {
                return new int[]{maxRow, mid};
            }

            // Move search space towards the larger neighbor
            if (leftVal > curVal) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        // The problem guarantees a peak exists; this line should never be reached.
        return new int[]{0, 0};
    }
}

package referenz;


public class Solution {
    public int[] getConcatenation(int[] nums) {
        int n = nums.length;
        int[] ans = new int[2 * n];
        System.arraycopy(nums, 0, ans, 0, n);
        System.arraycopy(nums, 0, ans, n, n);
        return ans;
    }
}

package referenz;


public class Solution {
    public int maxProductDifference(int[] nums) {
        // Find the two largest numbers
        int max1 = Integer.MIN_VALUE, max2 = Integer.MIN_VALUE;
        // Find the two smallest numbers
        int min1 = Integer.MAX_VALUE, min2 = Integer.MAX_VALUE;

        for (int num : nums) {
            // Update max values
            if (num > max1) {
                max2 = max1;
                max1 = num;
            } else if (num > max2) {
                max2 = num;
            }

            // Update min values
            if (num < min1) {
                min2 = min1;
                min1 = num;
            } else if (num < min2) {
                min2 = num;
            }
        }

        long productMax = (long) max1 * max2;
        long productMin = (long) min1 * min2;
        return (int) (productMax - productMin);
    }
}
